insert into activities (id, domain, age_band, title, why, duration_minutes, duration_label, materials, instructions) values
  ('chest-tummy-time-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Chest Tummy Time', 'Place baby face-down on your bare chest at a 45° recline. Get face-to-face — your face is their strongest motivation to lift their head.', 4, '2–5 min', 'None', 'Place baby face-down on your bare chest at a 45° recline. Get face-to-face — your face is their strongest motivation to lift their head.'),
  ('floor-tummy-time-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Floor Tummy Time', 'Lay baby face-down on a firm, clean surface. Place a rolled muslin under chest to ease the lift. Start 2 min and add 1 min per week.', 4, '2–5 min', 'Muslin cloth', 'Lay baby face-down on a firm, clean surface. Place a rolled muslin under chest to ease the lift. Start 2 min and add 1 min per week.'),
  ('bicycle-legs-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Bicycle Legs', 'Lay baby on back; hold ankles gently and move legs in slow cycling motions. Say ''pedal, pedal'' rhythmically while maintaining eye contact.', 4, '3–5 min', 'None', 'Lay baby on back; hold ankles gently and move legs in slow cycling motions. Say ''pedal, pedal'' rhythmically while maintaining eye contact.'),
  ('arm-stretch-midline-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Arm Stretch & Midline', 'Gently hold baby''s forearms, slowly extend arms outward, then bring hands together at midline over chest. Repeat 5 times each side.', 4, '3–5 min', 'None', 'Gently hold baby''s forearms, slowly extend arms outward, then bring hands together at midline over chest. Repeat 5 times each side.'),
  ('visual-tracking-card-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Visual Tracking Card', 'Hold a high-contrast B&W card 25 cm from baby''s face. Move it slowly left then right. Let eyes find it before you move again.', 4, '3–5 min', 'Paper with B&W pattern', 'Hold a high-contrast B&W card 25 cm from baby''s face. Move it slowly left then right. Let eyes find it before you move again.'),
  ('supported-upright-hold-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Supported Upright Hold', 'Hold baby upright against your shoulder and let them practice holding their head for 10–15 seconds. Support gently — don''t grip.', 4, '3–5 min', 'None', 'Hold baby upright against your shoulder and let them practice holding their head for 10–15 seconds. Support gently — don''t grip.'),
  ('leg-kicking-scarf-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Leg Kicking Scarf', 'Hold a light scarf 15 cm above baby''s feet while they lie on back. Let them discover kicking makes it move — first cause-effect feedback.', 8, '5–10 min', 'Light scarf or cloth', 'Hold a light scarf 15 cm above baby''s feet while they lie on back. Let them discover kicking makes it move — first cause-effect feedback.'),
  ('side-lying-practice-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Side-Lying Practice', 'Place baby on their side with a rolled towel tucked behind their back for support. Alternate sides each session; 5 min per side.', 8, '5–10 min', 'Rolled towel', 'Place baby on their side with a rolled towel tucked behind their back for support. Alternate sides each session; 5 min per side.'),
  ('finger-grasp-reflex-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Finger Grasp Reflex', 'Place your index finger in baby''s palm and let the grasp reflex close around it. Gently tug to stimulate the grip.', 4, '3–5 min', 'None', 'Place your index finger in baby''s palm and let the grasp reflex close around it. Gently tug to stimulate the grip.'),
  ('palm-massage-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Palm Massage', 'With warm hands make small circular motions across each palm and each finger. Open fisted hands gently with thumb-stroke wrist to fingertips.', 8, '5–10 min', 'Warm oil (optional)', 'With warm hands make small circular motions across each palm and each finger. Open fisted hands gently with thumb-stroke wrist to fingertips.'),
  ('hand-opening-stroke-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Hand Opening Stroke', 'When baby''s fists are clenched, gently stroke from wrist to fingertips along the back of the hand to encourage opening.', 4, '3–5 min', 'None', 'When baby''s fists are clenched, gently stroke from wrist to fingertips along the back of the hand to encourage opening.'),
  ('arm-to-midline-assist-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Arm-to-Midline Assist', 'Gently bring baby''s hands together at the centre of their chest. Hold 3 seconds, release. This builds bilateral brain coordination.', 4, '3–5 min', 'None', 'Gently bring baby''s hands together at the centre of their chest. Hold 3 seconds, release. This builds bilateral brain coordination.'),
  ('wrist-rotation-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Wrist Rotation', 'Hold baby''s forearm steady and gently rotate the wrist in small circles, 5 times each direction on each hand.', 4, '3–5 min', 'None', 'Hold baby''s forearm steady and gently rotate the wrist in small circles, 5 times each direction on each hand.'),
  ('soft-object-in-palm-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Soft Object in Palm', 'Place a small rolled cloth in baby''s palm. Note how long the grasp reflex holds it and whether they bring it toward their mouth.', 4, '3–5 min', 'Small soft cloth roll', 'Place a small rolled cloth in baby''s palm. Note how long the grasp reflex holds it and whether they bring it toward their mouth.'),
  ('narrate-every-routine-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Narrate Every Routine', 'Talk through every nappy change, feed, and bath. ''Now I''m lifting your legs. This might feel cool.'' Tone matters more than words.', null, 'Ongoing', 'None', 'Talk through every nappy change, feed, and bath. ''Now I''m lifting your legs. This might feel cool.'' Tone matters more than words.'),
  ('daily-lori-song-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Daily Lori / Song', 'Sing one consistent song at the same time each day. Repetition builds a neural safety pattern. Same song, same voice, every day.', 8, '5–10 min', 'None', 'Sing one consistent song at the same time each day. Repetition builds a neural safety pattern. Same song, same voice, every day.'),
  ('vowel-mirroring-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Vowel Mirroring', 'When baby makes any vowel sound, mirror it back exactly. Pause 10 full seconds before speaking again — that gap is the lesson.', 8, '5–10 min', 'None', 'When baby makes any vowel sound, mirror it back exactly. Pause 10 full seconds before speaking again — that gap is the lesson.'),
  ('serve-and-return-pause-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Serve and Return Pause', 'After speaking or making a sound, count to 10 silently before responding again. You are teaching conversation structure.', 8, '5–10 min', 'None', 'After speaking or making a sound, count to 10 silently before responding again. You are teaching conversation structure.'),
  ('name-recognition-distance-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Name Recognition Distance', 'Call baby''s name from 1 metre away (not from directly in front). Watch for eyes or head turning toward the sound.', 4, '3–5 min', 'None', 'Call baby''s name from 1 metre away (not from directly in front). Watch for eyes or head turning toward the sound.'),
  ('sound-exploration-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Sound Exploration', 'Introduce one new household sound daily: wooden spoon on pot, rustling paper, running water. Watch how baby stills and locates.', 4, '3–5 min', 'Household objects', 'Introduce one new household sound daily: wooden spoon on pot, rustling paper, running water. Watch how baby stills and locates.'),
  ('parentese-talk-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Parentese Talk', 'Use a slightly higher pitch and slower pace than normal when talking to baby. This is biologically optimal for infant language processing.', null, 'Ongoing', 'None', 'Use a slightly higher pitch and slower pace than normal when talking to baby. This is biologically optimal for infant language processing.'),
  ('read-aloud-any-text-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Read Aloud (Any Text)', 'Read any book, recipe, or message aloud to baby. The vocabulary range and rhythm matter — comprehension is irrelevant at this stage.', 8, '5–10 min', 'Any book or text', 'Read any book, recipe, or message aloud to baby. The vocabulary range and rhythm matter — comprehension is irrelevant at this stage.'),
  ('high-contrast-cards-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'High-Contrast Cards', 'Hold a black-and-white card 25 cm from baby''s face. Let them fixate 10 seconds before moving slowly left. Newborn vision peaks at this distance.', 4, '3–5 min', 'Paper with B&W pattern', 'Hold a black-and-white card 25 cm from baby''s face. Let them fixate 10 seconds before moving slowly left. Newborn vision peaks at this distance.'),
  ('face-gazing-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Face Gazing', 'Hold your face 20–30 cm from baby''s. Make one slow exaggerated expression and hold it. Wait 10 seconds for their response.', 7, '5–8 min', 'None', 'Hold your face 20–30 cm from baby''s. Make one slow exaggerated expression and hold it. Wait 10 seconds for their response.'),
  ('mirror-gazing-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Mirror Gazing', 'Hold a small unbreakable mirror 25 cm from baby. They won''t recognise themselves yet — but the responsive face is deeply engaging.', 4, '3–5 min', 'Any mirror', 'Hold a small unbreakable mirror 25 cm from baby. They won''t recognise themselves yet — but the responsive face is deeply engaging.'),
  ('disappearing-face-peek-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Disappearing Face Peek', 'Cover your face with your hands. Hold 3 seconds. Reveal warmly. Very early object permanence and social anticipation practice.', 8, '5–10 min', 'None', 'Cover your face with your hands. Hold 3 seconds. Reveal warmly. Very early object permanence and social anticipation practice.'),
  ('light-and-shadow-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Light and Shadow', 'Carry baby toward a window or lamp. Let them observe light change as you move closer and further. Narrate: ''Bright! Now darker.''', 4, '3–5 min', 'Window or lamp', 'Carry baby toward a window or lamp. Let them observe light change as you move closer and further. Narrate: ''Bright! Now darker.'''),
  ('b-w-pattern-book-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'B&W Pattern Book', 'Hold a high-contrast picture book 25 cm from baby. Spend 20–30 seconds on each page before turning. One page can hold attention this age.', 7, '5–8 min', 'High-contrast book or printed pages', 'Hold a high-contrast picture book 25 cm from baby. Spend 20–30 seconds on each page before turning. One page can hold attention this age.'),
  ('skin-to-skin-hold-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Skin-to-Skin Hold', 'Undress baby to nappy and hold against bare chest tummy-to-tummy. Cover both lightly. Regulates temperature, cortisol, and heart rate.', 23, '15–30 min', 'None', 'Undress baby to nappy and hold against bare chest tummy-to-tummy. Cover both lightly. Regulates temperature, cortisol, and heart rate.'),
  ('smile-mirroring-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Smile Mirroring', 'When baby makes a mouth movement or social smile, reflect it back immediately and wait. You are teaching: my expression has social power.', 8, '5–10 min', 'None', 'When baby makes a mouth movement or social smile, reflect it back immediately and wait. You are teaching: my expression has social power.'),
  ('responsive-holding-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Responsive Holding', 'When baby cries, respond before escalation. Consistent early response builds the secure attachment base for all future relationships.', null, 'Ongoing', 'None', 'When baby cries, respond before escalation. Consistent early response builds the secure attachment base for all future relationships.'),
  ('emotional-narration-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Emotional Narration', 'Name what you see: ''You look uncomfortable. Let me see what''s wrong.'' Labelling emotional states builds the circuits for self-regulation later.', null, 'Ongoing', 'None', 'Name what you see: ''You look uncomfortable. Let me see what''s wrong.'' Labelling emotional states builds the circuits for self-regulation later.'),
  ('caregiver-rotation-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Caregiver Rotation', 'Let each main caregiver hold baby skin-to-skin. Each person''s unique warmth and heartbeat is a distinct and valuable regulatory experience.', 18, '15–20 min', 'None', 'Let each main caregiver hold baby skin-to-skin. Each person''s unique warmth and heartbeat is a distinct and valuable regulatory experience.'),
  ('calm-modelling-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Calm Modelling', 'When you feel anxious, slow your own breathing while holding baby. They sense and entrain to your nervous system state.', 8, '5–10 min', 'None', 'When you feel anxious, slow your own breathing while holding baby. They sense and entrain to your nervous system state.'),
  ('tel-maalish-oil-massage-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Tel Maalish (Oil Massage)', 'Warm oil in palms. Begin with legs — least sensitive. Long slow strokes hip to foot, then arms, back, head. Stimulates vagus nerve.', 13, '10–15 min', 'Coconut or mustard oil', 'Warm oil in palms. Begin with legs — least sensitive. Long slow strokes hip to foot, then arms, back, head. Stimulates vagus nerve.'),
  ('texture-touch-exploration-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Texture Touch Exploration', 'Gently touch different textures to baby''s palm and feet: soft cloth, smooth wood, cool spoon. Name each: ''Soft. Smooth. Cool.''', 7, '5–8 min', 'Household objects with varied textures', 'Gently touch different textures to baby''s palm and feet: soft cloth, smooth wood, cool spoon. Name each: ''Soft. Smooth. Cool.'''),
  ('outdoor-air-light-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Outdoor Air & Light', 'Take baby outside for 10–15 min. Wind, natural light, birdsong, and temperature variation are multi-sensory inputs no indoor space can replicate.', 13, '10–15 min', 'None', 'Take baby outside for 10–15 min. Wind, natural light, birdsong, and temperature variation are multi-sensory inputs no indoor space can replicate.'),
  ('water-temperature-play-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Water Temperature Play', 'During bath, pour water at slightly different temperatures on hands. Narrate: ''Warm water now. A little cooler.''', 8, '5–10 min', 'Water in containers', 'During bath, pour water at slightly different temperatures on hands. Narrate: ''Warm water now. A little cooler.'''),
  ('chest-hum-vibration-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Chest Hum Vibration', 'Place baby against your chest and hum or sing. The physical vibration is felt across their whole body and is deeply calming.', 8, '5–10 min', 'None', 'Place baby against your chest and hum or sing. The physical vibration is felt across their whole body and is deeply calming.'),
  ('hunger-cue-recognition-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Hunger Cue Recognition', 'Learn early hunger cues: rooting, hand-to-mouth, stirring. Feed before crying. Responding to early cues builds baby''s signal-response trust.', null, 'Ongoing', 'None', 'Learn early hunger cues: rooting, hand-to-mouth, stirring. Feed before crying. Responding to early cues builds baby''s signal-response trust.'),
  ('wake-window-awareness-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Wake Window Awareness', 'Track awake time: 0–6 weeks = 45–60 min; 6–12 weeks = 60–90 min. Beginning sleep routine before overtiredness sets in improves settling.', null, 'Ongoing', 'None', 'Track awake time: 0–6 weeks = 45–60 min; 6–12 weeks = 60–90 min. Beginning sleep routine before overtiredness sets in improves settling.'),
  ('tummy-time-toy-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Tummy Time + Toy', 'Place an interesting toy just out of reach during tummy time. The motivation to lift and reach makes effort more sustained.', 8, '5–10 min', 'Small toy or crinkle paper', 'Place an interesting toy just out of reach during tummy time. The motivation to lift and reach makes effort more sustained.'),
  ('rolling-facilitation-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Rolling Facilitation', 'In tummy time, gently rock baby''s hips toward one side. Give the nervous system the sensation of weight transfer needed for rolling.', 8, '5–10 min', 'None', 'In tummy time, gently rock baby''s hips toward one side. Give the nervous system the sensation of weight transfer needed for rolling.'),
  ('floor-roll-practice-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Floor Roll Practice', 'Place baby on their back. Gently cross one leg over the other and let momentum encourage rolling to the side. Celebrate any attempt.', 7, '5–8 min', 'None', 'Place baby on their back. Gently cross one leg over the other and let momentum encourage rolling to the side. Celebrate any attempt.'),
  ('supported-sitting-lap-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Supported Sitting (Lap)', 'Sit baby on your lap facing outward, hands loosely around their trunk. Let them feel the work — don''t over-support.', 6, '3–8 min', 'None', 'Sit baby on your lap facing outward, hands loosely around their trunk. Let them feel the work — don''t over-support.'),
  ('forearm-weight-bearing-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Forearm Weight Bearing', 'In tummy time, once baby pushes up on forearms, gently rock their hips side to side. This is the direct predecessor of rolling.', 8, '5–10 min', 'None', 'In tummy time, once baby pushes up on forearms, gently rock their hips side to side. This is the direct predecessor of rolling.'),
  ('leg-press-against-hands-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Leg Press Against Hands', 'Hold your palms against baby''s feet while they lie on back. Let them push — this activates leg extensors used later for standing.', 7, '5–8 min', 'None', 'Hold your palms against baby''s feet while they lie on back. Let them push — this activates leg extensors used later for standing.'),
  ('bounce-on-lap-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Bounce on Lap', 'Hold baby upright on your lap, supporting under arms, and let them bounce slightly. Vestibular input and leg strength combined.', 4, '3–5 min', 'None', 'Hold baby upright on your lap, supporting under arms, and let them bounce slightly. Vestibular input and leg strength combined.'),
  ('tummy-time-mirror-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Tummy Time Mirror', 'Prop an unbreakable mirror in front of baby during tummy time. Their own face is one of the strongest motivators to lift the head.', 8, '5–10 min', 'Any mirror', 'Prop an unbreakable mirror in front of baby during tummy time. Their own face is one of the strongest motivators to lift the head.'),
  ('reach-for-hanging-object-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Reach for Hanging Object', 'Hang a lightweight object (cloth, spoon) just above baby''s chest while they lie on back. Wait — let them discover swiping makes it move.', 8, '5–10 min', 'Cloth, ribbon, or spoon on string', 'Hang a lightweight object (cloth, spoon) just above baby''s chest while they lie on back. Wait — let them discover swiping makes it move.'),
  ('two-handed-grasp-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Two-Handed Grasp', 'Offer a toy wider than one hand. Watch whether they use both hands together — bilateral integration milestone appearing around 4–5 months.', 8, '5–10 min', 'Wide rattle or soft ring', 'Offer a toy wider than one hand. Watch whether they use both hands together — bilateral integration milestone appearing around 4–5 months.'),
  ('object-transfer-observation-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Object Transfer Observation', 'Give a toy in one hand, then offer a second near the other. Do they transfer the first, or hold both? Transfer appears around 5–6 months.', 8, '5–10 min', 'Two small soft objects', 'Give a toy in one hand, then offer a second near the other. Do they transfer the first, or hold both? Transfer appears around 5–6 months.'),
  ('shake-and-listen-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Shake and Listen', 'Hand baby a small container with dried lentils inside. Let them discover shaking makes sound — first voluntary cause-effect action.', 8, '5–10 min', 'Sealed container with lentils', 'Hand baby a small container with dried lentils inside. Let them discover shaking makes sound — first voluntary cause-effect action.'),
  ('crinkle-paper-explore-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Crinkle Paper Explore', 'Give a piece of crinkled paper or foil (supervised). The sound, texture, and visual feedback engage three senses simultaneously.', 8, '5–10 min', 'Baking paper or foil', 'Give a piece of crinkled paper or foil (supervised). The sound, texture, and visual feedback engage three senses simultaneously.'),
  ('palm-pressure-exploration-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Palm Pressure Exploration', 'Press a textured surface gently against baby''s palm — a mesh bag, rough towel, smooth cup. The hand''s sensory map is being built now.', 8, '5–10 min', 'Various textured household surfaces', 'Press a textured surface gently against baby''s palm — a mesh bag, rough towel, smooth cup. The hand''s sensory map is being built now.'),
  ('babble-echo-session-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Babble Echo Session', 'When baby coos or babbles, echo it back exactly. Then add one new syllable: ''ooh… and then… ba?'' Pause 10 seconds each time.', 8, '5–10 min', 'None', 'When baby coos or babbles, echo it back exactly. Then add one new syllable: ''ooh… and then… ba?'' Pause 10 seconds each time.'),
  ('laugh-trigger-search-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Laugh Trigger Search', 'Try raspberry sounds, sudden peekaboo, lifting gently in the air. The belly laugh — appearing around 3–4 months — is a major milestone.', 8, '5–10 min', 'None', 'Try raspberry sounds, sudden peekaboo, lifting gently in the air. The belly laugh — appearing around 3–4 months — is a major milestone.'),
  ('consonant-introduction-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Consonant Introduction', 'Model ba-ba-ba, ma-ma-ma, da-da-da during alert windows. These are the first consonants baby will produce at 5–6 months.', 7, '5–8 min', 'None', 'Model ba-ba-ba, ma-ma-ma, da-da-da during alert windows. These are the first consonants baby will produce at 5–6 months.'),
  ('two-language-narration-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Two-Language Narration', 'Speak in two languages fluidly during routines. ''Now we''re washing your hands — haath dho rahe hain.'' Bilingual input from birth is a gift.', null, 'Ongoing', 'None', 'Speak in two languages fluidly during routines. ''Now we''re washing your hands — haath dho rahe hain.'' Bilingual input from birth is a gift.'),
  ('name-to-face-link-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Name-to-Face Link', 'Point to each family member and say their name slowly. ''This is Dadi. Dadi.'' Repetition over weeks builds face-name recognition.', 4, '3–5 min', 'None', 'Point to each family member and say their name slowly. ''This is Dadi. Dadi.'' Repetition over weeks builds face-name recognition.'),
  ('music-variety-session-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Music Variety Session', 'Play a different musical genre each day this week — classical, folk, jazz, film songs. Varied sound builds auditory discrimination.', 8, '5–10 min', 'Phone or any music source', 'Play a different musical genre each day this week — classical, folk, jazz, film songs. Varied sound builds auditory discrimination.'),
  ('respond-to-name-moving-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Respond to Name — Moving', 'Call baby''s name from different positions: behind, left, right. Turn-to-name appearing consistently by 6 months is a key milestone.', 4, '3–5 min', 'None', 'Call baby''s name from different positions: behind, left, right. Turn-to-name appearing consistently by 6 months is a key milestone.'),
  ('pause-in-song-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Pause in Song', 'Sing a familiar song and stop mid-verse. Wait. Watch baby''s face — anticipation appearing means they have learned the pattern.', 7, '5–8 min', 'None', 'Sing a familiar song and stop mid-verse. Wait. Watch baby''s face — anticipation appearing means they have learned the pattern.'),
  ('object-permanence-level-1-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Object Permanence Level 1', 'While baby watches, slowly hide your face behind a cloth or book. Wait 5 seconds. Reveal. Object permanence for faces is appearing now.', 7, '5–8 min', 'Cloth or book', 'While baby watches, slowly hide your face behind a cloth or book. Wait 5 seconds. Reveal. Object permanence for faces is appearing now.'),
  ('cause-effect-toy-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Cause-Effect Toy', 'Give baby a rattle. Let them discover that shaking = sound. When they look surprised after shaking, they have understood cause-effect.', 8, '5–10 min', 'Rattle or sealed container with lentils', 'Give baby a rattle. Let them discover that shaking = sound. When they look surprised after shaking, they have understood cause-effect.'),
  ('container-in-and-out-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Container In-and-Out', 'Show baby how to put an object into a bowl and take it out. Let them try. In-out schema is foundational for spatial reasoning.', 8, '5–10 min', 'Bowl and soft balls', 'Show baby how to put an object into a bowl and take it out. Let them try. In-out schema is foundational for spatial reasoning.'),
  ('look-where-i-point-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Look-Where-I-Point', 'Point at objects and then look at baby''s face — do they follow your point? Joint attention developing around 5–6 months.', 7, '5–8 min', 'None', 'Point at objects and then look at baby''s face — do they follow your point? Joint attention developing around 5–6 months.'),
  ('texture-comparison-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Texture Comparison', 'Give two very different textures simultaneously — smooth and rough. Let baby feel both and switch between them. Comparison is the lesson.', 7, '5–8 min', 'Two textured household items', 'Give two very different textures simultaneously — smooth and rough. Let baby feel both and switch between them. Comparison is the lesson.'),
  ('anticipatory-game-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Anticipatory Game', 'Do an action three times that baby enjoys — a raspberry, a bounce. On the fourth, pause before. Watch for anticipatory smile.', 8, '5–10 min', 'None', 'Do an action three times that baby enjoys — a raspberry, a bounce. On the fourth, pause before. Watch for anticipatory smile.'),
  ('social-smile-response-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Social Smile Response', 'Every time baby smiles, reflect it back immediately with warmth. Teaching: my positive emotion has social power. This builds communication.', null, 'Ongoing', 'None', 'Every time baby smiles, reflect it back immediately with warmth. Teaching: my positive emotion has social power. This builds communication.'),
  ('stranger-presence-practice-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Stranger Presence Practice', 'When a new person is present, hold baby and engage the person warmly yourself. Baby reads your calm as: this person is safe.', 8, '5–10 min', 'None', 'When a new person is present, hold baby and engage the person warmly yourself. Baby reads your calm as: this person is safe.'),
  ('protest-response-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Protest Response', 'When baby shows displeasure at a game stopping, restart it. Teaching: expressing a feeling produces a response. Foundation of communication.', 4, '3–5 min', 'None', 'When baby shows displeasure at a game stopping, restart it. Teaching: expressing a feeling produces a response. Foundation of communication.'),
  ('separation-practice-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Separation Practice', 'Step out of baby''s visual field for 30 seconds. Return before they cry. Gradually extend. Teaching: the person comes back.', 2, '1–3 min', 'None', 'Step out of baby''s visual field for 30 seconds. Return before they cry. Gradually extend. Teaching: the person comes back.'),
  ('emotional-vocabulary-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Emotional Vocabulary', 'Name emotions you see: ''You love that sound! Your face lit up.'' Accurate emotional labelling builds the brain''s emotional vocabulary.', null, 'Ongoing', 'None', 'Name emotions you see: ''You love that sound! Your face lit up.'' Accurate emotional labelling builds the brain''s emotional vocabulary.'),
  ('joint-attention-object-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Joint Attention Object', 'Hold up an interesting object and look between it and baby''s face — object, baby, object. This is joint attention, a language precursor.', 7, '5–8 min', 'Any interesting object', 'Hold up an interesting object and look between it and baby''s face — object, baby, object. This is joint attention, a language precursor.'),
  ('water-kicking-bath-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Water Kicking (Bath)', 'Let baby kick freely in the bath for 5 extra minutes. Water resistance builds leg strength while providing rich sensory feedback.', 13, '10–15 min', 'Water', 'Let baby kick freely in the bath for 5 extra minutes. Water resistance builds leg strength while providing rich sensory feedback.'),
  ('sensory-walk-held-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Sensory Walk (Held)', 'Walk outside slowly, narrating each sensory experience: ''That''s wind on your face. Listen — that''s a crow.'' Multi-sensory saturation.', 13, '10–15 min', 'None', 'Walk outside slowly, narrating each sensory experience: ''That''s wind on your face. Listen — that''s a crow.'' Multi-sensory saturation.'),
  ('varied-food-textures-intro-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Varied Food Textures (Intro)', 'If starting solids, introduce one very smooth purée at a time. Oral sensory exploration — taste and texture together — is its own skill.', 13, '10–15 min', 'Food (purée)', 'If starting solids, introduce one very smooth purée at a time. Oral sensory exploration — taste and texture together — is its own skill.'),
  ('dance-and-sway-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Dance and Sway', 'Hold baby and sway or dance to music with rhythm. Vestibular input plus auditory rhythm is two systems activating simultaneously.', 8, '5–10 min', 'Any music', 'Hold baby and sway or dance to music with rhythm. Vestibular input plus auditory rhythm is two systems activating simultaneously.'),
  ('temperature-contrast-hands-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Temperature Contrast Hands', 'Alternate placing a cool and slightly warm cloth against baby''s hands. Narrate each change. Temperature discrimination is developing.', 4, '3–5 min', 'Cloths at different temperatures', 'Alternate placing a cool and slightly warm cloth against baby''s hands. Narrate each change. Temperature discrimination is developing.'),
  ('feeding-cue-ritual-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Feeding Cue Ritual', 'Establish a consistent pre-feed sequence (dim lights, hold position, a specific phrase). Predictability regulates baby''s anticipatory state.', null, 'Ongoing', 'None', 'Establish a consistent pre-feed sequence (dim lights, hold position, a specific phrase). Predictability regulates baby''s anticipatory state.'),
  ('nap-cue-sequence-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Nap Cue Sequence', 'Same 3–4 steps before every nap: swaddle/sleep sack, darken room, white noise, feed. Consistent cues train the brain to prepare for sleep.', 13, '10–15 min', 'Swaddle or sleep sack', 'Same 3–4 steps before every nap: swaddle/sleep sack, darken room, white noise, feed. Consistent cues train the brain to prepare for sleep.'),
  ('sitting-balance-challenge-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Sitting Balance Challenge', 'Sit baby on firm surface. Place a toy slightly to the side so they must lean to reach. Each topple-and-catch is a core strength exercise.', 8, '5–10 min', 'Toy', 'Sit baby on firm surface. Place a toy slightly to the side so they must lean to reach. Each topple-and-catch is a core strength exercise.'),
  ('crawling-encouragement-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Crawling Encouragement', 'Place a desirable toy 50 cm in front of baby on the floor. Stay beside or behind — not in front — so they crawl away from you.', 8, '5–10 min', 'Toy', 'Place a desirable toy 50 cm in front of baby on the floor. Stay beside or behind — not in front — so they crawl away from you.'),
  ('all-fours-rocking-m7_9', 'motor'::domain, 'm7_9'::age_band, 'All-Fours Rocking', 'Place baby on hands and knees (support if needed). Place a toy just out of reach. Watch for rocking — the crawl motor pattern loading.', 8, '5–10 min', 'Toy', 'Place baby on hands and knees (support if needed). Place a toy just out of reach. Watch for rocking — the crawl motor pattern loading.'),
  ('obstacle-crawl-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Obstacle Crawl', 'Place a rolled blanket or sofa cushion in the crawl path. Watch whether baby navigates around or over it. Motor problem-solving.', 13, '10–15 min', 'Rolled blanket', 'Place a rolled blanket or sofa cushion in the crawl path. Watch whether baby navigates around or over it. Motor problem-solving.'),
  ('pull-to-stand-assisted-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Pull to Stand (Assisted)', 'Position baby next to a stable low piece of furniture. Place a toy on the surface above their head. Support at hips, not hands.', 8, '5–10 min', 'Low furniture + toy', 'Position baby next to a stable low piece of furniture. Place a toy on the surface above their head. Support at hips, not hands.'),
  ('pivot-in-tummy-time-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Pivot in Tummy Time', 'Place a toy at 45° from baby in tummy time. Watch them pivot their body to follow. This uses the same muscles as crawling.', 8, '5–10 min', 'Toy', 'Place a toy at 45° from baby in tummy time. Watch them pivot their body to follow. This uses the same muscles as crawling.'),
  ('walking-hold-two-hands-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Walking Hold (Two Hands)', 'Hold both of baby''s hands from behind and let them walk forward at their own pace. Alternate to one hand as confidence grows.', 8, '5–10 min', 'None', 'Hold both of baby''s hands from behind and let them walk forward at their own pace. Alternate to one hand as confidence grows.'),
  ('stair-climbing-supervised-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Stair Climbing (Supervised)', 'Let baby crawl up 2–3 safe stairs with you directly behind. Stair climbing builds strength, coordination, and spatial awareness.', 8, '5–10 min', 'Stairs', 'Let baby crawl up 2–3 safe stairs with you directly behind. Stair climbing builds strength, coordination, and spatial awareness.'),
  ('pincer-grasp-practice-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Pincer Grasp Practice', 'Place large puffed snacks or safe small objects on a tray. Watch how they pick up — raking grasp transitioning to pincer grasp.', 8, '5–10 min', 'Puffed snack or small safe object', 'Place large puffed snacks or safe small objects on a tray. Watch how they pick up — raking grasp transitioning to pincer grasp.'),
  ('object-in-container-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Object In Container', 'Give a large container and 4–5 objects. Let baby drop them in and dump them out repeatedly. Foundational spatial reasoning.', 8, '5–10 min', 'Bowl and soft objects', 'Give a large container and 4–5 objects. Let baby drop them in and dump them out repeatedly. Foundational spatial reasoning.'),
  ('banging-objects-together-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Banging Objects Together', 'Give two objects and demonstrate banging them together. When baby copies, bilateral motor coordination and cause-effect are both working.', 8, '5–10 min', 'Two safe household objects', 'Give two objects and demonstrate banging them together. When baby copies, bilateral motor coordination and cause-effect are both working.'),
  ('page-turning-board-book-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Page Turning (Board Book)', 'Offer a board book and let baby try to turn pages. Even clumsy turning is fine motor skill and book engagement combined.', 7, '5–8 min', 'Board book', 'Offer a board book and let baby try to turn pages. Even clumsy turning is fine motor skill and book engagement combined.'),
  ('stack-and-topple-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Stack and Topple', 'Stack 2 blocks, let baby knock them over. The knock is as developmental as the build — cause-effect with a satisfying outcome.', 8, '5–10 min', 'Blocks or similar stackable objects', 'Stack 2 blocks, let baby knock them over. The knock is as developmental as the build — cause-effect with a satisfying outcome.'),
  ('transfer-between-containers-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Transfer Between Containers', 'Show baby how to move an object from one bowl to another. This requires spatial planning and goal-directed motor action.', 8, '5–10 min', 'Two bowls + objects', 'Show baby how to move an object from one bowl to another. This requires spatial planning and goal-directed motor action.'),
  ('canonical-babbling-echo-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Canonical Babbling Echo', 'When baby produces ba-ba, da-da, or ma-ma, echo immediately and expand: ''Ba ba ba! And then — da da da?'' Pause 10 seconds.', 8, '5–10 min', 'None', 'When baby produces ba-ba, da-da, or ma-ma, echo immediately and expand: ''Ba ba ba! And then — da da da?'' Pause 10 seconds.'),
  ('respond-to-name-consistent-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Respond to Name (Consistent)', 'Test: call baby''s name from 2 m away in a normal voice. Consistent response by 9 months is a key language milestone.', 4, '3–5 min', 'None', 'Test: call baby''s name from 2 m away in a normal voice. Consistent response by 9 months is a key language milestone.'),
  ('gesture-introduction-wave-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Gesture Introduction (Wave)', 'Wave goodbye every single time anyone leaves. Every time, consistently. First gestural communication appears 8–10 months.', null, 'Ongoing', 'None', 'Wave goodbye every single time anyone leaves. Every time, consistently. First gestural communication appears 8–10 months.'),
  ('point-and-name-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Point and Name', 'Point at objects throughout the day and name them. When baby points at something, immediately name it and comment.', null, 'Ongoing', 'None', 'Point at objects throughout the day and name them. When baby points at something, immediately name it and comment.'),
  ('book-naming-session-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Book Naming Session', 'Board book: point to each picture, name it, wait 5 seconds. ''Woh kya hai? Haan — aam! Mango. Peela aam.'' Dual-language counts.', 8, '5–10 min', 'Board book', 'Board book: point to each picture, name it, wait 5 seconds. ''Woh kya hai? Haan — aam! Mango. Peela aam.'' Dual-language counts.'),
  ('simple-instruction-practice-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Simple Instruction Practice', 'Use consistent simple instructions with gesture: ''Come here'' + open arms. ''Give me'' + open hand. Gesture + word together.', null, 'Ongoing', 'None', 'Use consistent simple instructions with gesture: ''Come here'' + open arms. ''Give me'' + open hand. Gesture + word together.'),
  ('babble-conversation-record-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Babble Conversation Record', 'Record 2 minutes of serve-and-return babble conversation. Listen back — count how many turns baby takes. Target: 3+ by 9 months.', 8, '5–10 min', 'Phone for recording', 'Record 2 minutes of serve-and-return babble conversation. Listen back — count how many turns baby takes. Target: 3+ by 9 months.'),
  ('name-body-parts-touch-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Name Body Parts (Touch)', 'Touch each body part and name it while bathing or dressing. ''Yeh naak hai. Yeh haath.'' Touch plus name = dual encoding.', 8, '5–10 min', 'None', 'Touch each body part and name it while bathing or dressing. ''Yeh naak hai. Yeh haath.'' Touch plus name = dual encoding.'),
  ('object-permanence-under-cloth-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Object Permanence (Under Cloth)', 'Show baby an interesting toy. While they watch, hide it under a cloth. Say ''Kahaan gayi?'' Watch whether they search under the cloth.', 7, '5–8 min', 'Cloth and toy', 'Show baby an interesting toy. While they watch, hide it under a cloth. Say ''Kahaan gayi?'' Watch whether they search under the cloth.'),
  ('means-ends-pull-cloth-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Means-Ends: Pull Cloth', 'Place a toy on a cloth, toy out of reach but cloth within reach. Watch if baby pulls the cloth to get the toy — means-ends planning.', 7, '5–8 min', 'Cloth and toy', 'Place a toy on a cloth, toy out of reach but cloth within reach. Watch if baby pulls the cloth to get the toy — means-ends planning.'),
  ('cause-effect-button-toy-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Cause-Effect: Button Toy', 'Any toy that produces a response when pressed or moved. Systematic testing of what each element does is emerging scientific method.', 8, '5–10 min', 'Any cause-effect toy', 'Any toy that produces a response when pressed or moved. Systematic testing of what each element does is emerging scientific method.'),
  ('simple-sorting-big-small-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Simple Sorting (Big/Small)', 'Offer objects in two distinct sizes. Watch how baby handles them differently — size discrimination precedes sorting by months.', 8, '5–10 min', 'Objects of two distinct sizes', 'Offer objects in two distinct sizes. Watch how baby handles them differently — size discrimination precedes sorting by months.'),
  ('imitation-game-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Imitation Game', 'Tap a surface, shake your head, clap — do a simple action and wait. Imitation of familiar actions appears around 8–9 months.', 7, '5–8 min', 'None', 'Tap a surface, shake your head, clap — do a simple action and wait. Imitation of familiar actions appears around 8–9 months.'),
  ('memory-game-where-did-it-go-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Memory Game (Where Did It Go?)', 'Let baby see you hide an object under one of two cups. Which cup do they look under? Tracking invisible displacement is developing.', 7, '5–8 min', 'Two cups and small toy', 'Let baby see you hide an object under one of two cups. Which cup do they look under? Tracking invisible displacement is developing.'),
  ('stranger-anxiety-support-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Stranger Anxiety Support', 'When baby shows anxiety with new people, hold them securely and engage the stranger warmly. Don''t force contact — baby reads your calm.', 8, '5–10 min', 'None', 'When baby shows anxiety with new people, hold them securely and engage the stranger warmly. Don''t force contact — baby reads your calm.'),
  ('protest-honour-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Protest Honour', 'When baby clearly communicates ''no more'' (turns away, arches), stop immediately. Teaching: your communication is respected.', null, 'Ongoing', 'None', 'When baby clearly communicates ''no more'' (turns away, arches), stop immediately. Teaching: your communication is respected.'),
  ('separation-practice-extended-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Separation Practice Extended', 'Leave baby with a known caregiver for 10–15 min. Return before distress. Consistent returns build the trust that makes separations easier.', 13, '10–15 min', 'None', 'Leave baby with a known caregiver for 10–15 min. Return before distress. Consistent returns build the trust that makes separations easier.'),
  ('mirror-play-together-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Mirror Play Together', 'Sit in front of a large mirror with baby. Point to their reflection, then yours. ''Kaun hai yeh? Tum ho!'' Social-cognitive learning.', 7, '5–8 min', 'Large mirror', 'Sit in front of a large mirror with baby. Point to their reflection, then yours. ''Kaun hai yeh? Tum ho!'' Social-cognitive learning.'),
  ('laugh-trigger-catalogue-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Laugh Trigger Catalogue', 'Find 3 things that reliably make baby laugh. Do them daily. The belly laugh is a major social-emotional development marker.', 8, '5–10 min', 'None', 'Find 3 things that reliably make baby laugh. Do them daily. The belly laugh is a major social-emotional development marker.'),
  ('object-permanence-people-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Object Permanence — People', 'Call ''Where''s Papa?'' when Papa is out of sight. Watch baby look toward the right location. Person permanence = secure attachment working.', 4, '3–5 min', 'None', 'Call ''Where''s Papa?'' when Papa is out of sight. Watch baby look toward the right location. Person permanence = secure attachment working.'),
  ('textured-surface-crawling-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Textured Surface Crawling', 'Let baby crawl on different surfaces: carpet, smooth floor, grass, a mat outside. Each surface is different proprioceptive input.', 13, '10–15 min', 'Various surfaces', 'Let baby crawl on different surfaces: carpet, smooth floor, grass, a mat outside. Each surface is different proprioceptive input.'),
  ('water-play-supervised-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Water Play (Supervised)', 'Extended bath time — 15 min. Let baby splash, pour, and explore. Water provides resistance, temperature, visual, and auditory input simultaneously.', 18, '15–20 min', 'Water, cup for pouring', 'Extended bath time — 15 min. Let baby splash, pour, and explore. Water provides resistance, temperature, visual, and auditory input simultaneously.'),
  ('nature-texture-explore-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Nature Texture Explore', 'Outdoors: let baby touch bark, leaves, stones, soil (if safe). Natural textures are the richest sensory input available.', 13, '10–15 min', 'None (outdoors)', 'Outdoors: let baby touch bark, leaves, stones, soil (if safe). Natural textures are the richest sensory input available.'),
  ('mouth-exploration-safe-objects-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Mouth Exploration (Safe Objects)', 'At this age, mouthing is the primary sensory tool. Provide safe, clean objects of varied size and texture. Don''t interrupt unless unsafe.', 8, '5–10 min', 'Safe household objects of varied texture', 'At this age, mouthing is the primary sensory tool. Provide safe, clean objects of varied size and texture. Don''t interrupt unless unsafe.'),
  ('sound-localisation-game-m7_9', 'cognitive'::domain, 'm7_9'::age_band, 'Sound Localisation Game', 'Make an interesting sound from behind baby, left, right, and above. Watch how accurately they turn toward each direction.', 7, '5–8 min', 'Any sound-making object', 'Make an interesting sound from behind baby, left, right, and above. Watch how accurately they turn toward each direction.'),
  ('spoon-introduction-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Spoon Introduction', 'Give baby a spoon during feeding. Messy self-feeding attempts — however unsuccessful — build fine motor and self-care simultaneously.', 18, '15–20 min', 'Spoon, food', 'Give baby a spoon during feeding. Messy self-feeding attempts — however unsuccessful — build fine motor and self-care simultaneously.'),
  ('cup-introduction-m7_9', 'social_emotional'::domain, 'm7_9'::age_band, 'Cup Introduction', 'Offer a small open cup with a tiny amount of water. Supervised sipping — not for intake, for the skill of cup management.', 8, '5–10 min', 'Small open cup, water', 'Offer a small open cup with a tiny amount of water. Supervised sipping — not for intake, for the skill of cup management.'),
  ('cruising-along-furniture-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Cruising Along Furniture', 'Place a toy at the far end of the sofa. Baby learns to step sideways while holding on — each step is a walking lesson.', 8, '5–10 min', 'Furniture + toy', 'Place a toy at the far end of the sofa. Baby learns to step sideways while holding on — each step is a walking lesson.'),
  ('first-steps-between-points-m10_12', 'motor'::domain, 'm10_12'::age_band, 'First Steps Between Points', 'Sit 1–2 steps from furniture baby is holding. Open arms and call their name. Close the gap gradually as confidence grows.', 8, '5–10 min', 'None', 'Sit 1–2 steps from furniture baby is holding. Open arms and call their name. Close the gap gradually as confidence grows.'),
  ('standing-balance-challenge-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Standing Balance Challenge', 'While baby stands holding furniture, catch their attention from the other side. Count the independent standing seconds each day.', 8, '5–10 min', 'None', 'While baby stands holding furniture, catch their attention from the other side. Count the independent standing seconds each day.'),
  ('stair-descent-practice-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Stair Descent Practice', 'With you directly behind, let baby learn to descend stairs backwards (feet first). This is safer than forward and builds spatial awareness.', 8, '5–10 min', 'Stairs', 'With you directly behind, let baby learn to descend stairs backwards (feet first). This is safer than forward and builds spatial awareness.'),
  ('ball-kicking-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Ball Kicking', 'Roll a large soft ball toward baby''s feet while they stand with support. Kicking combines balance, timing, and motor planning.', 8, '5–10 min', 'Soft ball', 'Roll a large soft ball toward baby''s feet while they stand with support. Kicking combines balance, timing, and motor planning.'),
  ('carry-while-walking-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Carry While Walking', 'Ask baby to carry a lightweight object while walking (holding your hand). Dual-task walking builds automaticity.', 8, '5–10 min', 'Small lightweight object', 'Ask baby to carry a lightweight object while walking (holding your hand). Dual-task walking builds automaticity.'),
  ('push-along-toy-walk-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Push-Along Toy Walk', 'Give baby a push-along toy (cardboard box works) to push while walking. The resistance helps them control speed and direction.', 8, '5–10 min', 'Box or push-along toy', 'Give baby a push-along toy (cardboard box works) to push while walking. The resistance helps them control speed and direction.'),
  ('rough-ground-walking-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Rough-Ground Walking', 'Walk on grass, gravel path, or slight slope with one hand held. Variable terrain builds adaptive balance faster than smooth floors.', 13, '10–15 min', 'None (outdoors)', 'Walk on grass, gravel path, or slight slope with one hand held. Variable terrain builds adaptive balance faster than smooth floors.'),
  ('pincer-grasp-refinement-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Pincer Grasp Refinement', 'Offer small safe objects on a tray. A precise thumb-index pincer grip developing by 12 months is a fine motor milestone.', 8, '5–10 min', 'Small safe objects', 'Offer small safe objects on a tray. A precise thumb-index pincer grip developing by 12 months is a fine motor milestone.'),
  ('scribble-with-crayon-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Scribble with Crayon', 'Hold a crayon with baby''s hand and make marks on paper. The first deliberate mark — even if uncontrolled — is the beginning of writing.', 8, '5–10 min', 'Crayon and paper', 'Hold a crayon with baby''s hand and make marks on paper. The first deliberate mark — even if uncontrolled — is the beginning of writing.'),
  ('stacking-2-3-blocks-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Stacking 2–3 Blocks', 'Demonstrate stacking 2 blocks then hand one to baby. Can they place it on top? 2-block tower by 12 months = spatial milestone.', 8, '5–10 min', 'Blocks or similar objects', 'Demonstrate stacking 2 blocks then hand one to baby. Can they place it on top? 2-block tower by 12 months = spatial milestone.'),
  ('post-into-container-slot-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Post into Container (Slot)', 'Cut a slot in a box lid and provide objects that fit through. Posting requires visual-spatial matching — demanding for this age.', 8, '5–10 min', 'Cardboard box and objects', 'Cut a slot in a box lid and provide objects that fit through. Posting requires visual-spatial matching — demanding for this age.'),
  ('turn-pages-board-book-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Turn Pages (Board Book)', 'Let baby turn board book pages. Even turning multiple at once counts — the intent to turn is the milestone, not the accuracy.', 7, '5–8 min', 'Board book', 'Let baby turn board book pages. Even turning multiple at once counts — the intent to turn is the milestone, not the accuracy.'),
  ('unscrew-lid-m10_12', 'motor'::domain, 'm10_12'::age_band, 'Unscrew Lid', 'Offer a large-lidded container. Show loosening a lid; let them try. Rotation movements are a distinct fine motor skill.', 8, '5–10 min', 'Large lidded container', 'Offer a large-lidded container. Show loosening a lid; let them try. Rotation movements are a distinct fine motor skill.'),
  ('mama-and-dada-with-meaning-m10_12', 'communication'::domain, 'm10_12'::age_band, 'Mama'' and ''Dada'' with Meaning', 'When they say ''mama'' or ''dada'' directed at the correct person, respond warmly and immediately. First true words are emerging now.', null, 'Ongoing', 'None', 'When they say ''mama'' or ''dada'' directed at the correct person, respond warmly and immediately. First true words are emerging now.'),
  ('first-word-inventory-m10_12', 'communication'::domain, 'm10_12'::age_band, 'First Word Inventory', 'This week, note every consistent sound used to mean a specific thing. ''ba'' always for ball = a first word even if it doesn''t sound adult.', null, 'Ongoing', 'None', 'This week, note every consistent sound used to mean a specific thing. ''ba'' always for ball = a first word even if it doesn''t sound adult.'),
  ('expand-every-utterance-m10_12', 'communication'::domain, 'm10_12'::age_band, 'Expand Every Utterance', 'When baby says one word, add two: ''ba'' → ''ball! Big red ball.'' Every expansion teaches: what you said has a more complete version.', null, 'Ongoing', 'None', 'When baby says one word, add two: ''ba'' → ''ball! Big red ball.'' Every expansion teaches: what you said has a more complete version.'),
  ('bye-bye-gesture-contextual-m10_12', 'communication'::domain, 'm10_12'::age_band, 'Bye-Bye Gesture (Contextual)', 'Wave bye-bye every single time anyone leaves. First spontaneous contextual wave — not prompted — marks true gestural communication.', null, 'Ongoing', 'None', 'Wave bye-bye every single time anyone leaves. First spontaneous contextual wave — not prompted — marks true gestural communication.'),
  ('point-name-response-m10_12', 'communication'::domain, 'm10_12'::age_band, 'Point + Name Response', 'Every time baby points, immediately name what they''re pointing at and comment. The point deserves a full response, every time.', null, 'Ongoing', 'None', 'Every time baby points, immediately name what they''re pointing at and comment. The point deserves a full response, every time.'),
  ('follow-simple-instruction-m10_12', 'communication'::domain, 'm10_12'::age_band, 'Follow Simple Instruction', 'Come here'' / ''Give me'' / ''Where is the ball?'' with consistent gesture. Following 1-step instructions by 12 months is a key milestone.', 4, '3–5 min', 'None', 'Come here'' / ''Give me'' / ''Where is the ball?'' with consistent gesture. Following 1-step instructions by 12 months is a key milestone.'),
  ('nursery-rhymes-with-actions-m10_12', 'communication'::domain, 'm10_12'::age_band, 'Nursery Rhymes with Actions', 'Sing rhymes with hand actions: ''taalee bajao'', ''Johny Johny''. Baby learns to do the actions before saying the words.', 8, '5–10 min', 'None', 'Sing rhymes with hand actions: ''taalee bajao'', ''Johny Johny''. Baby learns to do the actions before saying the words.'),
  ('name-3-body-parts-m10_12', 'communication'::domain, 'm10_12'::age_band, 'Name 3 Body Parts', 'During bath or dressing, ask ''Kahaan hai naak?'' and point. Recognising 2–3 body parts on command by 12 months is typical.', 4, '3–5 min', 'None', 'During bath or dressing, ask ''Kahaan hai naak?'' and point. Recognising 2–3 body parts on command by 12 months is typical.'),
  ('object-permanence-two-locations-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Object Permanence (Two Locations)', 'Hide a toy under one of two cloths while baby watches. Do they search the correct one? Searching correctly = solid object permanence.', 7, '5–8 min', 'Two cloths + toy', 'Hide a toy under one of two cloths while baby watches. Do they search the correct one? Searching correctly = solid object permanence.'),
  ('imitate-household-tasks-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Imitate Household Tasks', 'Hand baby a cloth when you wipe a surface. Give them a spoon when you stir. They imitate because they understand the action''s purpose.', 8, '5–10 min', 'Household items', 'Hand baby a cloth when you wipe a surface. Give them a spoon when you stir. They imitate because they understand the action''s purpose.'),
  ('simple-puzzle-2-pieces-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Simple Puzzle (2 Pieces)', 'A 2-piece puzzle — shape fits a hole — shows visual discrimination, spatial rotation awareness, and persistence.', 8, '5–10 min', 'Simple puzzle or homemade shape-in-box', 'A 2-piece puzzle — shape fits a hole — shows visual discrimination, spatial rotation awareness, and persistence.'),
  ('find-object-under-cup-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Find Object Under Cup', 'Show baby the toy going under one cup. Reverse the cup with the toy and ask: where did it go? Object-tracking in 3D space.', 7, '5–8 min', 'Cup and small toy', 'Show baby the toy going under one cup. Reverse the cup with the toy and ask: where did it go? Object-tracking in 3D space.'),
  ('pretend-play-introduction-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Pretend Play Introduction', 'Pretend to drink from an empty cup, or put a toy phone to your ear. When baby imitates — symbolic thought has arrived.', 8, '5–10 min', 'Cup, spoon, or toy phone', 'Pretend to drink from an empty cup, or put a toy phone to your ear. When baby imitates — symbolic thought has arrived.'),
  ('problem-solving-open-box-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Problem Solving: Open Box', 'Put a favourite toy in a closed (not locked) box. Watch what baby does to open it — persistence and problem-solving combined.', 8, '5–10 min', 'Box with lid + toy', 'Put a favourite toy in a closed (not locked) box. Watch what baby does to open it — persistence and problem-solving combined.'),
  ('affection-initiation-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Affection Initiation', 'Note whether baby initiates affection — reaches up to be held, hugs, brings you objects. These are attachment behaviours to celebrate.', null, 'Ongoing', 'None', 'Note whether baby initiates affection — reaches up to be held, hugs, brings you objects. These are attachment behaviours to celebrate.'),
  ('limit-testing-observation-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Limit Testing Observation', 'When baby deliberately drops something and watches your reaction — they are testing social rules. Calm, consistent responses are the lesson.', null, 'Ongoing', 'None', 'When baby deliberately drops something and watches your reaction — they are testing social rules. Calm, consistent responses are the lesson.'),
  ('empathy-seed-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Empathy Seed', 'If someone nearby is crying or upset, narrate what you see: ''Woh reh rahi hai. Shayad dukh lag raha hai use.'' Early empathy wiring.', null, 'Ongoing', 'None', 'If someone nearby is crying or upset, narrate what you see: ''Woh reh rahi hai. Shayad dukh lag raha hai use.'' Early empathy wiring.'),
  ('short-separation-practice-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Short Separation Practice', 'Leave for a consistent 15–20 minute trip. Confident goodbye + return as promised + warmth on return = secure separation learning.', 18, '15–20 min', 'None', 'Leave for a consistent 15–20 minute trip. Confident goodbye + return as promised + warmth on return = secure separation learning.'),
  ('play-alongside-another-child-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Play Alongside Another Child', 'Arrange play near another baby. No expectation of interaction — parallel play beside another child is the correct stage right now.', 18, '15–20 min', 'None', 'Arrange play near another baby. No expectation of interaction — parallel play beside another child is the correct stage right now.'),
  ('social-game-repetition-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Social Game Repetition', 'Repeat a social game (peek-a-boo, tickle, bounce) and stop mid-way. Watch baby signal for continuation — communication is purposeful.', 8, '5–10 min', 'None', 'Repeat a social game (peek-a-boo, tickle, bounce) and stop mid-way. Watch baby signal for continuation — communication is purposeful.'),
  ('sensory-bin-introduction-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Sensory Bin Introduction', 'Fill a shallow container with dry rice or lentils. Let baby scoop, pour, and run hands through. Supervised closely.', 13, '10–15 min', 'Container + dry rice or lentils', 'Fill a shallow container with dry rice or lentils. Let baby scoop, pour, and run hands through. Supervised closely.'),
  ('outdoor-ground-texture-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Outdoor Ground Texture', 'Let baby crawl or stand on grass, sand, or mud (if safe). The resistance and texture of outdoor ground is uniquely rich input.', 13, '10–15 min', 'None (outdoors)', 'Let baby crawl or stand on grass, sand, or mud (if safe). The resistance and texture of outdoor ground is uniquely rich input.'),
  ('music-and-movement-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Music and Movement', 'Hold baby and move to music with a clear beat. Note what genres they respond to — musical personality is forming.', 8, '5–10 min', 'Music source', 'Hold baby and move to music with a clear beat. Note what genres they respond to — musical personality is forming.'),
  ('whole-body-movement-play-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Whole-Body Movement Play', 'Roll baby gently in a blanket, lift in air briefly, spin slowly. Vestibular system thrives on varied whole-body movement.', 8, '5–10 min', 'Blanket', 'Roll baby gently in a blanket, lift in air briefly, spin slowly. Vestibular system thrives on varied whole-body movement.'),
  ('messy-play-introduction-m10_12', 'cognitive'::domain, 'm10_12'::age_band, 'Messy Play Introduction', 'Puréed food or yoghurt on a tray. Let baby touch, smear, and explore. Tactile tolerance built now prevents later sensory avoidance.', 13, '10–15 min', 'Food-based material on tray', 'Puréed food or yoghurt on a tray. Let baby touch, smear, and explore. Tactile tolerance built now prevents later sensory avoidance.'),
  ('spoon-practice-self-feed-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Spoon Practice Self-Feed', 'Baby-led spoon feeding — messy and slow is correct. The independence matters more than the quantity eaten.', 18, '15–20 min', 'Spoon + food', 'Baby-led spoon feeding — messy and slow is correct. The independence matters more than the quantity eaten.'),
  ('shoes-and-socks-off-m10_12', 'social_emotional'::domain, 'm10_12'::age_band, 'Shoes and Socks Off', 'Let baby try to remove their own socks. This develops fine motor skill and body-care independence simultaneously.', 8, '5–10 min', 'Socks', 'Let baby try to remove their own socks. This develops fine motor skill and body-care independence simultaneously.'),
  ('walk-on-uneven-ground-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Walk on Uneven Ground', 'Daily outdoor walking on grass, gravel, or slopes builds adaptive balance far faster than smooth indoor floors.', 18, '15–20 min', 'None (outdoors)', 'Daily outdoor walking on grass, gravel, or slopes builds adaptive balance far faster than smooth indoor floors.'),
  ('climbing-on-low-furniture-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Climbing on Low Furniture', 'Let baby climb on and off a sofa cushion on the floor under supervision. Climbing builds shoulder, core, and spatial judgement.', 8, '5–10 min', 'Sofa cushion on floor', 'Let baby climb on and off a sofa cushion on the floor under supervision. Climbing builds shoulder, core, and spatial judgement.'),
  ('squat-to-pick-up-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Squat to Pick Up', 'Place toys on the floor and encourage baby to squat to retrieve them instead of bending at the waist. Squat builds hip and core strength.', 8, '5–10 min', 'Toys on floor', 'Place toys on the floor and encourage baby to squat to retrieve them instead of bending at the waist. Squat builds hip and core strength.'),
  ('kick-a-ball-forward-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Kick a Ball Forward', 'Roll a large soft ball toward baby and encourage kicking. Timing, balance on one foot, and motor planning combine in this action.', 8, '5–10 min', 'Soft ball', 'Roll a large soft ball toward baby and encourage kicking. Timing, balance on one foot, and motor planning combine in this action.'),
  ('throw-a-ball-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Throw a Ball', 'Demonstrate overhead throwing and let baby try. Even wild attempts build the shoulder rotation and release control needed for throwing.', 8, '5–10 min', 'Soft ball', 'Demonstrate overhead throwing and let baby try. Even wild attempts build the shoulder rotation and release control needed for throwing.'),
  ('walk-and-carry-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Walk and Carry', 'Ask baby to carry a lightweight object from one room to another. Dual-task locomotion shows walking is becoming automatic.', 8, '5–10 min', 'Lightweight object', 'Ask baby to carry a lightweight object from one room to another. Dual-task locomotion shows walking is becoming automatic.'),
  ('dance-freely-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Dance Freely', 'Put on music and dance together. Free movement to music builds coordination, rhythm, and body awareness simultaneously.', 8, '5–10 min', 'Music source', 'Put on music and dance together. Free movement to music builds coordination, rhythm, and body awareness simultaneously.'),
  ('stair-up-and-down-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Stair Up and Down', 'Practice going up and down stairs with one hand held. By 15 months most children can navigate with support.', 8, '5–10 min', 'Stairs', 'Practice going up and down stairs with one hand held. By 15 months most children can navigate with support.'),
  ('crayon-mark-making-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Crayon Mark Making', 'Large crayons on big paper. Any mark is the goal — this is the beginning of all future writing. Celebrate every mark.', 8, '5–10 min', 'Crayons and large paper', 'Large crayons on big paper. Any mark is the goal — this is the beginning of all future writing. Celebrate every mark.'),
  ('stacking-4-blocks-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Stacking 4+ Blocks', 'Stack 4 blocks and let baby copy. Knock down and restart. 4-block tower by 15 months is solid fine motor development.', 8, '5–10 min', 'Blocks', 'Stack 4 blocks and let baby copy. Knock down and restart. 4-block tower by 15 months is solid fine motor development.'),
  ('shape-sorter-circle-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Shape Sorter (Circle)', 'Start with just the circular hole — no rotation needed. Success with circle before introducing shapes that require rotation.', 8, '5–10 min', 'Shape sorter or homemade version', 'Start with just the circular hole — no rotation needed. Success with circle before introducing shapes that require rotation.'),
  ('bead-threading-large-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Bead Threading (Large)', 'Thread large beads or pasta onto a thick cord. Requires two-hand coordination, visual targeting, and sustained attention.', 8, '5–10 min', 'Large beads/pasta + thick cord', 'Thread large beads or pasta onto a thick cord. Requires two-hand coordination, visual targeting, and sustained attention.'),
  ('fill-and-pour-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Fill and Pour', 'Water play with two containers — fill one, pour into other. The control of pouring is a fine motor skill used in self-care for years.', 8, '5–10 min', 'Two containers, water', 'Water play with two containers — fill one, pour into other. The control of pouring is a fine motor skill used in self-care for years.'),
  ('peel-stickers-m13_15', 'motor'::domain, 'm13_15'::age_band, 'Peel Stickers', 'Place large stickers on paper and let baby peel them off. Pinch-peel requires precise finger coordination.', 8, '5–10 min', 'Stickers or tape on paper', 'Place large stickers on paper and let baby peel them off. Pinch-peel requires precise finger coordination.'),
  ('10-word-vocabulary-m13_15', 'communication'::domain, 'm13_15'::age_band, '10+ Word Vocabulary', 'Count consistent words this week including approximations. Target: 10+ words by 15 months. Each is celebrated explicitly.', null, 'Ongoing', 'None', 'Count consistent words this week including approximations. Target: 10+ words by 15 months. Each is celebrated explicitly.'),
  ('two-word-combination-watch-m13_15', 'communication'::domain, 'm13_15'::age_band, 'Two-Word Combination Watch', 'Listen for first two-word combinations: ''more doodh'', ''mama up''. These typically appear 15–18 months and mark a major leap.', null, 'Ongoing', 'None', 'Listen for first two-word combinations: ''more doodh'', ''mama up''. These typically appear 15–18 months and mark a major leap.'),
  ('name-5-body-parts-m13_15', 'communication'::domain, 'm13_15'::age_band, 'Name 5 Body Parts', 'Extend body part naming to 5: naak, haath, paon, aankhein, kaan. Can baby point to each when named?', 4, '3–5 min', 'None', 'Extend body part naming to 5: naak, haath, paon, aankhein, kaan. Can baby point to each when named?'),
  ('picture-book-naming-m13_15', 'communication'::domain, 'm13_15'::age_band, 'Picture Book Naming', 'Point to pictures and ask ''What''s this?'' Wait. If no answer, name it and move on. No pressure — repeated exposure is what builds it.', 8, '5–10 min', 'Picture book', 'Point to pictures and ask ''What''s this?'' Wait. If no answer, name it and move on. No pressure — repeated exposure is what builds it.'),
  ('follow-2-step-instruction-m13_15', 'communication'::domain, 'm13_15'::age_band, 'Follow 2-Step Instruction', 'Pick up the ball AND put it in the box.'' Two-step unrelated instructions mark a significant receptive language leap.', 4, '3–5 min', 'Ball and box', 'Pick up the ball AND put it in the box.'' Two-step unrelated instructions mark a significant receptive language leap.'),
  ('pretend-telephone-call-m13_15', 'communication'::domain, 'm13_15'::age_band, 'Pretend Telephone Call', 'Hold a wooden spoon to your ear: ''Hello? Yeh kaun hai?'' Let baby take it. Symbolic play and communication combined.', 8, '5–10 min', 'Any object as phone', 'Hold a wooden spoon to your ear: ''Hello? Yeh kaun hai?'' Let baby take it. Symbolic play and communication combined.'),
  ('expand-add-more-m13_15', 'communication'::domain, 'm13_15'::age_band, 'Expand + Add More', 'When baby says ''ball'', say ''ball — red ball — big round ball!'' Each expansion teaches vocabulary and sentence structure simultaneously.', null, 'Ongoing', 'None', 'When baby says ''ball'', say ''ball — red ball — big round ball!'' Each expansion teaches vocabulary and sentence structure simultaneously.'),
  ('sing-and-fill-m13_15', 'communication'::domain, 'm13_15'::age_band, 'Sing-and-Fill', 'Sing a familiar song and pause before the last word of each line. Wait for baby to fill it in vocally or with gesture.', 7, '5–8 min', 'None', 'Sing a familiar song and pause before the last word of each line. Wait for baby to fill it in vocally or with gesture.'),
  ('simple-pretend-sequence-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Simple Pretend Sequence', 'Baby feeds a doll, puts it to sleep, covers it with a cloth. Three-step pretend = narrative thinking beginning.', 8, '5–10 min', 'Doll or soft toy, cloth', 'Baby feeds a doll, puts it to sleep, covers it with a cloth. Three-step pretend = narrative thinking beginning.'),
  ('match-identical-objects-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Match Identical Objects', 'Give baby two identical cups and two identical spoons. Can they match the cups together and spoons together?', 8, '5–10 min', 'Two matching pairs of household objects', 'Give baby two identical cups and two identical spoons. Can they match the cups together and spoons together?'),
  ('find-under-two-cups-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Find Under Two Cups', 'Hide a toy under one of two cups while baby watches. Swap the cups slowly. Which cup do they check? A-not-B error is normal now.', 7, '5–8 min', 'Two cups + toy', 'Hide a toy under one of two cups while baby watches. Swap the cups slowly. Which cup do they check? A-not-B error is normal now.'),
  ('sort-by-colour-one-colour-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Sort by Colour (One Colour)', 'Place all red objects in one pile, all blue in another — demonstrate. Don''t expect success yet; the repeated demonstration is the teaching.', 8, '5–10 min', 'Household objects of two colours', 'Place all red objects in one pile, all blue in another — demonstrate. Don''t expect success yet; the repeated demonstration is the teaching.'),
  ('early-number-concepts-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Early Number Concepts', 'During stacking or sorting, count aloud slowly: ''Ek, do, teen.'' One-to-one counting comprehension comes later — hearing it is the start.', 8, '5–10 min', 'Any stackable objects', 'During stacking or sorting, count aloud slowly: ''Ek, do, teen.'' One-to-one counting comprehension comes later — hearing it is the start.'),
  ('cause-effect-complexity-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Cause-Effect Complexity', 'Offer a toy with multiple actions: press this to make sound, turn that to see movement. Systematic testing of each element is science.', 8, '5–10 min', 'Multi-action toy', 'Offer a toy with multiple actions: press this to make sound, turn that to see movement. Systematic testing of each element is science.'),
  ('parallel-play-beside-peer-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Parallel Play Beside Peer', 'Arrange play near another toddler. Don''t expect interaction. Parallel play is the developmentally correct stage — don''t rush sharing.', 18, '15–20 min', 'None', 'Arrange play near another toddler. Don''t expect interaction. Parallel play is the developmentally correct stage — don''t rush sharing.'),
  ('tantrums-as-communication-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Tantrums as Communication', 'When a tantrum happens, narrate calmly: ''You''re very frustrated. You wanted that and you can''t have it. That''s hard.'' Name — don''t fix.', null, 'Ongoing', 'None', 'When a tantrum happens, narrate calmly: ''You''re very frustrated. You wanted that and you can''t have it. That''s hard.'' Name — don''t fix.'),
  ('mine-acknowledgement-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Mine'' Acknowledgement', 'When baby says ''mine'', acknowledge the feeling: ''Yes, that''s yours.'' Teaching ownership feelings before teaching sharing.', null, 'Ongoing', 'None', 'When baby says ''mine'', acknowledge the feeling: ''Yes, that''s yours.'' Teaching ownership feelings before teaching sharing.'),
  ('comfort-object-introduction-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Comfort Object Introduction', 'If baby has a preferred toy or cloth, honour it. A comfort object is not a crutch — it is an autonomous self-regulation tool.', null, 'Ongoing', 'Preferred soft toy or cloth', 'If baby has a preferred toy or cloth, honour it. A comfort object is not a crutch — it is an autonomous self-regulation tool.'),
  ('proud-moments-response-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Proud Moments Response', 'When baby achieves something, your response matters. Specific warm praise: ''You put all the blocks in! You worked hard at that.''', null, 'Ongoing', 'None', 'When baby achieves something, your response matters. Specific warm praise: ''You put all the blocks in! You worked hard at that.'''),
  ('independence-in-play-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Independence in Play', 'Create a safe floor space and let baby play alone for 5–10 minutes without intervention. Independent play is a skill to build.', 8, '5–10 min', 'Safe toy collection', 'Create a safe floor space and let baby play alone for 5–10 minutes without intervention. Independent play is a skill to build.'),
  ('messy-sensory-play-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Messy Sensory Play', 'Cooked spaghetti, wet sand, or yoghurt on a tray. Sensory tolerance for unfamiliar textures is built through repeated low-pressure exposure.', 13, '10–15 min', 'Food material on tray', 'Cooked spaghetti, wet sand, or yoghurt on a tray. Sensory tolerance for unfamiliar textures is built through repeated low-pressure exposure.'),
  ('nature-walk-and-collect-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Nature Walk and Collect', 'Walk outdoors and collect leaves, stones, sticks (safe). Back home, handle and sort them. Natural materials are rich sensory input.', 25, '20–30 min', 'Bag for collecting', 'Walk outdoors and collect leaves, stones, sticks (safe). Back home, handle and sort them. Natural materials are rich sensory input.'),
  ('rhythm-instruments-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Rhythm Instruments', 'Pots, wooden spoon, dried rice in a container. Make music together. Rhythm production is both sensory and fine motor.', 8, '5–10 min', 'Pots, spoons, containers', 'Pots, wooden spoon, dried rice in a container. Make music together. Rhythm production is both sensory and fine motor.'),
  ('spinning-and-rolling-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Spinning and Rolling', 'Roll baby gently on the floor or spin slowly in arms. Vestibular input supports balance, posture, and regulation.', 4, '3–5 min', 'None', 'Roll baby gently on the floor or spin slowly in arms. Vestibular input supports balance, posture, and regulation.'),
  ('playdough-atta-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Playdough (Atta)', 'Knead some atta (wheat dough) together. Baby squeezes, pokes, and flattens. Playdough is pure fine motor and tactile input.', 13, '10–15 min', 'Wheat flour, water', 'Knead some atta (wheat dough) together. Baby squeezes, pokes, and flattens. Playdough is pure fine motor and tactile input.'),
  ('spoon-use-practice-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Spoon Use Practice', 'Encourage spoon use at every meal, however messy. Competence by 18 months is the target — not table manners, just the motor skill.', 18, '15–20 min', 'Spoon, food', 'Encourage spoon use at every meal, however messy. Competence by 18 months is the target — not table manners, just the motor skill.'),
  ('partial-dressing-help-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Partial Dressing Help', 'Ask baby to push their arm through a sleeve or lift a foot for a sock. Participation — however partial — builds independence.', 8, '5–10 min', 'Clothing', 'Ask baby to push their arm through a sleeve or lift a foot for a sock. Participation — however partial — builds independence.'),
  ('running-practice-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Running Practice', 'Running at 16–18 months is stiff-legged but consistent. Give open safe space and let them run freely — don''t slow them down.', 13, '10–15 min', 'Open safe space', 'Running at 16–18 months is stiff-legged but consistent. Give open safe space and let them run freely — don''t slow them down.'),
  ('walk-up-stairs-rail-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Walk Up Stairs (Rail)', 'Walk up stairs holding the rail, one hand held. Alternating feet on stairs typically appears around 2 years — step-together is fine now.', 8, '5–10 min', 'Stairs with rail', 'Walk up stairs holding the rail, one hand held. Alternating feet on stairs typically appears around 2 years — step-together is fine now.'),
  ('kick-ball-with-aim-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Kick Ball with Aim', 'Set up a ''goal'' (two objects as posts) and encourage kicking the ball between them. Directed kicking requires motor planning.', 8, '5–10 min', 'Ball + two objects as posts', 'Set up a ''goal'' (two objects as posts) and encourage kicking the ball between them. Directed kicking requires motor planning.'),
  ('jump-off-step-both-feet-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Jump Off Step (Both Feet)', 'Stand baby on the bottom stair or a thick book. Encourage jumping off with both feet. Landing with both feet = motor milestone.', 4, '3–5 min', 'Low step or book', 'Stand baby on the bottom stair or a thick book. Encourage jumping off with both feet. Landing with both feet = motor milestone.'),
  ('climbing-ladder-slide-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Climbing Ladder / Slide', 'At a playground or safe homemade version, let baby climb up and come down a small slide. Height + movement = vestibular rich.', 13, '10–15 min', 'Playground or safe climbing surface', 'At a playground or safe homemade version, let baby climb up and come down a small slide. Height + movement = vestibular rich.'),
  ('pedal-push-along-ride-on-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Pedal (Push Along Ride-On)', 'A push-along ride-on (or cardboard box to sit in) builds leg strength and spatial navigation before a true pedalling bike.', 13, '10–15 min', 'Ride-on toy or adapted cardboard box', 'A push-along ride-on (or cardboard box to sit in) builds leg strength and spatial navigation before a true pedalling bike.'),
  ('balance-beam-walking-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Balance Beam Walking', 'Make a ''beam'' with masking tape on the floor. Encourage walking along the line with arms out. Balance challenges in a safe context.', 8, '5–10 min', 'Masking tape', 'Make a ''beam'' with masking tape on the floor. Encourage walking along the line with arms out. Balance challenges in a safe context.'),
  ('carry-heavy-load-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Carry Heavy Load', 'Ask baby to carry a small bag with a few books inside across the room. Heavy carrying is regulating to the sensory system.', 8, '5–10 min', 'Small bag with books', 'Ask baby to carry a small bag with a few books inside across the room. Heavy carrying is regulating to the sensory system.'),
  ('drawing-lines-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Drawing Lines', 'Show drawing a horizontal line across paper and let baby try. Any deliberate directional mark is an achievement.', 8, '5–10 min', 'Crayons and paper', 'Show drawing a horizontal line across paper and let baby try. Any deliberate directional mark is an achievement.'),
  ('unscrew-and-screw-lids-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Unscrew and Screw Lids', 'Practice opening and closing containers with twist lids. Rotation movements are a distinct fine motor skill used in daily life.', 8, '5–10 min', 'Containers with lids', 'Practice opening and closing containers with twist lids. Rotation movements are a distinct fine motor skill used in daily life.'),
  ('stacking-6-blocks-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Stacking 6+ Blocks', '6-block tower requires spatial planning, grip calibration, and controlled release. Each additional block is harder than it looks.', 8, '5–10 min', 'Blocks or similar', '6-block tower requires spatial planning, grip calibration, and controlled release. Each additional block is harder than it looks.'),
  ('tear-paper-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Tear Paper', 'Provide magazines or old newspaper for tearing. Bilateral tearing requires both hands working in opposition — a coordination milestone.', 8, '5–10 min', 'Old paper', 'Provide magazines or old newspaper for tearing. Bilateral tearing requires both hands working in opposition — a coordination milestone.'),
  ('string-beads-large-m16_18', 'motor'::domain, 'm16_18'::age_band, 'String Beads (Large)', 'Thread 5 large beads or pasta pieces onto a shoelace. Requires visual targeting, bilateral coordination, and sustained attention.', 8, '5–10 min', 'Large beads + shoelace', 'Thread 5 large beads or pasta pieces onto a shoelace. Requires visual targeting, bilateral coordination, and sustained attention.'),
  ('puzzle-4-6-piece-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Puzzle (4–6 Piece)', 'A simple inset puzzle builds visual discrimination, spatial rotation, and the tolerance for trial-and-error failure.', 8, '5–10 min', 'Simple puzzle', 'A simple inset puzzle builds visual discrimination, spatial rotation, and the tolerance for trial-and-error failure.'),
  ('20-50-word-vocabulary-m16_18', 'communication'::domain, 'm16_18'::age_band, '20–50 Word Vocabulary', 'By 18 months, 20–50 words (including approximations) is the developmental target. Under 10 words by 18 months warrants a paediatrician mention.', null, 'Ongoing', 'None', 'By 18 months, 20–50 words (including approximations) is the developmental target. Under 10 words by 18 months warrants a paediatrician mention.'),
  ('two-word-combinations-m16_18', 'communication'::domain, 'm16_18'::age_band, 'Two-Word Combinations', 'More doodh'', ''bye dada'', ''big ball.'' Two-word phrases by 18 months are a major milestone. Model them in all conversation.', null, 'Ongoing', 'None', 'More doodh'', ''bye dada'', ''big ball.'' Two-word phrases by 18 months are a major milestone. Model them in all conversation.'),
  ('what-s-that-response-m16_18', 'communication'::domain, 'm16_18'::age_band, 'What''s That?'' Response', 'Baby will point at everything and say ''woh kya hai?'' or similar. Every time: name it, describe it in one sentence, wait.', null, 'Ongoing', 'None', 'Baby will point at everything and say ''woh kya hai?'' or similar. Every time: name it, describe it in one sentence, wait.'),
  ('story-telling-simple-m16_18', 'communication'::domain, 'm16_18'::age_band, 'Story Telling (Simple)', 'Tell a simple 3-sentence story about something that happened today. Story structure — beginning, middle, end — is absorbed before it is produced.', 8, '5–10 min', 'None', 'Tell a simple 3-sentence story about something that happened today. Story structure — beginning, middle, end — is absorbed before it is produced.'),
  ('animal-sounds-game-m16_18', 'communication'::domain, 'm16_18'::age_band, 'Animal Sounds Game', 'Kutte kya bolta hai? Bhow bhow!'' Sound-to-animal linking builds vocabulary through a different encoding channel.', 4, '3–5 min', 'None', 'Kutte kya bolta hai? Bhow bhow!'' Sound-to-animal linking builds vocabulary through a different encoding channel.'),
  ('action-word-focus-m16_18', 'communication'::domain, 'm16_18'::age_band, 'Action Word Focus', 'Focus on verbs this week: running, eating, sleeping, jumping. Action vocabulary is as important as noun vocabulary.', null, 'Ongoing', 'None', 'Focus on verbs this week: running, eating, sleeping, jumping. Action vocabulary is as important as noun vocabulary.'),
  ('reading-together-daily-m16_18', 'communication'::domain, 'm16_18'::age_band, 'Reading Together Daily', 'Same book, multiple days in a row. When baby anticipates a page, they are demonstrating memory, sequence, and language — simultaneously.', 8, '5–10 min', 'Board book', 'Same book, multiple days in a row. When baby anticipates a page, they are demonstrating memory, sequence, and language — simultaneously.'),
  ('singing-along-m16_18', 'communication'::domain, 'm16_18'::age_band, 'Singing Along', 'In familiar songs, pause on the last word of each line and wait. By 18 months many babies fill in the word — word retrieval practice.', 8, '5–10 min', 'None', 'In familiar songs, pause on the last word of each line and wait. By 18 months many babies fill in the word — word retrieval practice.'),
  ('simple-pretend-cooking-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Simple Pretend Cooking', 'Give baby pots, spoons, and empty containers. Let them ''cook.'' Pretend play now represents real sequences observed in daily life.', 13, '10–15 min', 'Pots, spoons, empty containers', 'Give baby pots, spoons, and empty containers. Let them ''cook.'' Pretend play now represents real sequences observed in daily life.'),
  ('sort-by-shape-2-shapes-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Sort by Shape (2 Shapes)', 'Sort objects into two groups by shape: round things here, flat things there. Demonstrate; don''t expect immediate success.', 8, '5–10 min', 'Household objects of two shapes', 'Sort objects into two groups by shape: round things here, flat things there. Demonstrate; don''t expect immediate success.'),
  ('picture-to-object-match-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Picture-to-Object Match', 'Show a picture of a cup, then ask baby to find the real cup. Picture-object correspondence is an abstract cognitive skill.', 7, '5–8 min', 'Picture and matching real object', 'Show a picture of a cup, then ask baby to find the real cup. Picture-object correspondence is an abstract cognitive skill.'),
  ('order-completion-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Order Completion', 'Begin a familiar routine and stop mid-way. Watch baby signal or try to complete it — sequence memory is confirming itself.', null, 'Ongoing', 'None', 'Begin a familiar routine and stop mid-way. Watch baby signal or try to complete it — sequence memory is confirming itself.'),
  ('count-with-objects-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Count with Objects', 'Place 1, then 2, then 3 objects in a line counting aloud as you do. One-to-one correspondence is being seeded; production comes later.', 7, '5–8 min', 'Small objects for counting', 'Place 1, then 2, then 3 objects in a line counting aloud as you do. One-to-one correspondence is being seeded; production comes later.'),
  ('problem-solving-unstick-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Problem Solving: Unstick', 'Tape a desirable toy lightly to a table or box. Watch how baby figures out removing the tape or pulling the object free.', 7, '5–8 min', 'Tape and toy', 'Tape a desirable toy lightly to a table or box. Watch how baby figures out removing the tape or pulling the object free.'),
  ('emotion-coaching-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Emotion Coaching', 'When emotions arise, sit close and name the emotion specifically: ''You''re angry. That felt unfair.'' Don''t fix — just name and stay.', null, 'Ongoing', 'None', 'When emotions arise, sit close and name the emotion specifically: ''You''re angry. That felt unfair.'' Don''t fix — just name and stay.'),
  ('feelings-chart-introduction-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Feelings Chart Introduction', 'Put a simple 4-face chart on the wall: happy, sad, angry, scared. ''How are you feeling today? Point to the face.'' No judgment.', 7, '5–8 min', 'Paper with drawn faces', 'Put a simple 4-face chart on the wall: happy, sad, angry, scared. ''How are you feeling today? Point to the face.'' No judgment.'),
  ('practice-goodbye-ritual-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Practice Goodbye Ritual', 'Develop a 3-step goodbye sequence for separations. Consistent, brief, warm — never long and uncertain. Consistency reduces distress.', 3, '2–3 min', 'None', 'Develop a 3-step goodbye sequence for separations. Consistent, brief, warm — never long and uncertain. Consistency reduces distress.'),
  ('cooperative-game-roll-ball-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Cooperative Game (Roll Ball)', 'Sit facing each other and roll a ball back and forth. Taking turns in a structured physical game is cooperative play emerging.', 8, '5–10 min', 'Ball', 'Sit facing each other and roll a ball back and forth. Taking turns in a structured physical game is cooperative play emerging.'),
  ('show-empathy-in-books-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Show Empathy in Books', 'When a character in a book is sad or scared, narrate: ''Woh dara hua hai. Tum kya sochte ho?'' Perspective-taking through story.', 7, '5–8 min', 'Picture book', 'When a character in a book is sad or scared, narrate: ''Woh dara hua hai. Tum kya sochte ho?'' Perspective-taking through story.'),
  ('household-helper-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Household Helper', 'Let baby ''help'' wipe a surface, stir food, hand you objects. Social participation and competence are both being built.', 8, '5–10 min', 'Household task', 'Let baby ''help'' wipe a surface, stir food, hand you objects. Social participation and competence are both being built.'),
  ('sensory-bin-varied-fill-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Sensory Bin (Varied Fill)', 'This month use a different fill each week: sand, water, dried beans, shredded paper. Sensory tolerance broadens with variety.', 13, '10–15 min', 'Container + fill material', 'This month use a different fill each week: sand, water, dried beans, shredded paper. Sensory tolerance broadens with variety.'),
  ('outdoor-barefoot-walking-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Outdoor Barefoot Walking', 'Walking barefoot on grass, sand, or dirt provides proprioceptive richness that shoes remove. 10 minutes barefoot outdoors = rich input.', 13, '10–15 min', 'None (outdoors)', 'Walking barefoot on grass, sand, or dirt provides proprioceptive richness that shoes remove. 10 minutes barefoot outdoors = rich input.'),
  ('clay-or-dough-play-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Clay or Dough Play', 'Commercial clay or homemade atta dough. Squeezing, rolling, and flattening are pure fine motor with rich tactile feedback.', 13, '10–15 min', 'Clay or atta dough', 'Commercial clay or homemade atta dough. Squeezing, rolling, and flattening are pure fine motor with rich tactile feedback.'),
  ('sound-discrimination-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Sound Discrimination', 'Make the same sound loudly and quietly — the same instrument or voice. Can baby identify louder and quieter? Auditory discrimination.', 4, '3–5 min', 'Any sound-making object', 'Make the same sound loudly and quietly — the same instrument or voice. Can baby identify louder and quieter? Auditory discrimination.'),
  ('blanket-roll-and-burrito-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Blanket Roll and Burrito', 'Roll baby gently in a blanket — not tight. The whole-body deep pressure is calming for the nervous system and delights most toddlers.', 4, '3–5 min', 'Blanket', 'Roll baby gently in a blanket — not tight. The whole-body deep pressure is calming for the nervous system and delights most toddlers.'),
  ('spoon-and-fork-independence-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Spoon and Fork Independence', 'Offer fork for stabbing soft foods. Fork + spoon both available. Child chooses — autonomy in eating builds a positive food relationship.', 18, '15–20 min', 'Fork, spoon, food', 'Offer fork for stabbing soft foods. Fork + spoon both available. Child chooses — autonomy in eating builds a positive food relationship.'),
  ('washing-hands-routine-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Washing Hands Routine', 'Demonstrate hand washing before every meal and after outdoors. By 18 months, with reminding and help, this is beginning to establish.', 3, '2–3 min', 'Soap, water, towel', 'Demonstrate hand washing before every meal and after outdoors. By 18 months, with reminding and help, this is beginning to establish.'),
  ('running-with-direction-changes-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Running with Direction Changes', 'Set up a simple course: run to the tree, run back. Direction change while running requires significant motor planning updates.', 13, '10–15 min', 'Open space', 'Set up a simple course: run to the tree, run back. Direction change while running requires significant motor planning updates.'),
  ('jump-with-both-feet-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Jump with Both Feet', 'From ground level, encourage jumping with both feet simultaneously leaving the ground. Landing on both feet = major gross motor milestone.', 4, '3–5 min', 'None', 'From ground level, encourage jumping with both feet simultaneously leaving the ground. Landing on both feet = major gross motor milestone.'),
  ('walk-up-and-down-stairs-rail-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Walk Up and Down Stairs (Rail)', 'Practice both directions on stairs with one hand on rail. Safety and independence are both being built.', 8, '5–10 min', 'Stairs', 'Practice both directions on stairs with one hand on rail. Safety and independence are both being built.'),
  ('kick-stationary-ball-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Kick Stationary Ball', 'Place a ball on the ground and ask baby to kick it. A stationary kick before a rolling ball — motor precision building.', 4, '3–5 min', 'Ball', 'Place a ball on the ground and ask baby to kick it. A stationary kick before a rolling ball — motor precision building.'),
  ('balance-on-one-foot-briefly-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Balance on One Foot Briefly', 'Hold baby''s hand and ask them to lift one foot for 2 seconds. Brief one-foot balance appearing 18–24 months.', 4, '3–5 min', 'None', 'Hold baby''s hand and ask them to lift one foot for 2 seconds. Brief one-foot balance appearing 18–24 months.'),
  ('climbing-frames-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Climbing Frames', 'Any safe climbing frame or jungle gym. Climbing is the most efficient builder of strength, coordination, and risk assessment.', 13, '10–15 min', 'Climbing frame or playground', 'Any safe climbing frame or jungle gym. Climbing is the most efficient builder of strength, coordination, and risk assessment.'),
  ('throwing-at-a-target-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Throwing at a Target', 'Set up a large container and throw soft balls into it from a metre away. Aimed throwing builds visual-motor coordination.', 8, '5–10 min', 'Container and soft balls', 'Set up a large container and throw soft balls into it from a metre away. Aimed throwing builds visual-motor coordination.'),
  ('ride-on-and-steer-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Ride-On and Steer', 'Push-along ride-on with steerable wheels, or just steering a cart. Navigation and steering need practice just like walking did.', 13, '10–15 min', 'Ride-on or push cart', 'Push-along ride-on with steerable wheels, or just steering a cart. Navigation and steering need practice just like walking did.'),
  ('draw-vertical-line-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Draw Vertical Line', 'Show drawing a line from top to bottom and let toddler try. Directional mark-making is the direct precursor to letter formation.', 8, '5–10 min', 'Crayon and paper', 'Show drawing a line from top to bottom and let toddler try. Directional mark-making is the direct precursor to letter formation.'),
  ('copy-circle-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Copy Circle', 'Show drawing a circle slowly and let toddler try. Circle before straight lines — fine motor milestone at 24–27 months when it appears.', 8, '5–10 min', 'Crayon and paper', 'Show drawing a circle slowly and let toddler try. Circle before straight lines — fine motor milestone at 24–27 months when it appears.'),
  ('stack-8-blocks-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Stack 8+ Blocks', '8-block tower requires sequential spatial planning: each level must be stable before the next. The planning IS the developmental work.', 8, '5–10 min', 'Blocks', '8-block tower requires sequential spatial planning: each level must be stable before the next. The planning IS the developmental work.'),
  ('cut-with-child-scissors-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Cut with Child Scissors', 'Introduce child-safe scissors with a parent steadying the paper. Cutting requires bilateral coordination and sustained grip.', 8, '5–10 min', 'Child scissors and paper', 'Introduce child-safe scissors with a parent steadying the paper. Cutting requires bilateral coordination and sustained grip.'),
  ('peg-in-pegboard-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Peg in Pegboard', 'Press pegs into a pegboard. Requires visual targeting, push force calibration, and the release of placing.', 8, '5–10 min', 'Pegboard (homemade: card with holes)', 'Press pegs into a pegboard. Requires visual targeting, push force calibration, and the release of placing.'),
  ('lace-large-holes-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Lace Large Holes', 'Lace a shoelace through large holes in cardboard. Pre-lacing builds the same hand movements as actual shoe-lacing later.', 8, '5–10 min', 'Cardboard with holes + shoelace', 'Lace a shoelace through large holes in cardboard. Pre-lacing builds the same hand movements as actual shoe-lacing later.'),
  ('50-100-word-vocabulary-m19_21', 'communication'::domain, 'm19_21'::age_band, '50–100 Word Vocabulary', '50+ words by 20 months is solid. Under 20 consistent words by 20 months is worth discussing with a paediatrician.', null, 'Ongoing', 'None', '50+ words by 20 months is solid. Under 20 consistent words by 20 months is worth discussing with a paediatrician.'),
  ('three-word-phrases-m19_21', 'communication'::domain, 'm19_21'::age_band, 'Three-Word Phrases', 'More apple please'', ''Mama come here.'' Three-word combinations beginning to appear 19–24 months.', null, 'Ongoing', 'None', 'More apple please'', ''Mama come here.'' Three-word combinations beginning to appear 19–24 months.'),
  ('refer-to-self-by-name-m19_21', 'communication'::domain, 'm19_21'::age_band, 'Refer to Self by Name', 'Aryan do it!'' Using own name before ''I'' is developmentally normal and means self-concept is forming.', null, 'Ongoing', 'None', 'Aryan do it!'' Using own name before ''I'' is developmentally normal and means self-concept is forming.'),
  ('ask-why-game-m19_21', 'communication'::domain, 'm19_21'::age_band, 'Ask ''Why?'' Game', 'When toddler asks ''why'' (it starts!), answer simply and then ask ''why do you think?'' Turn every why into a conversation.', null, 'Ongoing', 'None', 'When toddler asks ''why'' (it starts!), answer simply and then ask ''why do you think?'' Turn every why into a conversation.'),
  ('story-re-tell-m19_21', 'communication'::domain, 'm19_21'::age_band, 'Story Re-tell', 'After reading a familiar book, close it and ask ''What happened?'' Listen for any sequence — even one event recalled is narrative memory.', 8, '5–10 min', 'Familiar book', 'After reading a familiar book, close it and ask ''What happened?'' Listen for any sequence — even one event recalled is narrative memory.'),
  ('colour-naming-focus-m19_21', 'communication'::domain, 'm19_21'::age_band, 'Colour Naming Focus', 'Introduce one colour per week. Label it consistently all week: ''The red cup. Your red shoes. Red tomatoes!'' One at a time works best.', null, 'Ongoing', 'None', 'Introduce one colour per week. Label it consistently all week: ''The red cup. Your red shoes. Red tomatoes!'' One at a time works best.'),
  ('follow-2-step-instruction-unrelated-m19_21', 'communication'::domain, 'm19_21'::age_band, 'Follow 2-Step Instruction (Unrelated)', 'Pick up the cup AND bring it to me.'' Two unrelated steps in sequence tests working memory as well as language.', 4, '3–5 min', 'Cup', 'Pick up the cup AND bring it to me.'' Two unrelated steps in sequence tests working memory as well as language.'),
  ('conversation-practice-m19_21', 'communication'::domain, 'm19_21'::age_band, 'Conversation Practice', 'Ask open questions about recent experiences: ''What did you see at the park?'' Don''t correct answers — expand and continue.', 8, '5–10 min', 'None', 'Ask open questions about recent experiences: ''What did you see at the park?'' Don''t correct answers — expand and continue.'),
  ('cause-effect-multi-step-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Cause-Effect Multi-Step', 'Stack 3 books then push — watch toddler''s face. Set up a ramp and roll a ball down. Multi-step cause-effect chains are interesting now.', 8, '5–10 min', 'Books, ball, ramp (board)', 'Stack 3 books then push — watch toddler''s face. Set up a ramp and roll a ball down. Multi-step cause-effect chains are interesting now.'),
  ('categorise-animals-vs-food-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Categorise Animals vs Food', 'Use pictures or objects: sort animals from foods. Categorisation by function or type is a major cognitive leap.', 8, '5–10 min', 'Pictures or toy sets', 'Use pictures or objects: sort animals from foods. Categorisation by function or type is a major cognitive leap.'),
  ('sequence-3-events-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Sequence 3 Events', 'After a routine, ask what comes next: ''We had bath. Then what? Then what?'' Three-event sequence recall is emerging.', 7, '5–8 min', 'None', 'After a routine, ask what comes next: ''We had bath. Then what? Then what?'' Three-event sequence recall is emerging.'),
  ('simple-puzzle-6-8-pieces-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Simple Puzzle 6–8 Pieces', '6–8 piece puzzle requiring rotation and trial-and-error. The frustration tolerance needed here is as developmental as the spatial skill.', 8, '5–10 min', 'Simple puzzle', '6–8 piece puzzle requiring rotation and trial-and-error. The frustration tolerance needed here is as developmental as the spatial skill.'),
  ('count-1-5-objects-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Count 1–5 Objects', 'Place 3 objects in a line and count them together: touch each as you count. One-to-one correspondence beginning to appear.', 7, '5–8 min', 'Small objects', 'Place 3 objects in a line and count them together: touch each as you count. One-to-one correspondence beginning to appear.'),
  ('memory-card-match-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Memory Card Match', '4 pairs of matching cards face-down. Turn over 2 at a time. Early working memory and concentration.', 8, '5–10 min', '8 cards in 4 matching pairs', '4 pairs of matching cards face-down. Turn over 2 at a time. Early working memory and concentration.'),
  ('emotion-management-practice-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Emotion Management Practice', 'Before a frustrating task, name the strategy: ''If this is hard, take a breath.'' Practice during calm so it is available during frustration.', 7, '5–8 min', 'None', 'Before a frustrating task, name the strategy: ''If this is hard, take a breath.'' Practice during calm so it is available during frustration.'),
  ('turn-taking-in-games-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Turn Taking in Games', 'Establish clear turn-taking in a simple game. ''Meri baari. Ab tumhari baari.'' Consistent language makes the rule learnable.', 8, '5–10 min', 'Any game', 'Establish clear turn-taking in a simple game. ''Meri baari. Ab tumhari baari.'' Consistent language makes the rule learnable.'),
  ('empathy-practice-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Empathy Practice', 'Point out someone who is sad or hurt. ''Woh roh raha hai. Use dard hua. Hum kya kar sakte hain?'' Empathy is taught through narration.', null, 'Ongoing', 'None', 'Point out someone who is sad or hurt. ''Woh roh raha hai. Use dard hua. Hum kya kar sakte hain?'' Empathy is taught through narration.'),
  ('pretend-play-social-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Pretend Play Social', 'Set up a tea party or cooking scenario with dolls. Taking roles in pretend play is social cognition and narrative combined.', 13, '10–15 min', 'Dolls, cups, play food', 'Set up a tea party or cooking scenario with dolls. Taking roles in pretend play is social cognition and narrative combined.'),
  ('self-advocacy-seed-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Self-Advocacy Seed', 'When toddler is upset, model the phrase: ''I don''t like that'' or ''Mujhe yeh pasand nahi.'' Give them words for their feelings.', null, 'Ongoing', 'None', 'When toddler is upset, model the phrase: ''I don''t like that'' or ''Mujhe yeh pasand nahi.'' Give them words for their feelings.'),
  ('comfort-skill-building-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Comfort Skill Building', 'Introduce a simple self-comfort strategy in a calm moment: slow breathing, squeezing a soft object. Practice before it is needed.', 7, '5–8 min', 'Soft object', 'Introduce a simple self-comfort strategy in a calm moment: slow breathing, squeezing a soft object. Practice before it is needed.'),
  ('water-transfer-play-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Water Transfer Play', 'Two containers of water, a cup for transferring. Supervised water play for 15 min. Pouring, splashing, and measuring emerge naturally.', 18, '15–20 min', 'Two containers + cup + water', 'Two containers of water, a cup for transferring. Supervised water play for 15 min. Pouring, splashing, and measuring emerge naturally.'),
  ('playdough-shapes-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Playdough Shapes', 'Roll, flatten, and cut playdough with a blunt knife. Making shapes adds visual-motor control to the tactile input.', 13, '10–15 min', 'Playdough or atta dough', 'Roll, flatten, and cut playdough with a blunt knife. Making shapes adds visual-motor control to the tactile input.'),
  ('nature-scavenger-hunt-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Nature Scavenger Hunt', 'Walk outside and collect one of each: a leaf, a stone, a stick, a feather. Touch and describe each one together.', 25, '20–30 min', 'Bag for collecting', 'Walk outside and collect one of each: a leaf, a stone, a stick, a feather. Touch and describe each one together.'),
  ('bubble-play-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Bubble Play', 'Blow bubbles and let toddler pop them. Tracking, reaching, timing, and the satisfying pop make this multi-sensory and motivating.', 13, '10–15 min', 'Soap + water + wire loop', 'Blow bubbles and let toddler pop them. Tracking, reaching, timing, and the satisfying pop make this multi-sensory and motivating.'),
  ('paint-with-hands-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Paint with Hands', 'Finger painting (food-safe paint or safe craft paint). Each colour is introduced separately. Direct contact with material.', 13, '10–15 min', 'Paint (washable), paper', 'Finger painting (food-safe paint or safe craft paint). Each colour is introduced separately. Direct contact with material.'),
  ('dressing-participation-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Dressing Participation', 'Name each clothing item as it goes on. Ask toddler to help push arm through sleeve or lift foot for shoe. Participation builds independence.', 8, '5–10 min', 'Clothing', 'Name each clothing item as it goes on. Ask toddler to help push arm through sleeve or lift foot for shoe. Participation builds independence.'),
  ('teeth-brushing-ritual-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Teeth Brushing Ritual', 'Brush teeth together at the same time. Letting toddler hold and attempt the brush first builds cooperation with the hygiene routine.', 3, '2–3 min', 'Toothbrush', 'Brush teeth together at the same time. Letting toddler hold and attempt the brush first builds cooperation with the hygiene routine.'),
  ('running-obstacle-course-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Running Obstacle Course', 'Set up household obstacles to run around: chairs, cushions, a line of tape. Navigating while running requires real-time motor planning.', 13, '10–15 min', 'Chairs, cushions, tape', 'Set up household obstacles to run around: chairs, cushions, a line of tape. Navigating while running requires real-time motor planning.'),
  ('jump-over-a-line-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Jump Over a Line', 'Put a tape line on the floor. Jump over with both feet. Clearing an obstacle while jumping = significantly harder than jumping in place.', 4, '3–5 min', 'Masking tape', 'Put a tape line on the floor. Jump over with both feet. Clearing an obstacle while jumping = significantly harder than jumping in place.'),
  ('walk-backward-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Walk Backward', 'Practice walking backward, first holding hands then free. Backward locomotion requires body-awareness and spatial recalibration.', 8, '5–10 min', 'None', 'Practice walking backward, first holding hands then free. Backward locomotion requires body-awareness and spatial recalibration.'),
  ('throw-and-catch-large-ball-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Throw and Catch (Large Ball)', 'Roll a large ball back and forth, then graduate to low throwing and catching. Catching a rolling ball before a thrown one.', 8, '5–10 min', 'Large soft ball', 'Roll a large ball back and forth, then graduate to low throwing and catching. Catching a rolling ball before a thrown one.'),
  ('pedal-a-tricycle-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Pedal a Tricycle', 'Practice on a tricycle or balance bike. Pedalling requires reciprocal leg movement — the same pattern as walking but with sustained force.', 13, '10–15 min', 'Tricycle or balance bike', 'Practice on a tricycle or balance bike. Pedalling requires reciprocal leg movement — the same pattern as walking but with sustained force.'),
  ('gallop-forward-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Gallop Forward', 'Demonstrate a gallop (lead-foot, drag) and encourage copying. Galloping before skipping — the intermediate coordination step.', 8, '5–10 min', 'None', 'Demonstrate a gallop (lead-foot, drag) and encourage copying. Galloping before skipping — the intermediate coordination step.'),
  ('step-alternating-stairs-up-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Step Alternating Stairs (Up)', 'Encourage alternating feet on the way up the stairs. May still need rail; alternating feet up is a 24–30 month milestone.', 8, '5–10 min', 'Stairs', 'Encourage alternating feet on the way up the stairs. May still need rail; alternating feet up is a 24–30 month milestone.'),
  ('push-and-pull-heavy-objects-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Push and Pull Heavy Objects', 'Encourage pushing a chair or pulling a loaded bag. Resistance exercise builds core strength and spatial navigation simultaneously.', 8, '5–10 min', 'Chair or bag with books', 'Encourage pushing a chair or pulling a loaded bag. Resistance exercise builds core strength and spatial navigation simultaneously.'),
  ('copy-drawing-horizontal-line-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Copy Drawing: Horizontal Line', 'Show a horizontal line (left to right) and ask child to copy. Directionality in drawing precedes directionality in writing.', 8, '5–10 min', 'Crayon and paper', 'Show a horizontal line (left to right) and ask child to copy. Directionality in drawing precedes directionality in writing.'),
  ('copy-drawing-circle-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Copy Drawing: Circle', 'Demonstrate a circle slowly and let child try. Circle-copying typically appears 24–30 months — earlier than + or V shapes.', 8, '5–10 min', 'Crayon and paper', 'Demonstrate a circle slowly and let child try. Circle-copying typically appears 24–30 months — earlier than + or V shapes.'),
  ('snip-with-scissors-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Snip with Scissors', 'Child-safe scissors: snip fringe into paper strips. Each snip is a complete bilateral motor action.', 8, '5–10 min', 'Child scissors and paper', 'Child-safe scissors: snip fringe into paper strips. Each snip is a complete bilateral motor action.'),
  ('pour-from-jug-to-cup-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Pour from Jug to Cup', 'Pour water from a small jug into a cup. The control of flow is a daily self-care fine motor skill used for years.', 8, '5–10 min', 'Small jug and cup, water', 'Pour water from a small jug into a cup. The control of flow is a daily self-care fine motor skill used for years.'),
  ('puzzle-8-10-pieces-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Puzzle (8–10 Pieces)', '8–10 piece puzzle requiring rotation and spatial reasoning. Systematically trying each piece before accepting failure is the cognitive goal.', 8, '5–10 min', 'Puzzle', '8–10 piece puzzle requiring rotation and spatial reasoning. Systematically trying each piece before accepting failure is the cognitive goal.'),
  ('sort-colours-3-colours-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Sort Colours (3 Colours)', 'Sort household objects into 3 colour groups. Naming the colours correctly while sorting combines language and cognition.', 8, '5–10 min', 'Coloured household objects', 'Sort household objects into 3 colour groups. Naming the colours correctly while sorting combines language and cognition.'),
  ('200-word-vocabulary-m22_24', 'communication'::domain, 'm22_24'::age_band, '200+ Word Vocabulary', '200 words by 24 months is the benchmark (CDC). Under 50 words by 24 months is worth professional discussion.', null, 'Ongoing', 'None', '200 words by 24 months is the benchmark (CDC). Under 50 words by 24 months is worth professional discussion.'),
  ('two-to-three-word-phrases-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Two- to Three-Word Phrases', 'Mama, more water please.'' Three-word phrases mark a significant vocabulary and grammar step appearing 21–24 months.', null, 'Ongoing', 'None', 'Mama, more water please.'' Three-word phrases mark a significant vocabulary and grammar step appearing 21–24 months.'),
  ('use-i-and-me-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Use ''I'' and ''Me''', 'I want'' and ''Give me'' appearing means self-concept is strongly established. Model these forms throughout the day.', null, 'Ongoing', 'None', 'I want'' and ''Give me'' appearing means self-concept is strongly established. Model these forms throughout the day.'),
  ('ask-open-questions-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Ask Open Questions', 'What happened at the park today?'' Not ''Did you have fun?'' Open questions require memory, sequencing, and language simultaneously.', 8, '5–10 min', 'None', 'What happened at the park today?'' Not ''Did you have fun?'' Open questions require memory, sequencing, and language simultaneously.'),
  ('story-prediction-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Story Prediction', 'During book reading, stop before a page turn: ''What do you think will happen next?'' Prediction requires language plus narrative cognition.', 8, '5–10 min', 'Book', 'During book reading, stop before a page turn: ''What do you think will happen next?'' Prediction requires language plus narrative cognition.'),
  ('name-colours-in-environment-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Name Colours in Environment', 'Not a colour worksheet — just naming colours of real objects throughout the day. Context makes the association stronger.', null, 'Ongoing', 'None', 'Not a colour worksheet — just naming colours of real objects throughout the day. Context makes the association stronger.'),
  ('rhyming-play-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Rhyming Play', 'Cat — bat — sat — mat!'' Rhyming awareness at 24 months predicts reading readiness. Even partial awareness is worth celebrating.', 7, '5–8 min', 'None', 'Cat — bat — sat — mat!'' Rhyming awareness at 24 months predicts reading readiness. Even partial awareness is worth celebrating.'),
  ('describe-daily-events-m22_24', 'communication'::domain, 'm22_24'::age_band, 'Describe Daily Events', 'At bedtime, ask child to tell you two things that happened today. This builds narrative language and episodic memory together.', 8, '5–10 min', 'None', 'At bedtime, ask child to tell you two things that happened today. This builds narrative language and episodic memory together.'),
  ('sort-by-size-big-small-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Sort by Size (Big/Small)', 'Sort objects into two groups: big and small. Size concept develops through sorting, not worksheets.', 8, '5–10 min', 'Objects of two distinct sizes', 'Sort objects into two groups: big and small. Size concept develops through sorting, not worksheets.'),
  ('sequence-daily-routine-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Sequence Daily Routine', 'Ask: ''What do we do after breakfast? Then what?'' Three to four event sequence recall is the target at this age.', 7, '5–8 min', 'None', 'Ask: ''What do we do after breakfast? Then what?'' Three to four event sequence recall is the target at this age.'),
  ('complete-a-simple-pattern-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Complete a Simple Pattern', 'Build a simple colour or shape pattern: red, blue, red, blue — and leave a gap. Can child predict what comes next?', 7, '5–8 min', 'Coloured objects or blocks', 'Build a simple colour or shape pattern: red, blue, red, blue — and leave a gap. Can child predict what comes next?'),
  ('concept-full-and-empty-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Concept: Full and Empty', 'Pour water into an empty glass; let child pour it back. ''Full. Empty. Full again.'' Concrete object manipulation precedes abstract concept.', 8, '5–10 min', 'Glass and water', 'Pour water into an empty glass; let child pour it back. ''Full. Empty. Full again.'' Concrete object manipulation precedes abstract concept.'),
  ('match-photo-to-person-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Match Photo to Person', 'Show baby photos of family members. Can child identify who it is? Memory across time = abstract object permanence.', 7, '5–8 min', 'Family photos', 'Show baby photos of family members. Can child identify who it is? Memory across time = abstract object permanence.'),
  ('counting-with-one-to-one-correspondence-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Counting with One-to-One Correspondence', 'Place 4 objects in a line; touch each as you count 1-2-3-4. Guide child''s hand to touch each. Counting with meaning, not reciting.', 8, '5–10 min', 'Small objects', 'Place 4 objects in a line; touch each as you count 1-2-3-4. Guide child''s hand to touch each. Counting with meaning, not reciting.'),
  ('sharing-practice-guided-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Sharing Practice (Guided)', 'During play: ''You have 4 blocks. Can you give me 2?'' Guided sharing builds number concept alongside social skill.', 8, '5–10 min', 'Blocks or similar', 'During play: ''You have 4 blocks. Can you give me 2?'' Guided sharing builds number concept alongside social skill.'),
  ('cooperative-building-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Cooperative Building', 'Build something together: ''I put one block, you put one block.'' Turn-taking in construction is cooperative play at its clearest.', 8, '5–10 min', 'Blocks', 'Build something together: ''I put one block, you put one block.'' Turn-taking in construction is cooperative play at its clearest.'),
  ('feelings-vocabulary-5-emotions-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Feelings Vocabulary (5 Emotions)', 'Name 5 emotions accurately this week: happy, sad, angry, scared, excited. Emotional vocabulary directly predicts social competence.', null, 'Ongoing', 'None', 'Name 5 emotions accurately this week: happy, sad, angry, scared, excited. Emotional vocabulary directly predicts social competence.'),
  ('pretend-play-elaboration-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Pretend Play Elaboration', 'Join child''s pretend play and add a new element: ''The baby is sleeping — shall we sing her a lori?'' Extending the narrative.', 13, '10–15 min', 'Soft toy', 'Join child''s pretend play and add a new element: ''The baby is sleeping — shall we sing her a lori?'' Extending the narrative.'),
  ('frustration-script-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Frustration Script', 'Teach a specific phrase for frustration: ''I need help'' or ''Mujhe madad chahiye.'' Practice during calm — not during the moment.', 4, '3–5 min', 'None', 'Teach a specific phrase for frustration: ''I need help'' or ''Mujhe madad chahiye.'' Practice during calm — not during the moment.'),
  ('apology-practice-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Apology Practice', 'When child hurts or upsets another: ''What could you say? How do you think they felt?'' Modelling, not forcing. Empathy precedes apology.', 4, '3–5 min', 'None', 'When child hurts or upsets another: ''What could you say? How do you think they felt?'' Modelling, not forcing. Empathy precedes apology.'),
  ('sensory-walk-barefoot-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Sensory Walk Barefoot', 'Walk barefoot on grass, sand, and smooth pavement on the same outing. Noticing the difference is the sensory lesson.', 18, '15–20 min', 'None (outdoors)', 'Walk barefoot on grass, sand, and smooth pavement on the same outing. Noticing the difference is the sensory lesson.'),
  ('mixing-colours-water-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Mixing Colours (Water)', 'Add food colouring to water in clear cups and mix two together. Watching red + blue = purple is both science and sensory.', 8, '5–10 min', 'Clear cups, water, food colouring', 'Add food colouring to water in clear cups and mix two together. Watching red + blue = purple is both science and sensory.'),
  ('musical-instruments-exploration-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Musical Instruments Exploration', 'Pots, boxes, metal bowls — each makes a different sound. Let child experiment with what each material produces.', 8, '5–10 min', 'Pots, boxes, metal containers', 'Pots, boxes, metal bowls — each makes a different sound. Let child experiment with what each material produces.'),
  ('clay-atta-detailed-work-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Clay (Atta) Detailed Work', 'Press small objects into dough to make impressions. Roll thin snakes. Cut with blunt knife. Precision work in tactile medium.', 13, '10–15 min', 'Atta dough and objects to press', 'Press small objects into dough to make impressions. Roll thin snakes. Cut with blunt knife. Precision work in tactile medium.'),
  ('weighted-blanket-cuddle-m22_24', 'cognitive'::domain, 'm22_24'::age_band, 'Weighted Blanket Cuddle', 'Wrap child in a heavy blanket on a lap. Deep pressure input is calming for the autonomic nervous system.', 8, '5–10 min', 'Heavy blanket', 'Wrap child in a heavy blanket on a lap. Deep pressure input is calming for the autonomic nervous system.'),
  ('independent-dressing-simple-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Independent Dressing (Simple)', 'By 24 months: pull trousers up and down, remove shoes and socks, help with shirts. All with support — independence is incremental.', 13, '10–15 min', 'Clothing', 'By 24 months: pull trousers up and down, remove shoes and socks, help with shirts. All with support — independence is incremental.'),
  ('toilet-training-awareness-m22_24', 'social_emotional'::domain, 'm22_24'::age_band, 'Toilet Training Awareness', 'If interest appears: describe what toilet training involves. Let child see the process. No pressure — readiness signs should lead.', null, 'Ongoing', 'Potty (optional)', 'If interest appears: describe what toilet training involves. Let child see the process. No pressure — readiness signs should lead.'),
  ('jump-forward-both-feet-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Jump Forward (Both Feet)', 'Encourage jumping forward from standing, landing on both feet. Distance of jump increases each week as leg strength grows.', 8, '5–10 min', 'None', 'Encourage jumping forward from standing, landing on both feet. Distance of jump increases each week as leg strength grows.'),
  ('walk-on-a-balance-beam-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Walk on a Balance Beam', 'A plank, a garden wall, or tape on the floor. Walk along without falling off. Balance on a narrow path is a 2.5-year skill.', 8, '5–10 min', 'Plank or tape line', 'A plank, a garden wall, or tape on the floor. Walk along without falling off. Balance on a narrow path is a 2.5-year skill.'),
  ('hop-on-one-foot-attempt-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Hop on One Foot (Attempt)', 'Hold child''s hand and encourage hopping on one foot. Even one hop is the milestone beginning — don''t expect sustained hopping yet.', 4, '3–5 min', 'None', 'Hold child''s hand and encourage hopping on one foot. Even one hop is the milestone beginning — don''t expect sustained hopping yet.'),
  ('catch-a-bounced-ball-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Catch a Bounced Ball', 'Bounce a large ball to child. Catching a bounced ball before a thrown one — the visual tracking time is longer.', 8, '5–10 min', 'Large ball', 'Bounce a large ball to child. Catching a bounced ball before a thrown one — the visual tracking time is longer.'),
  ('pedal-with-steering-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Pedal with Steering', 'Tricycle: practice steering around objects. Combining pedalling with directional control is a significant motor coordination step.', 13, '10–15 min', 'Tricycle', 'Tricycle: practice steering around objects. Combining pedalling with directional control is a significant motor coordination step.'),
  ('animal-movement-play-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Animal Movement Play', 'Move like different animals: frog jump, bear walk, crab walk, snake slither. Each uses different muscle groups and movement patterns.', 8, '5–10 min', 'None', 'Move like different animals: frog jump, bear walk, crab walk, snake slither. Each uses different muscle groups and movement patterns.'),
  ('throw-overhand-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Throw Overhand', 'Demonstrate an overhand throw and let child try. Overhand requires trunk rotation — a very different movement than underhand.', 8, '5–10 min', 'Ball', 'Demonstrate an overhand throw and let child try. Overhand requires trunk rotation — a very different movement than underhand.'),
  ('summersault-assisted-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Summersault (Assisted)', 'Help child do a forward roll on a soft surface. Head tuck, push-off, and landing = vestibular, motor, and spatial all together.', 4, '3–5 min', 'Soft mat or rug', 'Help child do a forward roll on a soft surface. Head tuck, push-off, and landing = vestibular, motor, and spatial all together.'),
  ('copy-drawing-plus-sign-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Copy Drawing: Plus Sign (+)', 'Show a + (cross) and let child try. Requires two directional lines crossing — harder than circle; appears around 30–36 months.', 8, '5–10 min', 'Crayon and paper', 'Show a + (cross) and let child try. Requires two directional lines crossing — harder than circle; appears around 30–36 months.'),
  ('use-fork-independently-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Use Fork Independently', 'Fork for stabbing soft foods. The grip and stabbing force are different from a spoon — a distinct fine motor skill.', 13, '10–15 min', 'Fork, food', 'Fork for stabbing soft foods. The grip and stabbing force are different from a spoon — a distinct fine motor skill.'),
  ('dress-a-doll-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Dress a Doll', 'Button, zip, and dress a doll. This is fine motor practice that feels purposeful and maintains engagement longer.', 8, '5–10 min', 'Doll with dressing features', 'Button, zip, and dress a doll. This is fine motor practice that feels purposeful and maintains engagement longer.'),
  ('fold-paper-in-half-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Fold Paper in Half', 'Show folding a piece of paper in half and ask child to try. Aligning edges before folding requires spatial and motor precision.', 7, '5–8 min', 'Paper', 'Show folding a piece of paper in half and ask child to try. Aligning edges before folding requires spatial and motor precision.'),
  ('sort-by-2-attributes-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Sort by 2 Attributes', 'Sort blocks by BOTH colour AND size together. Multi-attribute sorting is more demanding than single-attribute.', 8, '5–10 min', 'Blocks in multiple colours and sizes', 'Sort blocks by BOTH colour AND size together. Multi-attribute sorting is more demanding than single-attribute.'),
  ('lace-a-pattern-board-m25_27', 'motor'::domain, 'm25_27'::age_band, 'Lace a Pattern Board', 'Lace thread through holes to form a simple picture. Requires planning the sequence of holes to achieve the intended shape.', 13, '10–15 min', 'Cardboard with holes and lace', 'Lace thread through holes to form a simple picture. Requires planning the sequence of holes to achieve the intended shape.'),
  ('tell-a-simple-story-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Tell a Simple Story', 'Ask child to tell a story about an animal they know. Even 2–3 sentences with a character is the emergence of narrative.', 8, '5–10 min', 'None', 'Ask child to tell a story about an animal they know. Even 2–3 sentences with a character is the emergence of narrative.'),
  ('ask-and-answer-questions-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Ask and Answer Questions', 'Why does it rain?'' ''What would happen if…?'' Complex question forms are emerging — answer simply and turn it back.', 8, '5–10 min', 'None', 'Why does it rain?'' ''What would happen if…?'' Complex question forms are emerging — answer simply and turn it back.'),
  ('three-to-four-word-sentences-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Three- to Four-Word Sentences', 'Consistent 3–4 word sentences with grammar: ''I want the red ball.'' Grammar errors (''I goed'') are developmentally correct now.', null, 'Ongoing', 'None', 'Consistent 3–4 word sentences with grammar: ''I want the red ball.'' Grammar errors (''I goed'') are developmentally correct now.'),
  ('rhyming-detection-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Rhyming Detection', 'Does cat rhyme with bat? What about cat and dog?'' Detecting rhyme before producing it — typical at 25–30 months.', 7, '5–8 min', 'None', 'Does cat rhyme with bat? What about cat and dog?'' Detecting rhyme before producing it — typical at 25–30 months.'),
  ('describe-a-picture-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Describe a Picture', 'Show a picture and ask ''What is happening here?'' Child describes scene — vocabulary, grammar, and observation all combined.', 7, '5–8 min', 'Picture or book illustration', 'Show a picture and ask ''What is happening here?'' Child describes scene — vocabulary, grammar, and observation all combined.'),
  ('first-and-last-name-m25_27', 'communication'::domain, 'm25_27'::age_band, 'First and Last Name', 'Practice saying full name. ''What is your full name?'' is a social comprehension milestone by age 3.', 4, '3–5 min', 'None', 'Practice saying full name. ''What is your full name?'' is a social comprehension milestone by age 3.'),
  ('conversation-with-questions-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Conversation with Questions', 'Have a 5-turn conversation where child asks at least one question. Asking is more advanced than answering.', 8, '5–10 min', 'None', 'Have a 5-turn conversation where child asks at least one question. Asking is more advanced than answering.'),
  ('story-from-memory-m25_27', 'communication'::domain, 'm25_27'::age_band, 'Story from Memory', 'After reading a favourite book many times, ask child to ''read'' it to you from the pictures. Memory narrative is emerging.', 8, '5–10 min', 'Familiar book', 'After reading a favourite book many times, ask child to ''read'' it to you from the pictures. Memory narrative is emerging.'),
  ('count-objects-to-5-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Count Objects to 5', 'Place up to 5 objects in a line and count together, touching each one. One-to-one correspondence solidifying now.', 7, '5–8 min', '5 small objects', 'Place up to 5 objects in a line and count together, touching each one. One-to-one correspondence solidifying now.'),
  ('basic-opposites-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Basic Opposites', 'Big/small, hot/cold, fast/slow, loud/quiet. Opposites build comparative conceptual thinking.', 7, '5–8 min', 'Objects demonstrating contrast', 'Big/small, hot/cold, fast/slow, loud/quiet. Opposites build comparative conceptual thinking.'),
  ('yesterday-and-today-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Yesterday and Today', 'Yesterday we went to the park. Today we are home.'' Time concepts past/present solidify through consistent narration.', null, 'Ongoing', 'None', 'Yesterday we went to the park. Today we are home.'' Time concepts past/present solidify through consistent narration.'),
  ('sort-4-categories-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Sort 4 Categories', 'Sort objects into 4 groups: food, animals, clothes, vehicles. Four-category sorting is sophisticated categorical thinking.', 8, '5–10 min', 'Assorted household objects', 'Sort objects into 4 groups: food, animals, clothes, vehicles. Four-category sorting is sophisticated categorical thinking.'),
  ('pattern-extension-abab-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Pattern Extension (ABAB)', 'Build red-blue-red-blue and leave a gap: ''What comes next?'' Pattern extension requires holding the rule in working memory.', 7, '5–8 min', 'Coloured objects', 'Build red-blue-red-blue and leave a gap: ''What comes next?'' Pattern extension requires holding the rule in working memory.'),
  ('simple-addition-concept-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Simple Addition Concept', 'Here are 2 bananas. I add 1 more. How many now?'' Concrete addition before abstract number.', 8, '5–10 min', 'Fruit or objects', 'Here are 2 bananas. I add 1 more. How many now?'' Concrete addition before abstract number.'),
  ('imaginary-friend-engagement-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Imaginary Friend Engagement', 'If an imaginary friend appears, engage with them: ''What is their name?'' Imaginary companions support language, emotional, and social development.', 8, '5–10 min', 'None', 'If an imaginary friend appears, engage with them: ''What is their name?'' Imaginary companions support language, emotional, and social development.'),
  ('negotiate-a-trade-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Negotiate a Trade', 'When a conflict arises over a toy: ''What could you offer them to trade?'' Negotiation is a social skill that must be taught explicitly.', 4, '3–5 min', 'None', 'When a conflict arises over a toy: ''What could you offer them to trade?'' Negotiation is a social skill that must be taught explicitly.'),
  ('brag-board-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Brag Board', 'Create a display of child''s achievements (drawings, photos). ''You did all of these!'' Pride in accomplishment is a social-emotional milestone.', 8, '5–10 min', 'Paper and display space', 'Create a display of child''s achievements (drawings, photos). ''You did all of these!'' Pride in accomplishment is a social-emotional milestone.'),
  ('role-play-doctor-chef-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Role Play (Doctor, Chef)', 'Set up a role-play scenario with simple props. Role-play at 25–30 months involves taking on another''s perspective.', 13, '10–15 min', 'Simple props', 'Set up a role-play scenario with simple props. Role-play at 25–30 months involves taking on another''s perspective.'),
  ('regulation-practice-pause-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Regulation Practice: Pause', 'When feelings escalate, say ''Let''s take a pause'' and model slow breathing together. Practice before it is needed.', 4, '3–5 min', 'None', 'When feelings escalate, say ''Let''s take a pause'' and model slow breathing together. Practice before it is needed.'),
  ('ask-how-others-feel-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Ask How Others Feel', 'While reading or in real life: ''How do you think she felt when that happened?'' Perspective-taking practice.', 7, '5–8 min', 'Book or real situation', 'While reading or in real life: ''How do you think she felt when that happened?'' Perspective-taking practice.'),
  ('sensory-art-tissue-paper-collage-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Sensory Art: Tissue Paper Collage', 'Tear and paste coloured tissue paper onto card. Tearing texture, paper texture, and glue texture are layered sensory inputs.', 13, '10–15 min', 'Tissue paper, card, glue', 'Tear and paste coloured tissue paper onto card. Tearing texture, paper texture, and glue texture are layered sensory inputs.'),
  ('outdoor-water-play-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Outdoor Water Play', 'Watering can, puddles, or garden tap. Child-directed water exploration is rich sensory and cause-effect play.', 18, '15–20 min', 'Water, watering can', 'Watering can, puddles, or garden tap. Child-directed water exploration is rich sensory and cause-effect play.'),
  ('texture-sorting-game-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Texture Sorting Game', 'Gather 8 objects of varied texture. Sort into ''rough'' and ''smooth.'' Tactile discrimination is now a language + sensory task.', 8, '5–10 min', '8 household objects', 'Gather 8 objects of varied texture. Sort into ''rough'' and ''smooth.'' Tactile discrimination is now a language + sensory task.'),
  ('proprioceptive-heavy-work-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Proprioceptive Heavy Work', 'Carrying loaded backpack, pushing a box of books, pulling a weighted trolley. Heavy work regulates the nervous system.', 8, '5–10 min', 'Loaded bag or box', 'Carrying loaded backpack, pushing a box of books, pulling a weighted trolley. Heavy work regulates the nervous system.'),
  ('spin-on-spot-m25_27', 'cognitive'::domain, 'm25_27'::age_band, 'Spin on Spot', 'Spin with arms out, stop, try to stay balanced. Vestibular system input — intentional dizziness and recovery is regulating.', 4, '3–5 min', 'None', 'Spin with arms out, stop, try to stay balanced. Vestibular system input — intentional dizziness and recovery is regulating.'),
  ('brush-teeth-independently-attempt-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Brush Teeth Independently (Attempt)', 'Let child brush their own teeth first, then parent finishes. Agency in the sequence builds cooperation with the hygiene routine.', 4, '3–5 min', 'Toothbrush and toothpaste', 'Let child brush their own teeth first, then parent finishes. Agency in the sequence builds cooperation with the hygiene routine.'),
  ('toilet-training-if-ready-m25_27', 'social_emotional'::domain, 'm25_27'::age_band, 'Toilet Training (If Ready)', 'If signs of readiness present (knowing when wet, interest in toilet), begin with simple potty introduction. Never forced.', null, 'Ongoing', 'Potty', 'If signs of readiness present (knowing when wet, interest in toilet), begin with simple potty introduction. Never forced.'),
  ('hop-on-one-foot-3-5-hops-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Hop on One Foot (3–5 Hops)', 'From one hop, build to 3–5 consecutive hops on the same foot. Each hop requires rebalancing — rapid balance adjustment developing.', 7, '5–8 min', 'None', 'From one hop, build to 3–5 consecutive hops on the same foot. Each hop requires rebalancing — rapid balance adjustment developing.'),
  ('skip-gallop-to-skip-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Skip (Gallop to Skip)', 'Most children gallop at 2.5 years and skip at 3.5. Practice gallop leading with each foot as the precursor.', 8, '5–10 min', 'None', 'Most children gallop at 2.5 years and skip at 3.5. Practice gallop leading with each foot as the precursor.'),
  ('catch-a-thrown-ball-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Catch a Thrown Ball', 'Graduate from bounced to thrown ball catching. Tracking the trajectory and adjusting arms = complex visual-motor planning.', 8, '5–10 min', 'Medium ball', 'Graduate from bounced to thrown ball catching. Tracking the trajectory and adjusting arms = complex visual-motor planning.'),
  ('pedal-and-brake-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Pedal and Brake', 'On a tricycle: practice pedalling and stopping at a marked line. Braking intentionally requires coordinated leg action.', 13, '10–15 min', 'Tricycle', 'On a tricycle: practice pedalling and stopping at a marked line. Braking intentionally requires coordinated leg action.'),
  ('climb-ladder-playground-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Climb Ladder (Playground)', 'Climbing a ladder — alternating hands and feet — is the most complex locomotion pattern children this age attempt.', 8, '5–10 min', 'Climbing frame or playground', 'Climbing a ladder — alternating hands and feet — is the most complex locomotion pattern children this age attempt.'),
  ('jump-from-height-30-cm-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Jump from Height (30 cm)', 'Jump off a 30-cm step with both feet landing together. Judging safe heights and landing = spatial and motor cognition combined.', 4, '3–5 min', 'Low step', 'Jump off a 30-cm step with both feet landing together. Judging safe heights and landing = spatial and motor cognition combined.'),
  ('balance-beam-eyes-closed-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Balance Beam (Eyes Closed)', 'Walk a balance beam (tape line) with eyes closed for 2 steps. Eyes-closed balance challenges proprioceptive system intensely.', 7, '5–8 min', 'Tape line', 'Walk a balance beam (tape line) with eyes closed for 2 steps. Eyes-closed balance challenges proprioceptive system intensely.'),
  ('dodge-and-weave-game-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Dodge and Weave Game', 'Chase game where child must dodge around obstacles. Reactive motor planning — responding to unexpected changes in a path.', 13, '10–15 min', 'None', 'Chase game where child must dodge around obstacles. Reactive motor planning — responding to unexpected changes in a path.'),
  ('copy-drawing-v-shape-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Copy Drawing: V Shape', 'Show a V and ask child to copy. Angular shapes (V, then +, then triangle) appear in sequence after circle.', 7, '5–8 min', 'Crayon and paper', 'Show a V and ask child to copy. Angular shapes (V, then +, then triangle) appear in sequence after circle.'),
  ('draw-a-person-head-2-parts-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Draw a Person (Head + 2 Parts)', 'Ask child to draw a person. Head + one other body part by 30 months = fine motor and representational thinking combined.', 8, '5–10 min', 'Crayon and paper', 'Ask child to draw a person. Head + one other body part by 30 months = fine motor and representational thinking combined.'),
  ('scissors-in-a-straight-line-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Scissors in a Straight Line', 'Cut along a straight line drawn on paper. Staying on the line requires visual monitoring while maintaining bilateral grip.', 8, '5–10 min', 'Child scissors and paper', 'Cut along a straight line drawn on paper. Staying on the line requires visual monitoring while maintaining bilateral grip.'),
  ('peel-and-stick-labels-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Peel and Stick Labels', 'Peel self-adhesive stickers and place on a target. Two-stage finger action requiring precise coordination.', 8, '5–10 min', 'Stickers and paper', 'Peel self-adhesive stickers and place on a target. Two-stage finger action requiring precise coordination.'),
  ('build-a-bridge-3-blocks-m28_30', 'motor'::domain, 'm28_30'::age_band, 'Build a Bridge (3 Blocks)', 'Demonstrate placing a block across two towers and ask child to build the same. Copying spatial models = architecture thinking.', 8, '5–10 min', 'Blocks', 'Demonstrate placing a block across two towers and ask child to build the same. Copying spatial models = architecture thinking.'),
  ('string-small-beads-m28_30', 'motor'::domain, 'm28_30'::age_band, 'String Small Beads', 'Small beads on a thin lace. Fine pincer control plus visual targeting plus threading = high-demand fine motor task.', 13, '10–15 min', 'Small beads + thin lace', 'Small beads on a thin lace. Fine pincer control plus visual targeting plus threading = high-demand fine motor task.'),
  ('500-word-vocabulary-m28_30', 'communication'::domain, 'm28_30'::age_band, '500+ Word Vocabulary', 'A 30-month-old typically has 450–600 words. Importantly, sentences are 3–5 words with mostly correct grammar.', null, 'Ongoing', 'None', 'A 30-month-old typically has 450–600 words. Importantly, sentences are 3–5 words with mostly correct grammar.'),
  ('tell-stories-with-beginning-middle-end-m28_30', 'communication'::domain, 'm28_30'::age_band, 'Tell Stories with Beginning-Middle-End', 'Once there was a dog. He was hungry. He found some food and ate it.'' Three-part narrative structure is the target.', 8, '5–10 min', 'None', 'Once there was a dog. He was hungry. He found some food and ate it.'' Three-part narrative structure is the target.'),
  ('because-and-if-sentences-m28_30', 'communication'::domain, 'm28_30'::age_band, 'Because'' and ''If'' Sentences', 'I''m tired because I didn''t sleep.'' ''If it rains, we''ll stay inside.'' Logical connectors mark a grammar milestone.', null, 'Ongoing', 'None', 'I''m tired because I didn''t sleep.'' ''If it rains, we''ll stay inside.'' Logical connectors mark a grammar milestone.'),
  ('describe-how-something-works-m28_30', 'communication'::domain, 'm28_30'::age_band, 'Describe How Something Works', 'How does a tap work?'' Let child explain from their own understanding. Explanatory language is emerging.', 8, '5–10 min', 'Any household object', 'How does a tap work?'' Let child explain from their own understanding. Explanatory language is emerging.'),
  ('rhyme-production-m28_30', 'communication'::domain, 'm28_30'::age_band, 'Rhyme Production', 'I say cat — you say something that rhymes.'' Production (not just detection) of rhymes = phonological awareness step.', 7, '5–8 min', 'None', 'I say cat — you say something that rhymes.'' Production (not just detection) of rhymes = phonological awareness step.'),
  ('letter-name-recognition-own-name-m28_30', 'communication'::domain, 'm28_30'::age_band, 'Letter Name Recognition (Own Name)', 'Recognise the first letter of own name in print. This is enough letter knowledge to celebrate at 30 months.', 7, '5–8 min', 'Paper with child''s name in large letters', 'Recognise the first letter of own name in print. This is enough letter knowledge to celebrate at 30 months.'),
  ('complex-question-response-m28_30', 'communication'::domain, 'm28_30'::age_band, 'Complex Question Response', 'What would you do if it was raining and you wanted to go outside?'' Hypothetical thinking + language combined.', 8, '5–10 min', 'None', 'What would you do if it was raining and you wanted to go outside?'' Hypothetical thinking + language combined.'),
  ('storytelling-from-memory-m28_30', 'communication'::domain, 'm28_30'::age_band, 'Storytelling from Memory', 'Retell a favourite story from memory using the book''s pictures as prompts. 3-event sequence is the typical recall at this age.', 8, '5–10 min', 'Familiar book', 'Retell a favourite story from memory using the book''s pictures as prompts. 3-event sequence is the typical recall at this age.'),
  ('count-to-10-with-meaning-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Count to 10 with Meaning', 'Count 10 objects touching each one. At 30 months, 10-object counting with one-to-one correspondence is an achievable goal.', 7, '5–8 min', '10 small objects', 'Count 10 objects touching each one. At 30 months, 10-object counting with one-to-one correspondence is an achievable goal.'),
  ('concept-same-and-different-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Concept: Same and Different', 'Are these the same or different?'' — with objects that are clearly one or the other. Comparative language + cognition.', 7, '5–8 min', 'Pairs of matching and non-matching objects', 'Are these the same or different?'' — with objects that are clearly one or the other. Comparative language + cognition.'),
  ('categorise-by-function-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Categorise by Function', 'Group things that you eat, things you wear, things you sit on. Sorting by function is more abstract than sorting by appearance.', 8, '5–10 min', 'Household objects', 'Group things that you eat, things you wear, things you sit on. Sorting by function is more abstract than sorting by appearance.'),
  ('spatial-concepts-in-on-under-behind-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Spatial Concepts: In, On, Under, Behind', 'Put the cup on the book. Now under the book.'' Following spatial prepositions in sequence.', 7, '5–8 min', 'Cup and book', 'Put the cup on the book. Now under the book.'' Following spatial prepositions in sequence.'),
  ('day-sequence-morning-afternoon-evening-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Day Sequence: Morning, Afternoon, Evening', 'What do we do in the morning? What happens in the evening?'' Time-of-day sequencing before days of the week.', 7, '5–8 min', 'None', 'What do we do in the morning? What happens in the evening?'' Time-of-day sequencing before days of the week.'),
  ('simple-inference-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Simple Inference', 'While reading: ''Why is the bear sad?'' — answer not in the text but inferrable from pictures. Early inferential thinking.', 8, '5–10 min', 'Picture book', 'While reading: ''Why is the bear sad?'' — answer not in the text but inferrable from pictures. Early inferential thinking.'),
  ('play-in-small-group-3-children-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Play in Small Group (3 Children)', 'Facilitate play in a group of 3. Children this age can begin brief cooperative interaction — note who initiates and who follows.', 18, '15–20 min', 'None', 'Facilitate play in a group of 3. Children this age can begin brief cooperative interaction — note who initiates and who follows.'),
  ('express-feelings-with-words-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Express Feelings With Words', 'Mujhe gussa aa raha hai'' or ''I feel scared.'' Verbal emotion expression before or instead of physical expression.', null, 'Ongoing', 'None', 'Mujhe gussa aa raha hai'' or ''I feel scared.'' Verbal emotion expression before or instead of physical expression.'),
  ('help-a-younger-child-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Help a Younger Child', 'When a younger child needs help with something child can do: ''Can you show them how to stack the blocks?'' Pro-social seed.', 8, '5–10 min', 'None', 'When a younger child needs help with something child can do: ''Can you show them how to stack the blocks?'' Pro-social seed.'),
  ('choose-an-activity-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Choose an Activity', 'Offer 3 activities and let child choose. ''What would you like to do first?'' Autonomous choice builds decision-making.', null, 'Ongoing', '3 activity options', 'Offer 3 activities and let child choose. ''What would you like to do first?'' Autonomous choice builds decision-making.'),
  ('deal-with-disappointment-script-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Deal with Disappointment Script', 'When something doesn''t happen as planned, narrate: ''You''re disappointed. That was important to you. Let''s think about what we can do.''', 4, '3–5 min', 'None', 'When something doesn''t happen as planned, narrate: ''You''re disappointed. That was important to you. Let''s think about what we can do.'''),
  ('fairness-conversations-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Fairness Conversations', 'Is it fair that she got 3 and you got 2?'' Fairness reasoning appears at 2.5 years and is important to take seriously.', 7, '5–8 min', 'None', 'Is it fair that she got 3 and you got 2?'' Fairness reasoning appears at 2.5 years and is important to take seriously.'),
  ('cornstarch-goop-oobleck-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Cornstarch Goop (Oobleck)', 'Mix cornstarch and water — it''s both solid and liquid. Scientifically bizarre sensory experience. Let child explore freely.', 18, '15–20 min', 'Cornstarch and water', 'Mix cornstarch and water — it''s both solid and liquid. Scientifically bizarre sensory experience. Let child explore freely.'),
  ('sound-walk-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Sound Walk', 'Walk outside listening only — no talking. Point at sounds. Back home, draw or describe what you heard. Auditory attention focus.', 18, '15–20 min', 'None (outdoors)', 'Walk outside listening only — no talking. Point at sounds. Back home, draw or describe what you heard. Auditory attention focus.'),
  ('temperature-sensory-bin-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Temperature Sensory Bin', 'Ice cubes in a bin of warm water. Feeling both together, watching ice melt. Temperature + observation + language.', 13, '10–15 min', 'Ice, warm water, container', 'Ice cubes in a bin of warm water. Feeling both together, watching ice melt. Temperature + observation + language.'),
  ('yoga-for-kids-3-poses-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Yoga for Kids (3 Poses)', 'Teach 3 simple yoga poses: tree, mountain, downward dog. Proprioceptive + balance + breath awareness combined.', 8, '5–10 min', 'None', 'Teach 3 simple yoga poses: tree, mountain, downward dog. Proprioceptive + balance + breath awareness combined.'),
  ('spin-top-or-gyroscope-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Spin Top or Gyroscope', 'Let child spin a top and watch. The visual tracking of a spinning object is uniquely absorbing at this age.', 7, '5–8 min', 'Top (or any spinning object)', 'Let child spin a top and watch. The visual tracking of a spinning object is uniquely absorbing at this age.'),
  ('pour-own-drink-jug-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Pour Own Drink (Jug)', 'Pour their own water from a small child-sized jug into a cup at meals. Independence in self-care + fine motor + self-regulation.', null, 'Ongoing', 'Small jug and cup', 'Pour their own water from a small child-sized jug into a cup at meals. Independence in self-care + fine motor + self-regulation.'),
  ('help-set-the-table-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Help Set the Table', 'Carry plates, fold napkins, place cutlery. Table-setting is fine motor + sequencing + contribution to family life.', 8, '5–10 min', 'Tableware', 'Carry plates, fold napkins, place cutlery. Table-setting is fine motor + sequencing + contribution to family life.'),
  ('hop-5-times-one-foot-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Hop 5+ Times (One Foot)', 'Sustained hopping on one foot — first dominant then non-dominant. Non-dominant hopping develops several months after dominant.', 4, '3–5 min', 'None', 'Sustained hopping on one foot — first dominant then non-dominant. Non-dominant hopping develops several months after dominant.'),
  ('broad-jump-forward-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Broad Jump (Forward)', 'Mark a starting line with tape. Jump forward as far as possible, both feet together. Measure distance — it increases weekly.', 4, '3–5 min', 'Tape', 'Mark a starting line with tape. Jump forward as far as possible, both feet together. Measure distance — it increases weekly.'),
  ('throw-at-a-vertical-target-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Throw at a Vertical Target', 'Tape a target circle on the wall at chest height. Throw a soft ball to hit it. Aimed at a vertical target = new motor challenge.', 7, '5–8 min', 'Soft ball, tape on wall', 'Tape a target circle on the wall at chest height. Throw a soft ball to hit it. Aimed at a vertical target = new motor challenge.'),
  ('ride-tricycle-fast-and-slow-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Ride Tricycle Fast and Slow', 'Pedal fast when you say go, slow when you say stop. Speed regulation while pedalling requires real-time motor control.', 13, '10–15 min', 'Tricycle', 'Pedal fast when you say go, slow when you say stop. Speed regulation while pedalling requires real-time motor control.'),
  ('walk-backward-on-balance-beam-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Walk Backward on Balance Beam', 'Backward walking on a balance beam (tape line) — balance plus motor sequencing in an unusual direction.', 7, '5–8 min', 'Tape line', 'Backward walking on a balance beam (tape line) — balance plus motor sequencing in an unusual direction.'),
  ('obstacle-course-run-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Obstacle Course Run', 'A full obstacle course: run, jump over, crawl under, balance on, throw at. Complex movement sequence requiring memory of order.', 13, '10–15 min', 'Chairs, cushions, tape, ball', 'A full obstacle course: run, jump over, crawl under, balance on, throw at. Complex movement sequence requiring memory of order.'),
  ('throw-and-run-combination-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Throw and Run Combination', 'Throw a ball, run to get it, throw again. Sequencing two motor actions with a transition tests motor working memory.', 8, '5–10 min', 'Ball', 'Throw a ball, run to get it, throw again. Sequencing two motor actions with a transition tests motor working memory.'),
  ('marching-in-place-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Marching in Place', 'Lift knees high and march in time to music. Rhythmic bilateral motor coordination and gross motor control.', 8, '5–10 min', 'Music source', 'Lift knees high and march in time to music. Rhythmic bilateral motor coordination and gross motor control.'),
  ('copy-drawing-square-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Copy Drawing: Square', 'Square (4 equal sides, 4 corners) is harder than a circle — requires direction changes at precise points. Appears ~33–36 months.', 8, '5–10 min', 'Crayon and paper', 'Square (4 equal sides, 4 corners) is harder than a circle — requires direction changes at precise points. Appears ~33–36 months.'),
  ('draw-a-person-head-4-parts-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Draw a Person (Head + 4 Parts)', 'Head, eyes, arms, legs. Drawing a person with 4 identifiable features is a 3-year representational drawing milestone.', 8, '5–10 min', 'Crayon and paper', 'Head, eyes, arms, legs. Drawing a person with 4 identifiable features is a 3-year representational drawing milestone.'),
  ('cut-a-curved-line-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Cut a Curved Line', 'After mastering straight-line cutting, introduce a curve to cut along. Following a curve requires continuous adjustment.', 8, '5–10 min', 'Child scissors and paper', 'After mastering straight-line cutting, introduce a curve to cut along. Following a curve requires continuous adjustment.'),
  ('button-large-buttons-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Button Large Buttons', 'Demonstrate and let child practice buttoning a shirt or coat with large buttons. Fine pincer + hand-eye coordination.', 8, '5–10 min', 'Shirt or coat with large buttons', 'Demonstrate and let child practice buttoning a shirt or coat with large buttons. Fine pincer + hand-eye coordination.'),
  ('weave-paper-strips-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Weave Paper Strips', 'Weave paper strips over and under to make a simple mat. The alternating pattern requires sustained visual-motor tracking.', 13, '10–15 min', 'Paper strips in two colours', 'Weave paper strips over and under to make a simple mat. The alternating pattern requires sustained visual-motor tracking.'),
  ('trace-letters-own-name-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Trace Letters (Own Name)', 'Trace the letters of own name with a finger, then crayon. Letter tracing before writing = spatial learning of letter forms.', 8, '5–10 min', 'Paper with large name printed', 'Trace the letters of own name with a finger, then crayon. Letter tracing before writing = spatial learning of letter forms.'),
  ('700-900-word-vocabulary-m31_33', 'communication'::domain, 'm31_33'::age_band, '700–900 Word Vocabulary', 'By 33 months, vocabulary typically 700–900 words with 5–6 word sentences used consistently.', null, 'Ongoing', 'None', 'By 33 months, vocabulary typically 700–900 words with 5–6 word sentences used consistently.'),
  ('why-conversation-chain-m31_33', 'communication'::domain, 'm31_33'::age_band, 'Why'' Conversation Chain', 'Follow a chain of ''why'' questions: ''Why does it rain?'' → ''Because the clouds get heavy.'' → ''Why do they get heavy?'' Sustain 3 turns.', 8, '5–10 min', 'None', 'Follow a chain of ''why'' questions: ''Why does it rain?'' → ''Because the clouds get heavy.'' → ''Why do they get heavy?'' Sustain 3 turns.'),
  ('name-all-basic-colours-m31_33', 'communication'::domain, 'm31_33'::age_band, 'Name All Basic Colours', 'Red, blue, green, yellow, orange, purple, black, white. Naming all basic colours correctly is a 3-year language milestone.', 4, '3–5 min', 'Coloured objects', 'Red, blue, green, yellow, orange, purple, black, white. Naming all basic colours correctly is a 3-year language milestone.'),
  ('use-plurals-correctly-m31_33', 'communication'::domain, 'm31_33'::age_band, 'Use Plurals Correctly', 'Two dogs, three cats.'' Plural ''-s'' rule solidifying. Point out examples: ''Look — two birds. Birds — more than one.''', null, 'Ongoing', 'None', 'Two dogs, three cats.'' Plural ''-s'' rule solidifying. Point out examples: ''Look — two birds. Birds — more than one.'''),
  ('past-tense-regular-verbs-m31_33', 'communication'::domain, 'm31_33'::age_band, 'Past Tense Regular Verbs', 'I walked. We played. She jumped.'' Regular past tense (-ed) appearing. Irregular past (''went'', ''ran'') still developing.', null, 'Ongoing', 'None', 'I walked. We played. She jumped.'' Regular past tense (-ed) appearing. Irregular past (''went'', ''ran'') still developing.'),
  ('describe-what-you-see-m31_33', 'communication'::domain, 'm31_33'::age_band, 'Describe What You See', 'Tell me everything you see in this picture.'' Descriptive language drill — vocabulary, grammar, and observation combined.', 8, '5–10 min', 'Any detailed picture or illustration', 'Tell me everything you see in this picture.'' Descriptive language drill — vocabulary, grammar, and observation combined.'),
  ('conditional-sentences-m31_33', 'communication'::domain, 'm31_33'::age_band, 'Conditional Sentences', 'If we water the plant, it will grow.'' If-then reasoning expressed in language — logical thinking made verbal.', 8, '5–10 min', 'None', 'If we water the plant, it will grow.'' If-then reasoning expressed in language — logical thinking made verbal.'),
  ('letter-sound-introduction-3-letters-m31_33', 'communication'::domain, 'm31_33'::age_band, 'Letter Sound Introduction (3 Letters)', 'Introduce 3 letter sounds: ''A says ah, B says bah, M says mah.'' Sound-letter pairs before letter names — phonics groundwork.', 7, '5–8 min', 'Paper with 3 letters printed', 'Introduce 3 letter sounds: ''A says ah, B says bah, M says mah.'' Sound-letter pairs before letter names — phonics groundwork.'),
  ('count-to-15-with-meaning-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Count to 15 with Meaning', 'Extend counting to 15 objects with one-to-one correspondence. Counting past 10 requires learning the teen number pattern.', 7, '5–8 min', '15 small objects', 'Extend counting to 15 objects with one-to-one correspondence. Counting past 10 requires learning the teen number pattern.'),
  ('name-all-basic-shapes-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Name All Basic Shapes', 'Circle, square, triangle, rectangle, oval. Naming all 5 basic shapes by name = geometry milestone at 33 months.', 7, '5–8 min', 'Shape cut-outs or drawings', 'Circle, square, triangle, rectangle, oval. Naming all 5 basic shapes by name = geometry milestone at 33 months.'),
  ('more-and-fewer-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'More and Fewer', 'Place 3 objects here and 5 there. ''Which group has more?'' Comparative quantity — not counting, but visual quantity judgement.', 7, '5–8 min', 'Two groups of objects', 'Place 3 objects here and 5 there. ''Which group has more?'' Comparative quantity — not counting, but visual quantity judgement.'),
  ('memory-game-6-pairs-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Memory Game (6 Pairs)', '6 matching pairs face-down. Turn 2, find matches. Working memory and concentration targeted directly.', 13, '10–15 min', '12 cards in 6 matching pairs', '6 matching pairs face-down. Turn 2, find matches. Working memory and concentration targeted directly.'),
  ('sequence-a-story-4-pictures-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Sequence a Story (4 Pictures)', '4 story pictures out of order. Can child arrange them in logical sequence? Narrative + causal reasoning combined.', 8, '5–10 min', '4 sequential pictures', '4 story pictures out of order. Can child arrange them in logical sequence? Narrative + causal reasoning combined.'),
  ('concept-first-middle-last-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Concept: First, Middle, Last', 'Line up 3 objects. ''Which is first? Last? Middle?'' Ordinal position language builds mathematical foundation.', 7, '5–8 min', '3 objects in a line', 'Line up 3 objects. ''Which is first? Last? Middle?'' Ordinal position language builds mathematical foundation.'),
  ('friend-concept-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Friend Concept', 'Who is your friend? What do you like about them?'' Friendship awareness at 31–33 months is a social milestone.', 8, '5–10 min', 'None', 'Who is your friend? What do you like about them?'' Friendship awareness at 31–33 months is a social milestone.'),
  ('take-turns-in-group-game-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Take Turns in Group Game', 'Play a group game with 3–4 children where turns rotate. Supporting turn-taking in a group is more complex than in a pair.', 13, '10–15 min', 'Group game', 'Play a group game with 3–4 children where turns rotate. Supporting turn-taking in a group is more complex than in a pair.'),
  ('accepting-no-practice-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Accepting ''No'' Practice', 'When a request must be declined, practice accepting it with words: ''Okay, maybe later.'' Delayed gratification is teachable.', null, 'Ongoing', 'None', 'When a request must be declined, practice accepting it with words: ''Okay, maybe later.'' Delayed gratification is teachable.'),
  ('cooperative-drawing-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Cooperative Drawing', 'Two people draw on the same paper at the same time. Sharing a creative space without conflict is social maturity.', 8, '5–10 min', 'Large paper and crayons for two', 'Two people draw on the same paper at the same time. Sharing a creative space without conflict is social maturity.'),
  ('identify-emotions-in-others-real-life-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Identify Emotions in Others (Real Life)', 'Dadi looks tired today. What do you think she needs?'' Reading real (not illustrated) emotional states is a harder skill.', null, 'Ongoing', 'None', 'Dadi looks tired today. What do you think she needs?'' Reading real (not illustrated) emotional states is a harder skill.'),
  ('comfort-peer-in-distress-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Comfort Peer in Distress', 'When another child is upset: ''Can you think of something that might help them feel better?'' Pro-social action seeded.', null, 'Ongoing', 'None', 'When another child is upset: ''Can you think of something that might help them feel better?'' Pro-social action seeded.'),
  ('mud-kitchen-play-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Mud Kitchen Play', 'Outdoors: soil, water, pots, spoons. Make ''food'', serve it, clean up. Sensory + imaginative + gross + fine motor all together.', 25, '20–30 min', 'Soil, water, pots, spoons (outdoors)', 'Outdoors: soil, water, pots, spoons. Make ''food'', serve it, clean up. Sensory + imaginative + gross + fine motor all together.'),
  ('shadow-play-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Shadow Play', 'In bright sunlight, make and change shadow shapes. Tracing shadows on paper. Visual perception + fine motor + science.', 13, '10–15 min', 'Sunlight or torch', 'In bright sunlight, make and change shadow shapes. Tracing shadows on paper. Visual perception + fine motor + science.'),
  ('magnet-exploration-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Magnet Exploration', 'A magnet and various household objects. Which ones stick? Systematic testing of a material property.', 13, '10–15 min', 'Magnet (fridge magnet) + household objects', 'A magnet and various household objects. Which ones stick? Systematic testing of a material property.'),
  ('rhythm-clapping-patterns-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Rhythm Clapping Patterns', 'Clap a 3-beat pattern and ask child to copy. Grade to 4-beat. Rhythmic working memory and motor sequencing.', 7, '5–8 min', 'None', 'Clap a 3-beat pattern and ask child to copy. Grade to 4-beat. Rhythmic working memory and motor sequencing.'),
  ('blindfold-texture-guess-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Blindfold Texture Guess', 'Blindfold or closed eyes; feel an object and name it. Tactile recognition without visual aid.', 8, '5–10 min', 'Blindfold + household objects', 'Blindfold or closed eyes; feel an object and name it. Tactile recognition without visual aid.'),
  ('help-prepare-a-simple-snack-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Help Prepare a Simple Snack', 'Peel a banana, spread butter on toast, pour cereal. Contributing to own food preparation builds self-care and agency.', 13, '10–15 min', 'Simple food preparation items', 'Peel a banana, spread butter on toast, pour cereal. Contributing to own food preparation builds self-care and agency.'),
  ('dress-independently-simple-items-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Dress Independently (Simple Items)', 'By 33 months: pull trousers up/down, put on shoes (even wrong feet), put on hat, take off jacket. Independence in sequence.', 8, '5–10 min', 'Clothing', 'By 33 months: pull trousers up/down, put on shoes (even wrong feet), put on hat, take off jacket. Independence in sequence.'),
  ('skip-alternating-feet-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Skip (Alternating Feet)', 'True skipping — step-hop alternating feet — typically appears 3.5–4 years. Practice the step-hop on each foot separately first.', 8, '5–10 min', 'None', 'True skipping — step-hop alternating feet — typically appears 3.5–4 years. Practice the step-hop on each foot separately first.'),
  ('throw-and-catch-tennis-ball-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Throw and Catch (Tennis Ball)', 'Tennis-ball-sized throw and catch at 2 metres. Smaller ball demands greater precision than large-ball catching.', 8, '5–10 min', 'Tennis ball or similar', 'Tennis-ball-sized throw and catch at 2 metres. Smaller ball demands greater precision than large-ball catching.'),
  ('hop-10-times-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Hop 10+ Times', '10+ consecutive hops on the preferred foot. Non-preferred foot at this stage is typically 5–8 hops.', 4, '3–5 min', 'None', '10+ consecutive hops on the preferred foot. Non-preferred foot at this stage is typically 5–8 hops.'),
  ('broad-jump-over-line-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Broad Jump Over Line', 'Mark two lines 40 cm apart. Jump from one to the other with both feet. Distance increases as leg strength and timing improve.', 4, '3–5 min', 'Two tape lines', 'Mark two lines 40 cm apart. Jump from one to the other with both feet. Distance increases as leg strength and timing improve.'),
  ('balance-on-one-foot-5-seconds-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Balance on One Foot (5 Seconds)', '5-second one-foot balance without support. Practice eyes open then eventually eyes closed.', 4, '3–5 min', 'None', '5-second one-foot balance without support. Practice eyes open then eventually eyes closed.'),
  ('dribble-a-ball-bouncing-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Dribble a Ball (Bouncing)', 'Bounce and catch a ball repeatedly. Dribbling (bouncing without catching) is harder and typically 4–5 years.', 8, '5–10 min', 'Medium ball', 'Bounce and catch a ball repeatedly. Dribbling (bouncing without catching) is harder and typically 4–5 years.'),
  ('move-to-music-rhythm-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Move to Music (Rhythm)', 'Move to the beat of different musical styles. Rhythmic entrainment — body movement matching musical tempo — is a motor milestone.', 8, '5–10 min', 'Music source', 'Move to the beat of different musical styles. Rhythmic entrainment — body movement matching musical tempo — is a motor milestone.'),
  ('gallop-with-object-in-hand-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Gallop with Object in Hand', 'Gallop while holding an object in one hand. Dual-task motor automatisation: galloping becomes automatic enough for a second task.', 8, '5–10 min', 'Small lightweight object', 'Gallop while holding an object in one hand. Dual-task motor automatisation: galloping becomes automatic enough for a second task.'),
  ('copy-drawing-triangle-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Copy Drawing: Triangle', 'Triangle requires three directional line changes at precise angles. Typically appearing 36 months — harder than square.', 8, '5–10 min', 'Crayon and paper', 'Triangle requires three directional line changes at precise angles. Typically appearing 36 months — harder than square.'),
  ('draw-a-person-6-parts-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Draw a Person (6 Parts)', 'Head, body, 2 arms, 2 legs. By 36 months: 6-part person is the benchmark drawing milestone.', 8, '5–10 min', 'Crayon and paper', 'Head, body, 2 arms, 2 legs. By 36 months: 6-part person is the benchmark drawing milestone.'),
  ('copy-first-name-tracing-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Copy First Name (Tracing)', 'Trace each letter of first name carefully. Letter-form learning happens through the motor movement, not just visual recognition.', 8, '5–10 min', 'Paper with large name printed', 'Trace each letter of first name carefully. Letter-form learning happens through the motor movement, not just visual recognition.'),
  ('use-child-scissors-for-shape-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Use Child Scissors for Shape', 'Cut out a simple shape (circle or triangle) drawn on paper. Following curved and angular lines in cutting.', 8, '5–10 min', 'Child scissors and paper', 'Cut out a simple shape (circle or triangle) drawn on paper. Following curved and angular lines in cutting.'),
  ('fold-paper-into-envelope-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Fold Paper into Envelope', 'Fold a piece of paper in thirds and tuck in the edges to make a simple envelope. Spatial folding and precise crease-making.', 8, '5–10 min', 'Paper', 'Fold a piece of paper in thirds and tuck in the edges to make a simple envelope. Spatial folding and precise crease-making.'),
  ('build-complex-block-structures-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Build Complex Block Structures', 'Build a house, bridge, or tower using a picture as a model. Copying a 3D structure from a 2D picture is abstract spatial cognition.', 13, '10–15 min', 'Blocks', 'Build a house, bridge, or tower using a picture as a model. Copying a 3D structure from a 2D picture is abstract spatial cognition.'),
  ('1000-word-vocabulary-m34_36', 'communication'::domain, 'm34_36'::age_band, '1000+ Word Vocabulary', 'At 36 months, vocabulary typically 900–1200 words. Strangers should understand 75–100% of speech by this age.', null, 'Ongoing', 'None', 'At 36 months, vocabulary typically 900–1200 words. Strangers should understand 75–100% of speech by this age.'),
  ('retell-a-story-sequence-m34_36', 'communication'::domain, 'm34_36'::age_band, 'Retell a Story (Sequence)', 'After reading a book, ask child to retell it in order without pictures. 4-event sequence recall is the 3-year target.', 8, '5–10 min', 'Familiar book', 'After reading a book, ask child to retell it in order without pictures. 4-event sequence recall is the 3-year target.'),
  ('use-past-and-future-tense-m34_36', 'communication'::domain, 'm34_36'::age_band, 'Use Past and Future Tense', 'Yesterday I played. Tomorrow we will go.'' Past and future tense correct usage is a 3-year grammar milestone.', null, 'Ongoing', 'None', 'Yesterday I played. Tomorrow we will go.'' Past and future tense correct usage is a 3-year grammar milestone.'),
  ('explain-how-something-works-m34_36', 'communication'::domain, 'm34_36'::age_band, 'Explain How Something Works', 'Why does the ball roll? Why does the fan spin?'' 3-year-olds begin to explain mechanisms, not just name them.', 8, '5–10 min', 'None', 'Why does the ball roll? Why does the fan spin?'' 3-year-olds begin to explain mechanisms, not just name them.'),
  ('letter-sound-game-5-letters-m34_36', 'communication'::domain, 'm34_36'::age_band, 'Letter Sound Game (5 Letters)', 'What sound does S make? Dog starts with what letter?'' 5-letter sound associations by 36 months = strong phonics foundation.', 7, '5–8 min', 'None', 'What sound does S make? Dog starts with what letter?'' 5-letter sound associations by 36 months = strong phonics foundation.'),
  ('5-word-sentences-complex-m34_36', 'communication'::domain, 'm34_36'::age_band, '5-Word Sentences (Complex)', 'The big red dog ran away.'' Complex sentences with adjectives and adverbs consistently = strong language development.', null, 'Ongoing', 'None', 'The big red dog ran away.'' Complex sentences with adjectives and adverbs consistently = strong language development.'),
  ('debate-why-is-x-better-m34_36', 'communication'::domain, 'm34_36'::age_band, 'Debate: Why is X Better?', 'Is a cat or a dog better to have? Why?'' Opinion + justification: the beginning of argument and persuasive language.', 8, '5–10 min', 'None', 'Is a cat or a dog better to have? Why?'' Opinion + justification: the beginning of argument and persuasive language.'),
  ('rhyme-a-word-family-m34_36', 'communication'::domain, 'm34_36'::age_band, 'Rhyme a Word Family', 'Cat, bat, sat, hat, rat — all rhyme. What else rhymes with cat?'' Generating rhymes from a family = phonological fluency.', 7, '5–8 min', 'None', 'Cat, bat, sat, hat, rat — all rhyme. What else rhymes with cat?'' Generating rhymes from a family = phonological fluency.'),
  ('count-to-20-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Count to 20', 'Count 20 objects one-to-one. Past 12, children must remember the teen pattern; past 20, the decade pattern begins.', 7, '5–8 min', '20 small objects', 'Count 20 objects one-to-one. Past 12, children must remember the teen pattern; past 20, the decade pattern begins.'),
  ('concept-of-zero-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Concept of Zero', 'How many elephants are on this table? Zero. Zero means none.'' Zero as a quantity is an abstract concept to teach explicitly.', 7, '5–8 min', 'None', 'How many elephants are on this table? Zero. Zero means none.'' Zero as a quantity is an abstract concept to teach explicitly.'),
  ('name-10-colours-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Name 10 Colours', 'Red, blue, green, yellow, orange, purple, pink, black, white, brown. Naming all 10 basic colours by 36 months is solid.', 7, '5–8 min', 'Coloured objects', 'Red, blue, green, yellow, orange, purple, pink, black, white, brown. Naming all 10 basic colours by 36 months is solid.'),
  ('days-of-the-week-introduction-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Days of the Week Introduction', 'Sing or say days of the week in sequence. Memorising the sequence before understanding the concept — sequence comes first.', 7, '5–8 min', 'None', 'Sing or say days of the week in sequence. Memorising the sequence before understanding the concept — sequence comes first.'),
  ('pattern-prediction-aabb-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Pattern Prediction (AABB)', 'AABB pattern: red, red, blue, blue, red, red… ''What comes next?'' Two-repeat pattern is harder than ABAB.', 7, '5–8 min', 'Coloured objects', 'AABB pattern: red, red, blue, blue, red, red… ''What comes next?'' Two-repeat pattern is harder than ABAB.'),
  ('cause-effect-explanation-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Cause-Effect Explanation', 'Why did that happen? What caused it?'' Causal explanation — not just observation but mechanism — is a 3-year cognitive goal.', 8, '5–10 min', 'None', 'Why did that happen? What caused it?'' Causal explanation — not just observation but mechanism — is a 3-year cognitive goal.'),
  ('cooperative-game-rules-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Cooperative Game (Rules)', 'Play a simple game with explicit rules (ludo, snap). Following rules in a game is the first social contract — a major SE milestone.', 13, '10–15 min', 'Simple card or board game', 'Play a simple game with explicit rules (ludo, snap). Following rules in a game is the first social contract — a major SE milestone.'),
  ('conflict-resolution-script-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Conflict Resolution Script', 'Teach: ''Stop. Think. Speak.'' When a conflict happens, model the steps: pause, consider the other person, use words.', 4, '3–5 min', 'None', 'Teach: ''Stop. Think. Speak.'' When a conflict happens, model the steps: pause, consider the other person, use words.'),
  ('recognise-own-feelings-early-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Recognise Own Feelings Early', 'I notice your face looks cross. Are you feeling frustrated before it comes out big?'' Self-awareness before dysregulation.', null, 'Ongoing', 'None', 'I notice your face looks cross. Are you feeling frustrated before it comes out big?'' Self-awareness before dysregulation.'),
  ('apology-with-empathy-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Apology with Empathy', 'I''m sorry I took your toy. I know that made you sad.'' Empathy embedded in apology: what they did + how the other felt.', null, 'Ongoing', 'None', 'I''m sorry I took your toy. I know that made you sad.'' Empathy embedded in apology: what they did + how the other felt.'),
  ('winning-and-losing-gracefully-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Winning and Losing Gracefully', 'Practice in a real game. Celebrate both: ''You lost this time and stayed kind. That is very hard and very mature.''', 13, '10–15 min', 'Game', 'Practice in a real game. Celebrate both: ''You lost this time and stayed kind. That is very hard and very mature.'''),
  ('best-friend-identification-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Best-Friend Identification', 'Who is your favourite person to play with? What do you do together?'' Intentional friendship at 3 is a social milestone.', 8, '5–10 min', 'None', 'Who is your favourite person to play with? What do you do together?'' Intentional friendship at 3 is a social milestone.'),
  ('resist-and-wait-practice-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Resist-and-Wait Practice', 'I know you want it now. Let''s wait 2 minutes together.'' Practise with a timer. Delayed gratification is a teachable executive function.', 4, '2–5 min', 'Timer', 'I know you want it now. Let''s wait 2 minutes together.'' Practise with a timer. Delayed gratification is a teachable executive function.'),
  ('slime-making-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Slime Making', 'Mix glue and bicarbonate of soda (or contact lens solution). Unique tactile input — stretchy, gooey, satisfying. Full sensory engagement.', 18, '15–20 min', 'PVA glue, bicarbonate of soda, contact lens solution', 'Mix glue and bicarbonate of soda (or contact lens solution). Unique tactile input — stretchy, gooey, satisfying. Full sensory engagement.'),
  ('sensory-story-walk-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Sensory Story Walk', 'Walk a route where child closes eyes at each stop and describes what they hear and feel. One sense at a time, deliberately.', 25, '20–30 min', 'None (outdoors)', 'Walk a route where child closes eyes at each stop and describes what they hear and feel. One sense at a time, deliberately.'),
  ('nature-printing-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Nature Printing', 'Press leaves, bark, or flowers with paint onto paper. The texture transfer is visual, tactile, and creative simultaneously.', 13, '10–15 min', 'Leaves, paint, paper', 'Press leaves, bark, or flowers with paint onto paper. The texture transfer is visual, tactile, and creative simultaneously.'),
  ('blindfold-object-guess-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Blindfold Object Guess', 'Feel objects in a bag without looking. Name or describe them. Pure tactile recognition with language challenge added.', 8, '5–10 min', 'Bag + household objects', 'Feel objects in a bag without looking. Name or describe them. Pure tactile recognition with language challenge added.'),
  ('rhythm-band-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Rhythm Band', 'Assign different percussion sounds to different family members. Create a rhythm piece together. Auditory + motor + social.', 13, '10–15 min', 'Pots, spoons, containers', 'Assign different percussion sounds to different family members. Create a rhythm piece together. Auditory + motor + social.'),
  ('simple-self-care-sequence-morning-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Simple Self-Care Sequence (Morning)', 'Wake, toilet, wash face, brush teeth, dress — child does as much as possible. Independence in sequence, not perfection in execution.', 18, '15–20 min', 'Clothing, towel, toothbrush', 'Wake, toilet, wash face, brush teeth, dress — child does as much as possible. Independence in sequence, not perfection in execution.'),
  ('help-with-household-chores-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Help with Household Chores', 'Set the table, put laundry in the basket, water a plant. Contributing to household function builds competence and belonging.', 8, '5–10 min', 'Household items', 'Set the table, put laundry in the basket, water a plant. Contributing to household function builds competence and belonging.'),
  ('skip-distance-challenge-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Skip Distance Challenge', 'Skip from one end of the room to the other. Alternate leading foot each trip. Distance and coordination both increase weekly.', 8, '5–10 min', 'None', 'Skip from one end of the room to the other. Alternate leading foot each trip. Distance and coordination both increase weekly.'),
  ('gallop-relay-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Gallop Relay', 'Gallop to a point, pick up an object, gallop back. Combining a motor skill with a task = motor automatisation.', 8, '5–10 min', 'Small object + open space', 'Gallop to a point, pick up an object, gallop back. Combining a motor skill with a task = motor automatisation.'),
  ('throw-overhand-at-distance-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Throw Overhand at Distance', 'Increase throwing distance to 3 metres. Overhand distance throw = full shoulder rotation and trunk twist working together.', 8, '5–10 min', 'Ball', 'Increase throwing distance to 3 metres. Overhand distance throw = full shoulder rotation and trunk twist working together.'),
  ('hop-on-non-dominant-foot-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Hop on Non-Dominant Foot', 'After mastering dominant foot hopping, work on non-dominant. Often takes 3–6 months more than dominant foot.', 4, '3–5 min', 'None', 'After mastering dominant foot hopping, work on non-dominant. Often takes 3–6 months more than dominant foot.'),
  ('pump-on-a-swing-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Pump on a Swing', 'Teach the leg-pump rhythm for swinging independently. Pendulum mechanics + body coordination + rhythm = rich learning.', 13, '10–15 min', 'Swing', 'Teach the leg-pump rhythm for swinging independently. Pendulum mechanics + body coordination + rhythm = rich learning.'),
  ('jump-rope-assisted-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Jump Rope (Assisted)', 'Hold rope and jump over it laid flat, then swing it slowly. Full jump rope is 5–6 years; foundations built from 3 years.', 8, '5–10 min', 'Rope', 'Hold rope and jump over it laid flat, then swing it slowly. Full jump rope is 5–6 years; foundations built from 3 years.'),
  ('catch-with-one-hand-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Catch with One Hand', 'Catch a large soft ball with one hand. Single-hand catching requires much faster visual-motor processing than two-hand.', 8, '5–10 min', 'Large soft ball', 'Catch a large soft ball with one hand. Single-hand catching requires much faster visual-motor processing than two-hand.'),
  ('steering-obstacle-course-bike-trike-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Steering Obstacle Course (Bike/Trike)', 'Navigate around cones or objects at speed. Complex steering + speed control.', 13, '10–15 min', 'Trike + objects for cones', 'Navigate around cones or objects at speed. Complex steering + speed control.'),
  ('copy-drawing-diamond-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Copy Drawing: Diamond', 'Diamond shape = two triangles. More complex than triangle; appears 4–5 years. Begin exploring it with guided tracing.', 8, '5–10 min', 'Crayon and paper', 'Diamond shape = two triangles. More complex than triangle; appears 4–5 years. Begin exploring it with guided tracing.'),
  ('write-first-name-unaided-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Write First Name (Unaided)', 'First attempt at unaided name writing. Any recognisable letters = progress. Letter formation before order — order comes second.', 8, '5–10 min', 'Pencil and paper', 'First attempt at unaided name writing. Any recognisable letters = progress. Letter formation before order — order comes second.'),
  ('craft-project-multi-step-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Craft Project (Multi-Step)', 'Build a paper crown, collage, or model from 4+ steps with different materials. Planning and sequencing a multi-material project.', 18, '15–20 min', 'Paper, scissors, glue, tape', 'Build a paper crown, collage, or model from 4+ steps with different materials. Planning and sequencing a multi-material project.'),
  ('use-ruler-measure-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Use Ruler (Measure)', 'Measure objects with a ruler: ''This book is 20 centimetres long.'' Combining numeracy with fine motor tool use.', 8, '5–10 min', 'Ruler', 'Measure objects with a ruler: ''This book is 20 centimetres long.'' Combining numeracy with fine motor tool use.'),
  ('fold-paper-multiple-creases-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Fold Paper (Multiple Creases)', 'Fold paper boat or simple origami frog. 4–5 creases requiring precise spatial awareness and planning.', 13, '10–15 min', 'Paper', 'Fold paper boat or simple origami frog. 4–5 creases requiring precise spatial awareness and planning.'),
  ('braid-3-strands-simple-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Braid 3 Strands (Simple)', 'Demonstrate and let child attempt braiding 3 ribbons or cords. The over-under-over pattern is executive function in the hands.', 13, '10–15 min', '3 ribbons or cords', 'Demonstrate and let child attempt braiding 3 ribbons or cords. The over-under-over pattern is executive function in the hands.'),
  ('tell-story-with-5-events-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Tell Story with 5+ Events', 'Spontaneous storytelling with a character, a problem, 3 events, and a resolution. Narrative structure growing.', 8, '5–10 min', 'None', 'Spontaneous storytelling with a character, a problem, 3 events, and a resolution. Narrative structure growing.'),
  ('ask-and-answer-why-chain-of-3-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Ask and Answer ''Why'' (Chain of 3)', 'Sustain a chain of why-question-and-answer 3 turns deep. Each answer must be a full sentence.', 8, '5–10 min', 'None', 'Sustain a chain of why-question-and-answer 3 turns deep. Each answer must be a full sentence.'),
  ('introduction-to-letters-full-alphabet-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Introduction to Letters (Full Alphabet)', 'Introduce the alphabet song. Letter names before letter sounds — the song is a memory sequence, not phonics yet.', 8, '5–10 min', 'None', 'Introduce the alphabet song. Letter names before letter sounds — the song is a memory sequence, not phonics yet.'),
  ('describe-yesterday-in-detail-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Describe Yesterday in Detail', 'Tell me 5 things you did yesterday.'' Episodic memory recall + narrative sequencing in combination.', 8, '5–10 min', 'None', 'Tell me 5 things you did yesterday.'' Episodic memory recall + narrative sequencing in combination.'),
  ('compound-sentences-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Compound Sentences', 'The dog ran AND the cat hid.'' Compound sentences (two clauses joined by ''and'', ''but'', ''so'') are a grammar milestone.', null, 'Ongoing', 'None', 'The dog ran AND the cat hid.'' Compound sentences (two clauses joined by ''and'', ''but'', ''so'') are a grammar milestone.'),
  ('word-families-at-an-in-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Word Families (at, an, in)', '-at words: cat, bat, sat, mat, hat.'' Word families build phonological pattern recognition.', 7, '5–8 min', 'None', '-at words: cat, bat, sat, mat, hat.'' Word families build phonological pattern recognition.'),
  ('conversations-with-adults-sustained-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Conversations with Adults (Sustained)', '5-turn conversation with an unfamiliar adult. Sustaining conversation with non-family adults = social language milestone.', 8, '5–10 min', 'None', '5-turn conversation with an unfamiliar adult. Sustaining conversation with non-family adults = social language milestone.'),
  ('read-environmental-print-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Read Environmental Print', 'Read familiar logos, signs, and labels in the environment: shop name, cereal box, road signs. Environmental print = first reading.', null, 'Ongoing', 'None (outdoors)', 'Read familiar logos, signs, and labels in the environment: shop name, cereal box, road signs. Environmental print = first reading.'),
  ('addition-to-5-concrete-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Addition to 5 (Concrete)', '3 bananas + 2 bananas = 5 bananas.'' Concrete object addition. The concept of adding before the symbol.', 7, '5–8 min', 'Fruit or objects', '3 bananas + 2 bananas = 5 bananas.'' Concrete object addition. The concept of adding before the symbol.'),
  ('subtraction-to-5-concrete-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Subtraction to 5 (Concrete)', '5 blocks. Take away 2. How many left?'' Concrete subtraction. Count what remains, not just recite the answer.', 7, '5–8 min', '5 small objects', '5 blocks. Take away 2. How many left?'' Concrete subtraction. Count what remains, not just recite the answer.'),
  ('measurement-comparison-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Measurement Comparison', 'Which stick is longer? Which cup holds more?'' Direct comparison measurement before formal units.', 7, '5–8 min', 'Two sticks or two cups', 'Which stick is longer? Which cup holds more?'' Direct comparison measurement before formal units.'),
  ('days-of-the-week-in-order-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Days of the Week (in Order)', 'Sing and recite days of the week in order. Mark each day on a simple calendar together.', 7, '5–8 min', 'Simple calendar or drawn week', 'Sing and recite days of the week in order. Mark each day on a simple calendar together.'),
  ('pattern-aabbc-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Pattern: AABBC', 'More complex pattern: red, red, blue, blue, green. 5-element pattern before repeating — demands higher working memory.', 7, '5–8 min', 'Coloured objects', 'More complex pattern: red, red, blue, blue, green. 5-element pattern before repeating — demands higher working memory.'),
  ('map-making-simple-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Map Making (Simple)', 'Draw a simple map of one room together. Spatial representation — map making — is abstract spatial cognition beginning.', 13, '10–15 min', 'Paper and crayon', 'Draw a simple map of one room together. Spatial representation — map making — is abstract spatial cognition beginning.'),
  ('cooperative-building-project-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Cooperative Building Project', 'Build something together that neither could build alone: a fort, a long train, a tall tower. True cooperation with shared goal.', 18, '15–20 min', 'Blankets, cushions, blocks', 'Build something together that neither could build alone: a fort, a long train, a tall tower. True cooperation with shared goal.'),
  ('conflict-resolution-role-play-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Conflict Resolution Role-Play', 'Act out a common conflict and try different resolutions. Role-playing the resolution builds the script for real situations.', 8, '5–10 min', 'None', 'Act out a common conflict and try different resolutions. Role-playing the resolution builds the script for real situations.'),
  ('emotion-intensity-scale-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Emotion Intensity Scale', 'How big are your feelings? A little bit or a LOT?'' Emotion intensity awareness before intensity regulation.', 7, '5–8 min', 'None', 'How big are your feelings? A little bit or a LOT?'' Emotion intensity awareness before intensity regulation.'),
  ('plan-an-activity-together-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Plan an Activity Together', 'What shall we do this afternoon? What do we need? What should we do first?'' Child-led planning with support.', 8, '5–10 min', 'None', 'What shall we do this afternoon? What do we need? What should we do first?'' Child-led planning with support.'),
  ('appreciate-differences-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Appreciate Differences', 'Your friend likes climbing. You like painting. Both are great.'' Differences in preference as valid and interesting — not better/worse.', null, 'Ongoing', 'None', 'Your friend likes climbing. You like painting. Both are great.'' Differences in preference as valid and interesting — not better/worse.'),
  ('celebrate-others-successes-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Celebrate Others'' Successes', 'When a friend achieves something: ''How do you feel about what they did? Can you tell them?'' Pro-social emotion building.', null, 'Ongoing', 'None', 'When a friend achieves something: ''How do you feel about what they did? Can you tell them?'' Pro-social emotion building.'),
  ('clay-sculpture-from-imagination-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Clay Sculpture (From Imagination)', 'Make something from clay without a model or prompt. Imagination into 3D form — high-level creative and fine motor combined.', 18, '15–20 min', 'Clay or atta dough', 'Make something from clay without a model or prompt. Imagination into 3D form — high-level creative and fine motor combined.'),
  ('sound-mapping-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Sound Mapping', 'Draw a map of sounds heard in the house: kitchen sounds, garden sounds. Audio representation in a visual medium.', 13, '10–15 min', 'Paper and crayons', 'Draw a map of sounds heard in the house: kitchen sounds, garden sounds. Audio representation in a visual medium.'),
  ('texture-collage-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Texture Collage', 'Collect 10 different textures (sandpaper, foil, fabric, bark) and stick on card. The making and the touching are both the activity.', 18, '15–20 min', 'Various texture samples, card, glue', 'Collect 10 different textures (sandpaper, foil, fabric, bark) and stick on card. The making and the touching are both the activity.'),
  ('cooking-mix-and-pour-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Cooking: Mix and Pour', 'Involve child in making a simple dish: pancake batter, lemonade. Measuring, pouring, mixing = sensory + numeracy + fine motor.', 25, '20–30 min', 'Cooking ingredients and tools', 'Involve child in making a simple dish: pancake batter, lemonade. Measuring, pouring, mixing = sensory + numeracy + fine motor.'),
  ('mindful-breathing-3-breaths-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Mindful Breathing (3 Breaths)', 'Let''s take 3 big breaths together. In through the nose, out through the mouth.'' Begin building breath as a self-regulation tool.', 3, '2–3 min', 'None', 'Let''s take 3 big breaths together. In through the nose, out through the mouth.'' Begin building breath as a self-regulation tool.'),
  ('dress-completely-independently-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Dress Completely Independently', 'Full dress sequence independently except challenging fastenings. Independence in self-care is as developmental as any skill.', 13, '10–15 min', 'Clothing', 'Full dress sequence independently except challenging fastenings. Independence in self-care is as developmental as any skill.'),
  ('make-own-breakfast-simple-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Make Own Breakfast (Simple)', 'Pour cereal, peel banana, spread butter on toast. Self-feeding preparation builds agency, fine motor, and self-reliance.', 13, '10–15 min', 'Simple breakfast items', 'Pour cereal, peel banana, spread butter on toast. Self-feeding preparation builds agency, fine motor, and self-reliance.'),
  ('skip-and-change-direction-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Skip and Change Direction', 'Skip, then on a signal change direction. Changing a skill mid-execution is a high-level motor planning task.', 8, '5–10 min', 'None', 'Skip, then on a signal change direction. Changing a skill mid-execution is a high-level motor planning task.'),
  ('kick-a-moving-ball-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Kick a Moving Ball', 'Kick a ball rolled toward them — timing a kick to a moving target is significantly harder than kicking a stationary one.', 8, '5–10 min', 'Ball', 'Kick a ball rolled toward them — timing a kick to a moving target is significantly harder than kicking a stationary one.'),
  ('hop-with-distance-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Hop with Distance', 'Hop across a room on one foot — 5+ metres. Distance hopping builds stamina as well as motor control.', 8, '5–10 min', 'None', 'Hop across a room on one foot — 5+ metres. Distance hopping builds stamina as well as motor control.'),
  ('balance-beam-walk-backward-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Balance Beam: Walk Backward', 'Walk backward along a tape line without stepping off. Backward balance beam requires proprioceptive awareness.', 7, '5–8 min', 'Tape line', 'Walk backward along a tape line without stepping off. Backward balance beam requires proprioceptive awareness.'),
  ('sprint-vs-jog-on-signal-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Sprint vs Jog on Signal', 'Run at full speed to a point when they hear ''go'', slow to a jog on ''slow.'' Speed modulation on command.', 8, '5–10 min', 'Open space', 'Run at full speed to a point when they hear ''go'', slow to a jog on ''slow.'' Speed modulation on command.'),
  ('catch-with-both-hands-small-ball-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Catch with Both Hands (Small Ball)', 'Catching a tennis-ball-sized object thrown from 2 m with two hands closing at the right moment.', 8, '5–10 min', 'Tennis ball', 'Catching a tennis-ball-sized object thrown from 2 m with two hands closing at the right moment.'),
  ('jump-rope-self-turning-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Jump Rope (Self-Turning)', 'Begin learning to turn a short rope independently and jump. Step over first, then small jumps, then rhythmic jumping.', 13, '10–15 min', 'Short rope', 'Begin learning to turn a short rope independently and jump. Step over first, then small jumps, then rhythmic jumping.'),
  ('side-slide-steps-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Side Slide Steps', 'Step-slide-step sideways in both directions. Lateral movement uses a different motor pattern from forward locomotion.', 7, '5–8 min', 'None', 'Step-slide-step sideways in both directions. Lateral movement uses a different motor pattern from forward locomotion.'),
  ('copy-initials-2-letters-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Copy Initials (2 Letters)', 'Write first and last name initials without tracing. Letter formation from memory, not visual copying.', 8, '5–10 min', 'Pencil and paper', 'Write first and last name initials without tracing. Letter formation from memory, not visual copying.'),
  ('mosaic-tile-placement-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Mosaic Tile Placement', 'Stick small squares of coloured paper onto a grid to make a pattern. Precision placement in a constrained space.', 18, '15–20 min', 'Small coloured squares, grid paper, glue', 'Stick small squares of coloured paper onto a grid to make a pattern. Precision placement in a constrained space.'),
  ('use-a-stapler-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Use a Stapler', 'Supervised stapler use. Knowing the correct pressure and position = tool awareness and fine motor calibration.', 8, '5–10 min', 'Stapler and paper', 'Supervised stapler use. Knowing the correct pressure and position = tool awareness and fine motor calibration.'),
  ('zig-zag-cutting-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Zig-Zag Cutting', 'Cut along a zig-zag line. Directional change while cutting is harder than cutting a curve.', 8, '5–10 min', 'Child scissors and paper', 'Cut along a zig-zag line. Directional change while cutting is harder than cutting a curve.'),
  ('weave-fabric-strips-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Weave Fabric Strips', 'Weave cloth strips over and under cardboard loom slots. Over-under alternation sustained across a whole piece.', 18, '15–20 min', 'Cloth strips, cardboard with slots', 'Weave cloth strips over and under cardboard loom slots. Over-under alternation sustained across a whole piece.'),
  ('pin-and-thread-simple-embroidery-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Pin-and-Thread Simple Embroidery', 'Thread large-eyed blunt needle and make running stitch on open-weave fabric. Tactile + fine motor + sequencing.', 18, '15–20 min', 'Large-eyed blunt needle, fabric, thread', 'Thread large-eyed blunt needle and make running stitch on open-weave fabric. Tactile + fine motor + sequencing.'),
  ('1500-word-vocabulary-y3_3', 'communication'::domain, 'y3_3'::age_band, '1500+ Word Vocabulary', 'At 3y6m, vocabulary is typically 1200–1500 words. Sentences are 5–6 words with complex grammar emerging.', null, 'Ongoing', 'None', 'At 3y6m, vocabulary is typically 1200–1500 words. Sentences are 5–6 words with complex grammar emerging.'),
  ('write-a-dictated-sentence-y3_3', 'communication'::domain, 'y3_3'::age_band, 'Write a Dictated Sentence', 'Say a sentence; child repeats, then writes it with whatever letters they know. Any attempt that maps to the sentence is progress.', 8, '5–10 min', 'Pencil and paper', 'Say a sentence; child repeats, then writes it with whatever letters they know. Any attempt that maps to the sentence is progress.'),
  ('read-simple-c-v-c-words-y3_3', 'communication'::domain, 'y3_3'::age_band, 'Read Simple C-V-C Words', 'Cat, sat, mat, big, fit. Sound-blending 3-letter words: c-a-t = cat. The first reading bridge.', 8, '5–10 min', 'Paper with simple words', 'Cat, sat, mat, big, fit. Sound-blending 3-letter words: c-a-t = cat. The first reading bridge.'),
  ('use-conjunctions-because-so-but-y3_3', 'communication'::domain, 'y3_3'::age_band, 'Use Conjunctions (Because, So, But)', 'I was cold, SO I put on a jumper.'' Complex clause connectors = significant grammar sophistication.', null, 'Ongoing', 'None', 'I was cold, SO I put on a jumper.'' Complex clause connectors = significant grammar sophistication.'),
  ('explain-a-process-step-by-step-y3_3', 'communication'::domain, 'y3_3'::age_band, 'Explain a Process Step-by-Step', 'How do you make a sandwich? Tell me each step.'' Procedural language: sequenced instruction giving.', 8, '5–10 min', 'None', 'How do you make a sandwich? Tell me each step.'' Procedural language: sequenced instruction giving.'),
  ('conversation-repair-y3_3', 'communication'::domain, 'y3_3'::age_band, 'Conversation Repair', 'When communication breaks down, teach: ''I don''t understand — can you say it a different way?'' Repair is advanced pragmatic skill.', null, 'Ongoing', 'None', 'When communication breaks down, teach: ''I don''t understand — can you say it a different way?'' Repair is advanced pragmatic skill.'),
  ('news-sharing-y3_3', 'communication'::domain, 'y3_3'::age_band, 'News Sharing', 'Daily ''news'' time: ''Tell me one important thing that happened today.'' Selective recall + reporting = executive + language.', 7, '5–8 min', 'None', 'Daily ''news'' time: ''Tell me one important thing that happened today.'' Selective recall + reporting = executive + language.'),
  ('simple-crossword-picture-y3_3', 'communication'::domain, 'y3_3'::age_band, 'Simple Crossword (Picture)', 'A 3-clue picture crossword. Name the picture, count letters, fill boxes. Reading + counting + writing combined.', 8, '5–10 min', 'Simple picture crossword', 'A 3-clue picture crossword. Name the picture, count letters, fill boxes. Reading + counting + writing combined.'),
  ('add-within-10-concrete-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Add Within 10 (Concrete)', 'Here are 4 blocks. I give you 3 more. How many altogether?'' Count all strategy — touching each object to count.', 8, '5–10 min', '10 small objects', 'Here are 4 blocks. I give you 3 more. How many altogether?'' Count all strategy — touching each object to count.'),
  ('subtract-within-10-concrete-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Subtract Within 10 (Concrete)', 'Remove objects from a group and count what remains. Cover the removed objects so child counts only remaining.', 8, '5–10 min', '10 small objects', 'Remove objects from a group and count what remains. Cover the removed objects so child counts only remaining.'),
  ('name-days-of-week-in-order-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Name Days of Week in Order', 'Recite days of week reliably in order. Begin linking days to events: ''On Monday we have swimming.''', 7, '5–8 min', 'None', 'Recite days of week reliably in order. Begin linking days to events: ''On Monday we have swimming.'''),
  ('seasons-concept-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Seasons Concept', 'Name 4 seasons and one characteristic of each. ''Winter is cold. Summer is hot.'' Concept before observation.', 7, '5–8 min', 'None', 'Name 4 seasons and one characteristic of each. ''Winter is cold. Summer is hot.'' Concept before observation.'),
  ('sort-and-graph-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Sort and Graph', 'Sort 20 objects into 3 groups. Count each group. Draw a simple bar graph of the results. Data literacy beginning.', 13, '10–15 min', '20 small objects, paper', 'Sort 20 objects into 3 groups. Count each group. Draw a simple bar graph of the results. Data literacy beginning.'),
  ('classify-living-non-living-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Classify Living / Non-Living', 'Is a dog living? Is a chair living?'' Living/non-living is the first science classification concept.', 7, '5–8 min', 'Household objects and toy animals', 'Is a dog living? Is a chair living?'' Living/non-living is the first science classification concept.'),
  ('express-needs-verbally-before-escalation-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Express Needs Verbally Before Escalation', 'I feel like I need a break before I get too frustrated.'' Body-awareness + self-advocacy + language = emotional executive function.', null, 'Ongoing', 'None', 'I feel like I need a break before I get too frustrated.'' Body-awareness + self-advocacy + language = emotional executive function.'),
  ('introduce-compromise-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Introduce Compromise', 'You want X, I want Y. What if we do X for 10 minutes and then Y?'' Compromise as a concept explicitly taught.', 7, '5–8 min', 'None', 'You want X, I want Y. What if we do X for 10 minutes and then Y?'' Compromise as a concept explicitly taught.'),
  ('identity-i-am-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Identity: I Am...', 'Tell me 5 things about you.'' Not what you do — who you are. Self-concept building is the 3-year social-emotional task.', 8, '5–10 min', 'None', 'Tell me 5 things about you.'' Not what you do — who you are. Self-concept building is the 3-year social-emotional task.'),
  ('friendship-maintenance-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Friendship Maintenance', 'Your friend seems quiet today. What could you do?'' Friendship requires maintenance actions — teach them explicitly.', null, 'Ongoing', 'None', 'Your friend seems quiet today. What could you do?'' Friendship requires maintenance actions — teach them explicitly.'),
  ('handle-disappointment-script-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Handle Disappointment Script', 'You''re disappointed. Let''s say what you''re feeling and think of one thing that might help.'' Disappointment skill.', 4, '3–5 min', 'None', 'You''re disappointed. Let''s say what you''re feeling and think of one thing that might help.'' Disappointment skill.'),
  ('gratitude-practice-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Gratitude Practice', 'Name 3 things you''re grateful for at dinner. Gratitude practice correlates with wellbeing and prosocial behaviour.', 4, '3–5 min', 'None', 'Name 3 things you''re grateful for at dinner. Gratitude practice correlates with wellbeing and prosocial behaviour.'),
  ('cooking-sensory-experience-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Cooking Sensory Experience', 'Make chapati or simple bread together. Feel dough, smell cooking, hear sizzle, taste result. All 5 senses in one activity.', 25, '20–30 min', 'Flour, water, pan', 'Make chapati or simple bread together. Feel dough, smell cooking, hear sizzle, taste result. All 5 senses in one activity.'),
  ('ice-melt-science-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Ice Melt Science', 'Fill ice trays with water + small objects. Freeze. Let child unmelt at room temperature or with warm water. Science + sensory.', 18, '15–20 min', 'Ice tray, water, small objects', 'Fill ice trays with water + small objects. Freeze. Let child unmelt at room temperature or with warm water. Science + sensory.'),
  ('weaving-with-natural-materials-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Weaving with Natural Materials', 'Weave grass, leaves, and twigs through a simple frame. Outdoor sensory + fine motor + creativity.', 18, '15–20 min', 'Sticks for frame, natural materials', 'Weave grass, leaves, and twigs through a simple frame. Outdoor sensory + fine motor + creativity.'),
  ('mindful-listening-2-minutes-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Mindful Listening (2 Minutes)', 'Sit quietly for 2 minutes. When timer rings, share 3 things you heard. Auditory attention + metacognition.', 3, '2–3 min', 'Timer', 'Sit quietly for 2 minutes. When timer rings, share 3 things you heard. Auditory attention + metacognition.'),
  ('light-table-or-torch-play-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Light Table or Torch Play', 'In a darkened room, explore light through coloured acetate or water. Light science + visual sensory exploration.', 13, '10–15 min', 'Torch, coloured acetate or water in bag', 'In a darkened room, explore light through coloured acetate or water. Light science + visual sensory exploration.'),
  ('independent-morning-routine-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Independent Morning Routine', 'Wake, toilet, wash, dress, breakfast — child completes the entire sequence with minimal reminders. Executive function in action.', 25, '20–30 min', 'None', 'Wake, toilet, wash, dress, breakfast — child completes the entire sequence with minimal reminders. Executive function in action.'),
  ('responsible-for-one-chore-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Responsible for One Chore', 'One daily chore owned completely: watering a plant, setting the table, feeding a pet. Responsibility + competence.', 8, '5–10 min', 'Chore-specific materials', 'One daily chore owned completely: watering a plant, setting the table, feeding a pet. Responsibility + competence.'),
  ('jump-over-moving-object-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Jump Over Moving Object', 'Jump over a rolling ball. Timing a jump to a moving target is a higher motor planning demand than a stationary jump.', 8, '5–10 min', 'Large ball', 'Jump over a rolling ball. Timing a jump to a moving target is a higher motor planning demand than a stationary jump.'),
  ('dribble-and-run-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Dribble and Run', 'Bounce a ball continuously while walking, then while running. Dual-task automatisation: locomotion + ball control.', 13, '10–15 min', 'Medium ball', 'Bounce a ball continuously while walking, then while running. Dual-task automatisation: locomotion + ball control.'),
  ('one-leg-balance-8-seconds-y3_6', 'motor'::domain, 'y3_6'::age_band, 'One-Leg Balance (8 Seconds)', '8-second one-foot balance, eyes open. Begin introducing eyes-closed versions briefly.', 4, '3–5 min', 'None', '8-second one-foot balance, eyes open. Begin introducing eyes-closed versions briefly.'),
  ('summersault-independently-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Summersault Independently', 'Forward roll without assistance. Head tuck, push-off, round-back landing. Proprioception and vestibular combined.', 4, '3–5 min', 'Soft mat or rug', 'Forward roll without assistance. Head tuck, push-off, round-back landing. Proprioception and vestibular combined.'),
  ('tandem-walk-heel-to-toe-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Tandem Walk (Heel-to-Toe)', 'Walk heel-to-toe in a straight line, arms out. Tandem walking tests balance in a constrained path.', 7, '5–8 min', 'Tape line', 'Walk heel-to-toe in a straight line, arms out. Tandem walking tests balance in a constrained path.'),
  ('gallop-with-music-rhythm-match-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Gallop with Music (Rhythm Match)', 'Gallop to music, matching the tempo. Rhythmic locomotion: motor planning linked to auditory input.', 8, '5–10 min', 'Music source', 'Gallop to music, matching the tempo. Rhythmic locomotion: motor planning linked to auditory input.'),
  ('target-throwing-underhand-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Target Throwing (Underhand)', 'Underhand toss into a basket from 1.5 m. Underhand vs overhand uses different arm mechanics -- both need practice.', 7, '5–8 min', 'Ball and container', 'Underhand toss into a basket from 1.5 m. Underhand vs overhand uses different arm mechanics -- both need practice.'),
  ('jumping-jacks-star-jumps-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Jumping Jacks (Star Jumps)', 'Demonstrate jumping jacks and let child try. Coordinating arm and leg movement simultaneously -- hard at this age.', 4, '3–5 min', 'None', 'Demonstrate jumping jacks and let child try. Coordinating arm and leg movement simultaneously -- hard at this age.'),
  ('letter-formation-practice-a-e-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Letter Formation Practice (A-E)', 'Correct formation of letters A, B, C, D, E. Top-to-bottom and left-to-right directional habits built now last a lifetime.', 8, '5–10 min', 'Pencil and paper', 'Correct formation of letters A, B, C, D, E. Top-to-bottom and left-to-right directional habits built now last a lifetime.'),
  ('watercolour-painting-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Watercolour Painting', 'Paint with watercolours, rinsing brush between colours. Controlling dilution and brush pressure = fine motor calibration.', 13, '10–15 min', 'Watercolours, brush, water, paper', 'Paint with watercolours, rinsing brush between colours. Controlling dilution and brush pressure = fine motor calibration.'),
  ('weaving-loom-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Weaving (Loom)', 'Simple over-under weaving on a cardboard loom. Alternating the direction of each row = pattern thinking in the hands.', 18, '15–20 min', 'Cardboard loom, yarn', 'Simple over-under weaving on a cardboard loom. Alternating the direction of each row = pattern thinking in the hands.'),
  ('use-a-hole-punch-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Use a Hole Punch', 'Punch holes along the edge of paper to make a lacing card. Using a hole punch requires significant grip force.', 8, '5–10 min', 'Hole punch and paper', 'Punch holes along the edge of paper to make a lacing card. Using a hole punch requires significant grip force.'),
  ('cut-spiral-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Cut Spiral', 'Draw a spiral and cut along the line. The continuously changing direction is the most demanding cutting challenge yet.', 8, '5–10 min', 'Child scissors and paper', 'Draw a spiral and cut along the line. The continuously changing direction is the most demanding cutting challenge yet.'),
  ('roll-a-thin-clay-snake-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Roll a Thin Clay Snake', 'Roll clay into a long thin snake without breaking it. Fine pressure calibration -- too hard = flatten, too soft = break.', 8, '5–10 min', 'Clay or atta dough', 'Roll clay into a long thin snake without breaking it. Fine pressure calibration -- too hard = flatten, too soft = break.'),
  ('read-simple-sentences-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Read Simple Sentences', 'Read 3-word sentences: ''The cat sat.'' Sound each letter, blend. First independent reading = a landmark moment.', 8, '5–10 min', 'Simple reader or card with sentences', 'Read 3-word sentences: ''The cat sat.'' Sound each letter, blend. First independent reading = a landmark moment.'),
  ('write-simple-words-cvc-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Write Simple Words (CVC)', 'Write simple consonant-vowel-consonant words: cat, sit, big. Encoding = higher skill than decoding. Celebrate any attempt.', 8, '5–10 min', 'Pencil and paper', 'Write simple consonant-vowel-consonant words: cat, sit, big. Encoding = higher skill than decoding. Celebrate any attempt.'),
  ('use-adjectives-and-adverbs-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Use Adjectives and Adverbs', 'The small brown dog ran quickly.'' Describe objects and actions with modifiers -- vocabulary sophistication growing.', null, 'Ongoing', 'None', 'The small brown dog ran quickly.'' Describe objects and actions with modifiers -- vocabulary sophistication growing.'),
  ('tell-a-joke-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Tell a Joke', 'Learn one simple joke and tell it to someone. Jokes require understanding that words can have two meanings -- abstract language.', 8, '5–10 min', 'None', 'Learn one simple joke and tell it to someone. Jokes require understanding that words can have two meanings -- abstract language.'),
  ('listen-and-summarise-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Listen and Summarise', 'Read a short paragraph, then ask: ''What was it about? Say it in two sentences.'' Summarising requires comprehension + language.', 8, '5–10 min', 'Short paragraph from any book', 'Read a short paragraph, then ask: ''What was it about? Say it in two sentences.'' Summarising requires comprehension + language.'),
  ('name-10-sight-words-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Name 10 Sight Words', 'Common sight words: the, and, is, it, in, on, a, I, to, he. Sight word reading is memory + print awareness.', 8, '5–10 min', 'Cards with sight words', 'Common sight words: the, and, is, it, in, on, a, I, to, he. Sight word reading is memory + print awareness.'),
  ('give-directions-to-someone-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Give Directions to Someone', 'Tell me how to get to the kitchen from here.'' Spatial language + perspective-taking + sequential instruction.', 8, '5–10 min', 'None', 'Tell me how to get to the kitchen from here.'' Spatial language + perspective-taking + sequential instruction.'),
  ('debate-two-sides-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Debate Two Sides', 'Some people think dogs are better than cats. Some think cats are better. What''s your view? Why?'' Beginning of argument.', 8, '5–10 min', 'None', 'Some people think dogs are better than cats. Some think cats are better. What''s your view? Why?'' Beginning of argument.'),
  ('addition-and-subtraction-to-10-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Addition and Subtraction to 10', 'Concrete then pictorial then symbolic. ''4+3=?'' on paper, with objects to count if needed.', 8, '5–10 min', 'Objects + pencil and paper', 'Concrete then pictorial then symbolic. ''4+3=?'' on paper, with objects to count if needed.'),
  ('even-and-odd-numbers-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Even and Odd Numbers', '2, 4, 6 are even -- can be split into two equal groups. 1, 3, 5 cannot. Concrete splitting before the rule.', 7, '5–8 min', 'Small objects', '2, 4, 6 are even -- can be split into two equal groups. 1, 3, 5 cannot. Concrete splitting before the rule.'),
  ('months-of-year-sequence-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Months of Year (Sequence)', 'Recite months in order. Link each to a family event: ''My birthday is in July.'' Sequence then meaning.', 7, '5–8 min', 'None', 'Recite months in order. Link each to a family event: ''My birthday is in July.'' Sequence then meaning.'),
  ('concept-of-money-coins-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Concept of Money (Coins)', 'Identify coins by appearance and name their values. Sorting coins by value -- not yet purchasing, just denominations.', 8, '5–10 min', 'Real coins', 'Identify coins by appearance and name their values. Sorting coins by value -- not yet purchasing, just denominations.'),
  ('living-things-need-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Living Things Need...', 'What do plants need? What do animals need?'' Beginning biology -- organisms have requirements for survival.', 8, '5–10 min', 'Plant to observe', 'What do plants need? What do animals need?'' Beginning biology -- organisms have requirements for survival.'),
  ('simple-map-reading-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Simple Map Reading', 'A map of the house or garden. Find a ''treasure'' hidden using map coordinates. Spatial representation reading.', 13, '10–15 min', 'Drawn map + hidden object', 'A map of the house or garden. Find a ''treasure'' hidden using map coordinates. Spatial representation reading.'),
  ('manage-waiting-5-minutes-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Manage Waiting (5 Minutes)', 'Wait 5 minutes for something desirable with a visible timer. Narrate the wait: ''We''re waiting. That is hard. We can do it.''', 8, '5–10 min', 'Timer', 'Wait 5 minutes for something desirable with a visible timer. Narrate the wait: ''We''re waiting. That is hard. We can do it.'''),
  ('ask-for-what-you-need-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Ask for What You Need', 'Practice saying ''I need...'' or ''Can I have...'' instead of grabbing, whining, or melting down. Verbal request habit.', null, 'Ongoing', 'None', 'Practice saying ''I need...'' or ''Can I have...'' instead of grabbing, whining, or melting down. Verbal request habit.'),
  ('acknowledge-others-feelings-first-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Acknowledge Others'' Feelings First', 'Before I say what I want, let me notice how you are feeling.'' Other-first awareness is sophisticated SE development.', null, 'Ongoing', 'None', 'Before I say what I want, let me notice how you are feeling.'' Other-first awareness is sophisticated SE development.'),
  ('resilience-story-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Resilience Story', 'Read a book about a character who faces difficulty and succeeds. Discuss: ''What did they do when it was hard?''', 8, '5–10 min', 'Book with resilience theme', 'Read a book about a character who faces difficulty and succeeds. Discuss: ''What did they do when it was hard?'''),
  ('disagree-respectfully-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Disagree Respectfully', 'I think it''s different because...'' Teaching disagreement that doesn''t damage the relationship.', null, 'Ongoing', 'None', 'I think it''s different because...'' Teaching disagreement that doesn''t damage the relationship.'),
  ('gratitude-letter-dictated-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Gratitude Letter (Dictated)', 'Dictate a thank-you to someone who helped them. Gratitude expressed externally = prosocial behaviour building.', 8, '5–10 min', 'Paper and pencil', 'Dictate a thank-you to someone who helped them. Gratitude expressed externally = prosocial behaviour building.'),
  ('cooking-science-baking-soda-vinegar-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Cooking Science (Baking Soda + Vinegar)', 'Mix baking soda and vinegar in a bowl. Watch, discuss why it fizzes. Hypothesis before result -- early science thinking.', 13, '10–15 min', 'Baking soda, vinegar, container', 'Mix baking soda and vinegar in a bowl. Watch, discuss why it fizzes. Hypothesis before result -- early science thinking.'),
  ('blindfold-smell-test-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Blindfold Smell Test', 'Blindfolded: smell 6 household items and name them. Olfactory discrimination is rarely directly exercised.', 8, '5–10 min', '6 strongly scented household items', 'Blindfolded: smell 6 household items and name them. Olfactory discrimination is rarely directly exercised.'),
  ('shadow-puppets-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Shadow Puppets', 'Make hand-shadow animals on a wall with a torch. Visual creation + fine motor + narrative.', 13, '10–15 min', 'Torch', 'Make hand-shadow animals on a wall with a torch. Visual creation + fine motor + narrative.'),
  ('rhythm-pattern-4-beat-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Rhythm Pattern (4 Beat)', 'Clap a 4-beat pattern and ask child to copy. Then let them create one for you to copy. Rhythmic working memory.', 7, '5–8 min', 'None', 'Clap a 4-beat pattern and ask child to copy. Then let them create one for you to copy. Rhythmic working memory.'),
  ('plant-observation-journal-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Plant Observation Journal', 'Plant a seed and draw it each week. Observation + recording + science concept of growth over time.', 8, '5–10 min', 'Seed, pot, soil, drawing journal', 'Plant a seed and draw it each week. Observation + recording + science concept of growth over time.'),
  ('pack-own-school-bag-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Pack Own School Bag', 'Child packs their own bag with a checklist: water bottle, lunch, library book, uniform. Executive function daily practice.', 8, '5–10 min', 'School bag + checklist', 'Child packs their own bag with a checklist: water bottle, lunch, library book, uniform. Executive function daily practice.'),
  ('manage-belongings-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Manage Belongings', 'Your responsibility: water bottle goes in your bag, shoes go in the rack, toys go in the box.'' Ownership of own items.', null, 'Ongoing', 'None', 'Your responsibility: water bottle goes in your bag, shoes go in the rack, toys go in the box.'' Ownership of own items.'),
  ('skip-relay-race-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Skip Relay Race', 'Skip to a point, pick up an object, skip back -- in competition with self (timer) or family. Speed + skill combined.', 13, '10–15 min', 'Small objects', 'Skip to a point, pick up an object, skip back -- in competition with self (timer) or family. Speed + skill combined.'),
  ('stand-on-tiptoes-10-seconds-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Stand on Tiptoes (10 Seconds)', 'Balance on tiptoes for 10 seconds. Calf strength + balance + body awareness.', 4, '3–5 min', 'None', 'Balance on tiptoes for 10 seconds. Calf strength + balance + body awareness.'),
  ('throw-overhand-aim-at-target-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Throw Overhand (Aim at Target)', 'Overhand throw at a target 3 m away. Accuracy + distance combined = complex motor planning.', 8, '5–10 min', 'Ball + target', 'Overhand throw at a target 3 m away. Accuracy + distance combined = complex motor planning.'),
  ('balance-on-wobble-board-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Balance on Wobble Board', 'Any improvised wobble surface (cushion on board). Dynamic balance is harder than static balance.', 8, '5–10 min', 'Cushion or improvised wobble surface', 'Any improvised wobble surface (cushion on board). Dynamic balance is harder than static balance.'),
  ('walk-on-hands-wheelbarrow-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Walk on Hands (Wheelbarrow)', 'Parent holds legs; child walks on hands. Shoulder girdle strength and weight-bearing through arms.', 4, '3–5 min', 'None', 'Parent holds legs; child walks on hands. Shoulder girdle strength and weight-bearing through arms.'),
  ('stair-running-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Stair Running', 'Run up and down stairs (safely). Requires much faster motor planning and leg activation than walking on stairs.', 7, '5–8 min', 'Stairs', 'Run up and down stairs (safely). Requires much faster motor planning and leg activation than walking on stairs.'),
  ('dribble-around-obstacles-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Dribble Around Obstacles', 'Dribble a ball around objects placed at 50-cm intervals. Controlled directional dribbling.', 8, '5–10 min', 'Ball + obstacles', 'Dribble a ball around objects placed at 50-cm intervals. Controlled directional dribbling.'),
  ('controlled-landing-from-jump-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Controlled Landing from Jump', 'Jump from 40 cm and land softly -- bent knees, arms out. Controlled landing is as important as the jump itself.', 4, '3–5 min', 'Low step or table', 'Jump from 40 cm and land softly -- bent knees, arms out. Controlled landing is as important as the jump itself.'),
  ('letter-formation-f-j-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Letter Formation (F-J)', 'Correct formation of letters F, G, H, I, J. Focus on correct starting point and direction.', 8, '5–10 min', 'Pencil and paper', 'Correct formation of letters F, G, H, I, J. Focus on correct starting point and direction.'),
  ('sewing-running-stitch-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Sewing Running Stitch', 'Running stitch on open-weave fabric with a large blunt needle. Threading + in-out pattern + sustained fine motor.', 18, '15–20 min', 'Blunt needle, thread, open fabric', 'Running stitch on open-weave fabric with a large blunt needle. Threading + in-out pattern + sustained fine motor.'),
  ('origami-simple-animal-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Origami (Simple Animal)', 'Simple origami: bird or boat using 3-4 folds. Spatial + fine motor + following sequence.', 13, '10–15 min', 'Square paper', 'Simple origami: bird or boat using 3-4 folds. Spatial + fine motor + following sequence.'),
  ('tying-knot-simple-overhand-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Tying Knot (Simple Overhand)', 'Tie an overhand knot in a rope. Pre-cursor to shoe-tying. Loop and through.', 8, '5–10 min', 'Rope or shoelace', 'Tie an overhand knot in a rope. Pre-cursor to shoe-tying. Loop and through.'),
  ('draw-scene-from-imagination-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Draw Scene from Imagination', 'Draw something that has never existed.'' Imagination into representation -- no reference, only internal image.', 13, '10–15 min', 'Drawing materials', 'Draw something that has never existed.'' Imagination into representation -- no reference, only internal image.'),
  ('build-3d-model-from-plan-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Build 3D Model from Plan', 'Look at a photo or drawing of a structure and recreate it with blocks. 2D-to-3D translation.', 13, '10–15 min', 'Blocks + reference picture', 'Look at a photo or drawing of a structure and recreate it with blocks. 2D-to-3D translation.'),
  ('read-a-short-book-independently-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Read a Short Book (Independently)', 'Level-appropriate early reader: 8-12 pages, 1-2 sentences per page. Independent reading attempt.', 13, '10–15 min', 'Level-appropriate early reader', 'Level-appropriate early reader: 8-12 pages, 1-2 sentences per page. Independent reading attempt.'),
  ('write-a-short-sentence-unaided-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Write a Short Sentence (Unaided)', '3-5 words, own spelling attempt. ''The cat is big.'' Phonetic spelling -- celebrate all attempts regardless of accuracy.', 8, '5–10 min', 'Pencil and paper', '3-5 words, own spelling attempt. ''The cat is big.'' Phonetic spelling -- celebrate all attempts regardless of accuracy.'),
  ('explain-your-thinking-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Explain Your Thinking', 'How did you know it was a dog? What told you?'' Metacognitive language: explaining reasoning, not just answering.', 8, '5–10 min', 'None', 'How did you know it was a dog? What told you?'' Metacognitive language: explaining reasoning, not just answering.'),
  ('presentation-to-family-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Presentation to Family', 'Show-and-tell: choose an object and speak about it for 1 minute to family. Public speaking practice in a safe context.', 8, '5–10 min', 'Chosen object', 'Show-and-tell: choose an object and speak about it for 1 minute to family. Public speaking practice in a safe context.'),
  ('interview-a-family-member-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Interview a Family Member', 'Child interviews a parent or grandparent: ''What was your favourite food as a child?'' Language + social + inquiry.', 8, '5–10 min', 'None', 'Child interviews a parent or grandparent: ''What was your favourite food as a child?'' Language + social + inquiry.'),
  ('understand-idioms-simple-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Understand Idioms (Simple)', 'It''s raining cats and dogs -- does that mean real cats and dogs?'' Figurative language awareness beginning.', 7, '5–8 min', 'None', 'It''s raining cats and dogs -- does that mean real cats and dogs?'' Figurative language awareness beginning.'),
  ('create-own-book-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Create Own Book', 'Fold 4 sheets of paper, staple, write a title, draw 4 pictures, dictate the story text. Author identity building.', 18, '15–20 min', 'Paper, stapler, drawing materials', 'Fold 4 sheets of paper, staple, write a title, draw 4 pictures, dictate the story text. Author identity building.'),
  ('debate-evidence-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Debate + Evidence', 'Why do you think that? What makes you sure?'' Adding evidence to an opinion. Critical thinking through language.', 8, '5–10 min', 'None', 'Why do you think that? What makes you sure?'' Adding evidence to an opinion. Critical thinking through language.'),
  ('addition-and-subtraction-to-20-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Addition and Subtraction to 20', 'Extend arithmetic to 20 with concrete supports first. Count-on strategy: start from the larger number.', 8, '5–10 min', '20 objects + number line drawn on paper', 'Extend arithmetic to 20 with concrete supports first. Count-on strategy: start from the larger number.'),
  ('halves-and-quarters-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Halves and Quarters', 'Cut an apple or paper into 2 equal halves, then 4 equal quarters. Fraction concept through direct physical splitting.', 8, '5–10 min', 'Apple or paper', 'Cut an apple or paper into 2 equal halves, then 4 equal quarters. Fraction concept through direct physical splitting.'),
  ('weight-comparison-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Weight Comparison', 'Balance two objects on a plank over a pivot. Which is heavier? Direct comparison before scales.', 8, '5–10 min', 'Plank, pivot (rolled towel), objects', 'Balance two objects on a plank over a pivot. Which is heavier? Direct comparison before scales.'),
  ('concept-of-time-duration-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Concept of Time Duration', 'How long is 1 minute? 5 minutes? Time a minute of activity, then wait a minute. Duration concept before clock reading.', 7, '5–8 min', 'Timer', 'How long is 1 minute? 5 minutes? Time a minute of activity, then wait a minute. Duration concept before clock reading.'),
  ('animal-classification-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Animal Classification', 'Sort animals into mammals, birds, fish, insects. Classification by shared characteristics = taxonomy thinking.', 8, '5–10 min', 'Toy animals or pictures', 'Sort animals into mammals, birds, fish, insects. Classification by shared characteristics = taxonomy thinking.'),
  ('create-a-survey-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Create a Survey', 'Do you prefer apples or oranges?'' Survey 5 family members, record results, draw graph. Data collection at its simplest.', 13, '10–15 min', 'Paper for tally chart', 'Do you prefer apples or oranges?'' Survey 5 family members, record results, draw graph. Data collection at its simplest.'),
  ('handle-unfairness-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Handle Unfairness', 'When something seems unfair: ''Tell me what you think happened and what you think would be fair.'' Reasoning about justice.', 8, '5–10 min', 'None', 'When something seems unfair: ''Tell me what you think happened and what you think would be fair.'' Reasoning about justice.'),
  ('include-an-outsider-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Include an Outsider', 'When playing with others: ''Is there anyone who isn''t playing? Can we include them?'' Proactive inclusivity.', null, 'Ongoing', 'None', 'When playing with others: ''Is there anyone who isn''t playing? Can we include them?'' Proactive inclusivity.'),
  ('persistence-practice-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Persistence Practice', 'Attempt something just beyond current ability for 5 minutes without giving up. ''I can''t do it yet -- not yet.''', 8, '5–10 min', 'Challenging task', 'Attempt something just beyond current ability for 5 minutes without giving up. ''I can''t do it yet -- not yet.'''),
  ('manage-boredom-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Manage Boredom', 'I''m bored.'' Response: ''Let''s see what you can create with these 5 things.'' Resourcefulness from boredom = creativity.', 8, '5–10 min', '5 household objects', 'I''m bored.'' Response: ''Let''s see what you can create with these 5 things.'' Resourcefulness from boredom = creativity.'),
  ('recognise-your-own-triggers-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Recognise Your Own Triggers', 'What kinds of things make you feel very upset? Let''s make a list.'' Trigger awareness before trigger management.', 8, '5–10 min', 'None', 'What kinds of things make you feel very upset? Let''s make a list.'' Trigger awareness before trigger management.'),
  ('celebrate-failure-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Celebrate Failure', 'Share a time you failed and what you learned. Normalise failure explicitly: ''Failing is how we find out what to do differently.''', 8, '5–10 min', 'None', 'Share a time you failed and what you learned. Normalise failure explicitly: ''Failing is how we find out what to do differently.'''),
  ('garden-science-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Garden Science', 'Plant seeds, water them, observe growth daily. Science hypothesis: ''What does a plant need to grow?''', null, 'Ongoing', 'Seeds, pot, soil, water', 'Plant seeds, water them, observe growth daily. Science hypothesis: ''What does a plant need to grow?'''),
  ('colour-mixing-paints-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Colour Mixing (Paints)', 'Primary colour mixing: what does red + blue make? Let child predict before mixing. Science + sensory + language.', 13, '10–15 min', 'Red, blue, yellow paint; paper', 'Primary colour mixing: what does red + blue make? Let child predict before mixing. Science + sensory + language.'),
  ('build-a-marble-run-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Build a Marble Run', 'Build a run from rolled paper or tubes. Engineering: ramp angle, connections, energy transfer.', 18, '15–20 min', 'Paper tubes, tape', 'Build a run from rolled paper or tubes. Engineering: ramp angle, connections, energy transfer.'),
  ('listen-to-classical-music-still-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Listen to Classical Music (Still)', 'Sit for 5 minutes and listen to a piece of music without words. What pictures does it make in your mind?', 8, '5–10 min', 'Classical music recording', 'Sit for 5 minutes and listen to a piece of music without words. What pictures does it make in your mind?'),
  ('clay-pottery-coil-method-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Clay Pottery (Coil Method)', 'Roll long clay coils and stack them to build a pot. Coil pottery is one of the oldest craft techniques.', 18, '15–20 min', 'Clay or atta dough', 'Roll long clay coils and stack them to build a pot. Coil pottery is one of the oldest craft techniques.'),
  ('responsible-pet-care-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Responsible Pet Care', 'If family has a pet: feed, water, clean up after under supervision. Daily animal responsibility.', 8, '5–10 min', 'Pet-care materials', 'If family has a pet: feed, water, clean up after under supervision. Daily animal responsibility.'),
  ('money-for-small-purchase-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Money for Small Purchase', 'Give coins for a small purchase at a shop. Count out the right amount. Real-world transaction practice.', 8, '5–10 min', 'Coins', 'Give coins for a small purchase at a shop. Count out the right amount. Real-world transaction practice.'),
  ('skip-20-metres-without-stopping-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Skip 20 Metres Without Stopping', 'Sustained skipping over a distance requires stamina as well as skill -- the motor pattern becomes automatic.', 7, '5–8 min', 'Open space', 'Sustained skipping over a distance requires stamina as well as skill -- the motor pattern becomes automatic.'),
  ('ride-a-bicycle-training-wheels-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Ride a Bicycle (Training Wheels)', 'Balance + steering + pedalling + braking all together. Even with training wheels, this is the most complex motor task to date.', 18, '15–20 min', 'Bicycle with training wheels', 'Balance + steering + pedalling + braking all together. Even with training wheels, this is the most complex motor task to date.'),
  ('hop-on-non-dominant-foot-5-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Hop on Non-Dominant Foot (5+)', '5+ hops on the non-dominant foot. This typically lags dominant by 3-6 months -- both sides need direct practice.', 4, '3–5 min', 'None', '5+ hops on the non-dominant foot. This typically lags dominant by 3-6 months -- both sides need direct practice.'),
  ('throw-distance-5-metres-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Throw Distance (5 Metres)', 'Overhand throw to 5-metre distance. Full body rotation, arm extension, and follow-through must all coordinate.', 8, '5–10 min', 'Ball', 'Overhand throw to 5-metre distance. Full body rotation, arm extension, and follow-through must all coordinate.'),
  ('jump-down-from-50-cm-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Jump Down from 50 cm', 'Jump from a 50-cm height and land safely with soft knees. Height judgement and controlled landing.', 4, '3–5 min', 'Step or table (50 cm)', 'Jump from a 50-cm height and land safely with soft knees. Height judgement and controlled landing.'),
  ('move-to-music-complex-rhythm-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Move to Music (Complex Rhythm)', 'Move to music with syncopated rhythm. Following complex rhythm requires auditory discrimination and motor response.', 8, '5–10 min', 'Music with varied rhythm', 'Move to music with syncopated rhythm. Following complex rhythm requires auditory discrimination and motor response.'),
  ('aim-and-kick-moving-ball-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Aim and Kick (Moving Ball)', 'Kick a rolling ball -- timing the contact point on a moving target.', 8, '5–10 min', 'Ball', 'Kick a rolling ball -- timing the contact point on a moving target.'),
  ('side-shuffle-race-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Side Shuffle Race', 'Side-shuffle (step-together-step) to a point and back. Lateral movement at speed.', 7, '5–8 min', 'None', 'Side-shuffle (step-together-step) to a point and back. Lateral movement at speed.'),
  ('letter-formation-k-p-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Letter Formation (K-P)', 'Correct formation of letters K, L, M, N, O, P. Build toward writing the full alphabet.', 8, '5–10 min', 'Pencil and paper', 'Correct formation of letters K, L, M, N, O, P. Build toward writing the full alphabet.'),
  ('draw-portrait-of-a-person-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Draw Portrait of a Person', 'Draw a person with face details: eyes, nose, mouth, hair, eyebrows. Observed portrait vs schematic figure.', 13, '10–15 min', 'Drawing materials', 'Draw a person with face details: eyes, nose, mouth, hair, eyebrows. Observed portrait vs schematic figure.'),
  ('knit-or-crochet-simple-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Knit or Crochet (Simple)', 'Knitting: cast on 8 stitches, do 4 rows. Even basic knitting requires bilateral coordination and pattern following.', 18, '15–20 min', 'Thick yarn and large needles', 'Knitting: cast on 8 stitches, do 4 rows. Even basic knitting requires bilateral coordination and pattern following.'),
  ('cut-complex-shape-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Cut Complex Shape', 'Cut out a picture of a house or animal from a drawn outline. Complex shape-following.', 13, '10–15 min', 'Child scissors and paper with complex outline', 'Cut out a picture of a house or animal from a drawn outline. Complex shape-following.'),
  ('build-freestanding-tall-tower-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Build Freestanding Tall Tower', 'Build the tallest possible tower from household recycling. Stability physics: base width vs height ratio.', 13, '10–15 min', 'Cardboard boxes, toilet rolls, tape', 'Build the tallest possible tower from household recycling. Stability physics: base width vs height ratio.'),
  ('construct-paper-aeroplane-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Construct Paper Aeroplane', 'Basic paper plane requires 5-6 precise folds. Launch it: does direction of fold affect flight?', 13, '10–15 min', 'Paper', 'Basic paper plane requires 5-6 precise folds. Launch it: does direction of fold affect flight?'),
  ('read-a-level-1-early-reader-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Read a Level-1 Early Reader', '8-12 pages, repeating sentence pattern. Read independently; parent supports only when stuck.', 13, '10–15 min', 'Level 1 early reader book', '8-12 pages, repeating sentence pattern. Read independently; parent supports only when stuck.'),
  ('write-own-story-3-sentences-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Write Own Story (3 Sentences)', '3 sentences: character, problem, resolution. Own invented narrative committed to paper.', 13, '10–15 min', 'Pencil and paper', '3 sentences: character, problem, resolution. Own invented narrative committed to paper.'),
  ('learn-20-sight-words-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Learn 20 Sight Words', 'First 20 high-frequency words. These are the building blocks of early reading fluency.', 8, '5–10 min', 'Sight word cards', 'First 20 high-frequency words. These are the building blocks of early reading fluency.'),
  ('simile-introduction-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Simile Introduction', 'The cloud is like cotton wool.'' Make 5 similes about things in the room. Figurative language production.', 8, '5–10 min', 'None', 'The cloud is like cotton wool.'' Make 5 similes about things in the room. Figurative language production.'),
  ('retell-story-with-different-ending-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Retell Story with Different Ending', 'After reading a story, ask: ''What would happen if the ending was different?'' Narrative manipulation.', 8, '5–10 min', 'Familiar story', 'After reading a story, ask: ''What would happen if the ending was different?'' Narrative manipulation.'),
  ('listen-and-draw-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Listen and Draw', 'Describe a scene verbally; child draws it without seeing the description. Listening comprehension + visual production.', 8, '5–10 min', 'Drawing materials', 'Describe a scene verbally; child draws it without seeing the description. Listening comprehension + visual production.'),
  ('read-a-simple-poem-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Read a Simple Poem', 'Read a short poem together. Identify rhymes, count syllables in words. Poetry as a linguistic object.', 8, '5–10 min', 'Simple poem', 'Read a short poem together. Identify rhymes, count syllables in words. Poetry as a linguistic object.'),
  ('write-a-letter-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Write a Letter', 'Dictate or write a letter to a real person (grandparent, friend). Letter-writing structure: greeting, body, sign-off.', 13, '10–15 min', 'Pencil and paper', 'Dictate or write a letter to a real person (grandparent, friend). Letter-writing structure: greeting, body, sign-off.'),
  ('addition-with-carrying-simple-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Addition with Carrying (Simple)', '9 + 3 = 12. The concept that 10 ones become 1 ten. Use objects to cross the 10-barrier concretely.', 8, '5–10 min', 'Objects + tens and ones representation', '9 + 3 = 12. The concept that 10 ones become 1 ten. Use objects to cross the 10-barrier concretely.'),
  ('number-line-0-20-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Number Line (0-20)', 'Draw a number line 0-20 and use it for addition and subtraction. The number line models quantity spatially.', 8, '5–10 min', 'Paper', 'Draw a number line 0-20 and use it for addition and subtraction. The number line models quantity spatially.'),
  ('measure-with-non-standard-units-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Measure with Non-Standard Units', 'Measure the table using hand-spans, or the room using shoe-lengths. Non-standard measurement before cm.', 8, '5–10 min', 'Paper for recording', 'Measure the table using hand-spans, or the room using shoe-lengths. Non-standard measurement before cm.'),
  ('plant-life-cycle-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Plant Life Cycle', 'Seed → sprout → plant → flower → seed. Draw the cycle as a diagram. First cyclical thinking in science.', 8, '5–10 min', 'Paper and crayons', 'Seed → sprout → plant → flower → seed. Draw the cycle as a diagram. First cyclical thinking in science.'),
  ('force-and-motion-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Force and Motion', 'Push a toy car on carpet vs smooth floor. Why is one harder? Forces changing motion -- first physics concept.', 8, '5–10 min', 'Toy car, different surfaces', 'Push a toy car on carpet vs smooth floor. Why is one harder? Forces changing motion -- first physics concept.'),
  ('3d-shape-names-y4_0', 'cognitive'::domain, 'y4_0'::age_band, '3D Shape Names', 'Cube, sphere, cylinder, cone, pyramid. Match to household objects. 3D shape language before formal geometry.', 8, '5–10 min', 'Household objects', 'Cube, sphere, cylinder, cone, pyramid. Match to household objects. 3D shape language before formal geometry.'),
  ('recognise-when-you-need-help-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'Recognise When You Need Help', 'This is too hard for me right now. I need support.'' Asking for help before frustration peaks is executive function.', null, 'Ongoing', 'None', 'This is too hard for me right now. I need support.'' Asking for help before frustration peaks is executive function.'),
  ('handle-being-wrong-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'Handle Being Wrong', 'When corrected, respond: ''Oh, I see. So I was wrong about that -- I''ll try to remember.'' Model and practice.', null, 'Ongoing', 'None', 'When corrected, respond: ''Oh, I see. So I was wrong about that -- I''ll try to remember.'' Model and practice.'),
  ('interest-in-another-s-world-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'Interest in Another''s World', 'What is your favourite thing? Tell me all about it.'' Genuine curiosity about another''s inner life -- theory of mind growing.', 8, '5–10 min', 'None', 'What is your favourite thing? Tell me all about it.'' Genuine curiosity about another''s inner life -- theory of mind growing.'),
  ('disagree-politely-with-adult-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'Disagree Politely with Adult', 'I think it might be a bit different because...'' Respectful disagreement with authority. Assertiveness, not defiance.', null, 'Ongoing', 'None', 'I think it might be a bit different because...'' Respectful disagreement with authority. Assertiveness, not defiance.'),
  ('group-project-contribution-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'Group Project Contribution', 'Work on a group project (art, building, game). Contribute without needing to lead or control -- fellowship skill.', 18, '15–20 min', 'Group activity materials', 'Work on a group project (art, building, game). Contribute without needing to lead or control -- fellowship skill.'),
  ('take-care-of-something-living-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'Take Care of Something Living', 'Water a plant daily for a week. Small, consistent caretaking responsibility builds empathy and agency together.', null, 'Ongoing', 'Plant and watering can', 'Water a plant daily for a week. Small, consistent caretaking responsibility builds empathy and agency together.'),
  ('leaf-printing-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Leaf Printing', 'Press autumn leaves with paint onto paper. Vein detail prints clearly -- observe the structure of the leaf in the print.', 13, '10–15 min', 'Leaves, paint, paper', 'Press autumn leaves with paint onto paper. Vein detail prints clearly -- observe the structure of the leaf in the print.'),
  ('make-instruments-shakers-drums-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Make Instruments (Shakers, Drums)', 'Fill bottles with different amounts of rice for shakers, stretch rubber band across box for guitar. Sound science.', 18, '15–20 min', 'Bottles, rice, rubber bands, boxes', 'Fill bottles with different amounts of rice for shakers, stretch rubber band across box for guitar. Sound science.'),
  ('dark-room-torch-exploration-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Dark Room Torch Exploration', 'In a darkened room: explore what the torch illuminates. Experiment with angles, distance, colour.', 13, '10–15 min', 'Torch', 'In a darkened room: explore what the torch illuminates. Experiment with angles, distance, colour.'),
  ('make-a-kite-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Make a Kite', 'Simple kite from paper, sticks, and string. Fly it -- observe how wind interacts with a surface.', 18, '15–20 min', 'Paper, sticks, string', 'Simple kite from paper, sticks, and string. Fly it -- observe how wind interacts with a surface.'),
  ('cooking-simple-dish-solo-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Cooking (Simple Dish Solo)', 'With adult present, child independently makes a simple dish: boiled egg, toast, fruit salad.', 25, '20–30 min', 'Simple food items', 'With adult present, child independently makes a simple dish: boiled egg, toast, fruit salad.'),
  ('manage-pocket-money-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'Manage Pocket Money', 'Given a small amount per week. Track what was spent and saved. Money management from the first rupee.', null, 'Ongoing', 'Small amount of real money', 'Given a small amount per week. Track what was spent and saved. Money management from the first rupee.'),
  ('first-aid-basics-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'First Aid Basics', 'Learn: stop bleeding with pressure, run cold water on burns. Two specific first-aid responses a 4-year-old can perform.', 8, '5–10 min', 'Bandage, cold water', 'Learn: stop bleeding with pressure, run cold water on burns. Two specific first-aid responses a 4-year-old can perform.'),
  ('bicycle-without-training-wheels-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Bicycle Without Training Wheels', 'Remove training wheels when balance bike balance is good. First real bike = one of the most complex motor achievements of childhood.', 18, '15–20 min', 'Bicycle without training wheels', 'Remove training wheels when balance bike balance is good. First real bike = one of the most complex motor achievements of childhood.'),
  ('skip-with-rope-self-turning-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Skip with Rope (Self-Turning)', 'Turn own rope and jump: 10+ consecutive jumps. Coordinating arm circles and leg jumps is a high-level motor achievement.', 13, '10–15 min', 'Jump rope', 'Turn own rope and jump: 10+ consecutive jumps. Coordinating arm circles and leg jumps is a high-level motor achievement.'),
  ('throw-and-catch-partner-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Throw and Catch (Partner)', 'Throw and catch with a partner at 3-m distance: underhand, overhand, and bounce throw variants.', 8, '5–10 min', 'Ball', 'Throw and catch with a partner at 3-m distance: underhand, overhand, and bounce throw variants.'),
  ('kick-penalty-goal-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Kick Penalty Goal', 'Set up a small goal; kick from 3 m with power and aim. Combining power, direction, and timing.', 8, '5–10 min', 'Ball + goal (two objects)', 'Set up a small goal; kick from 3 m with power and aim. Combining power, direction, and timing.'),
  ('backwards-skip-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Backwards Skip', 'Skip backwards -- significantly harder than forward as direction reversal and coordination must both work.', 7, '5–8 min', 'None', 'Skip backwards -- significantly harder than forward as direction reversal and coordination must both work.'),
  ('cartwheels-attempt-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Cartwheels (Attempt)', 'Demonstrate a cartwheel and let child try. Controlled weight-bearing through hands + leg extension = advanced gymnastics.', 7, '5–8 min', 'Open safe space', 'Demonstrate a cartwheel and let child try. Controlled weight-bearing through hands + leg extension = advanced gymnastics.'),
  ('swim-basic-stroke-if-exposed-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Swim Basic Stroke (If Exposed)', 'If swimming opportunity: 5-metre distance, any stroke, with floaties if needed. Water confidence first.', 18, '15–20 min', 'Swimming pool', 'If swimming opportunity: 5-metre distance, any stroke, with floaties if needed. Water confidence first.'),
  ('sprint-30-metres-timed-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Sprint 30 Metres (Timed)', 'Time a 30-metre sprint and record. Tracking personal speed progress -- intrinsic motivation + physical literacy.', 7, '5–8 min', 'Open space + timer', 'Time a 30-metre sprint and record. Tracking personal speed progress -- intrinsic motivation + physical literacy.'),
  ('letter-formation-q-v-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Letter Formation (Q-V)', 'Correct formation of letters Q, R, S, T, U, V -- including the trickiest ones that children reverse.', 8, '5–10 min', 'Pencil and paper', 'Correct formation of letters Q, R, S, T, U, V -- including the trickiest ones that children reverse.'),
  ('sewing-a-simple-shape-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Sewing a Simple Shape', 'Sew around the outline of a simple shape on fabric. Following a curved line in sewing.', 18, '15–20 min', 'Fabric, blunt needle, thread', 'Sew around the outline of a simple shape on fabric. Following a curved line in sewing.'),
  ('tie-a-bow-shoelace-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Tie a Bow (Shoelace)', 'Teach shoe-tying: make rabbit ears method or loop-swoop-pull. This is one of the hardest fine motor tasks of early childhood.', 13, '10–15 min', 'Shoelace or practice board', 'Teach shoe-tying: make rabbit ears method or loop-swoop-pull. This is one of the hardest fine motor tasks of early childhood.'),
  ('mosaic-or-tile-pattern-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Mosaic or Tile Pattern', 'Create a geometric mosaic using small square stickers or paper. Colour planning + precision placement.', 18, '15–20 min', 'Small coloured squares, grid, glue', 'Create a geometric mosaic using small square stickers or paper. Colour planning + precision placement.'),
  ('carve-soap-or-clay-subtractive-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Carve Soap or Clay (Subtractive)', 'Use a blunt tool to remove clay or carve soft soap. Subtractive sculpture is very different from additive building.', 18, '15–20 min', 'Soap bar or firm clay + blunt tool', 'Use a blunt tool to remove clay or carve soft soap. Subtractive sculpture is very different from additive building.'),
  ('design-then-build-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Design Then Build', 'Design a structure on paper, then build it with available materials. Does the result match the plan? Adjust if not.', 18, '15–20 min', 'Drawing materials + building materials', 'Design a structure on paper, then build it with available materials. Does the result match the plan? Adjust if not.'),
  ('read-level-2-reader-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Read Level-2 Reader', 'Level 2: 12-16 pages, more varied vocabulary, less repetition. Reading pace and fluency building.', 13, '10–15 min', 'Level 2 early reader', 'Level 2: 12-16 pages, more varied vocabulary, less repetition. Reading pace and fluency building.'),
  ('write-a-recount-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Write a Recount', 'Write 3-4 sentences about what you did yesterday. Past-tense writing + event sequencing + punctuation awareness.', 13, '10–15 min', 'Pencil and paper', 'Write 3-4 sentences about what you did yesterday. Past-tense writing + event sequencing + punctuation awareness.'),
  ('punctuation-awareness-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Punctuation Awareness', 'Full stop ends a sentence. Question mark for questions. Read a sentence and identify punctuation.', 7, '5–8 min', 'Book or written sentence', 'Full stop ends a sentence. Question mark for questions. Read a sentence and identify punctuation.'),
  ('parts-of-a-story-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Parts of a Story', 'Story has: characters, setting, problem, events, resolution. Identify each in a known story. Story grammar.', 8, '5–10 min', 'Familiar book', 'Story has: characters, setting, problem, events, resolution. Identify each in a known story. Story grammar.'),
  ('read-aloud-with-expression-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Read Aloud with Expression', 'Read a passage with appropriate volume, pace, and expression. Fluent expressive reading comprehension.', 8, '5–10 min', 'Any text', 'Read a passage with appropriate volume, pace, and expression. Fluent expressive reading comprehension.'),
  ('persuasive-letter-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Persuasive Letter', 'Write (or dictate) a letter asking for something with 2 reasons. ''Dear Papa, I would like a dog because...''', 8, '5–10 min', 'Pencil and paper', 'Write (or dictate) a letter asking for something with 2 reasons. ''Dear Papa, I would like a dog because...'''),
  ('create-crossword-for-family-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Create Crossword for Family', 'Make a simple 5-clue crossword for a family member to solve. Word knowledge + spelling + spatial placement.', 13, '10–15 min', 'Pencil, paper, ruler', 'Make a simple 5-clue crossword for a family member to solve. Word knowledge + spelling + spatial placement.'),
  ('newspaper-report-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Newspaper Report', 'Write a ''news report'' about something that happened today: Headline + Who + What + When + Where.', 13, '10–15 min', 'Pencil and paper', 'Write a ''news report'' about something that happened today: Headline + Who + What + When + Where.'),
  ('multiplication-introduction-grouping-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Multiplication Introduction (Grouping)', '2 groups of 3 = 6 total. Physical grouping before the times table. ''Multiplication means equal groups.''', 8, '5–10 min', 'Small objects for grouping', '2 groups of 3 = 6 total. Physical grouping before the times table. ''Multiplication means equal groups.'''),
  ('division-introduction-sharing-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Division Introduction (Sharing)', '12 objects shared equally among 4 people -- how many each? Concrete sharing before the division symbol.', 8, '5–10 min', '12 small objects', '12 objects shared equally among 4 people -- how many each? Concrete sharing before the division symbol.'),
  ('fractions-and-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Fractions (½ and ¼)', 'Show ½ and ¼ with folded paper and with food. ''We cut the pizza into 4 equal pieces -- each is one quarter.''', 8, '5–10 min', 'Paper and food (apple, roti)', 'Show ½ and ¼ with folded paper and with food. ''We cut the pizza into 4 equal pieces -- each is one quarter.'''),
  ('weather-patterns-observation-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Weather Patterns (Observation)', 'Keep a 5-day weather journal: sunny, cloudy, rainy, windy. Weather prediction by pattern recognition.', null, 'Ongoing', 'Drawing journal', 'Keep a 5-day weather journal: sunny, cloudy, rainy, windy. Weather prediction by pattern recognition.'),
  ('simple-electrical-circuit-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Simple Electrical Circuit', 'Battery + wire + bulb. Does the light go on? What happens if we break the circuit? Simple electricity science.', 13, '10–15 min', 'Small battery, wire, bulb (from toy)', 'Battery + wire + bulb. Does the light go on? What happens if we break the circuit? Simple electricity science.'),
  ('clock-reading-hour-and-half-hour-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Clock Reading (Hour and Half Hour)', 'Read a clock at exact hours and half hours. Analogue clock before digital -- analogue requires spatial reasoning.', 8, '5–10 min', 'Analogue clock or drawn clock face', 'Read a clock at exact hours and half hours. Analogue clock before digital -- analogue requires spatial reasoning.'),
  ('mentor-a-younger-child-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Mentor a Younger Child', 'Teach a younger sibling or cousin how to do something: a game, a craft, a skill. Teaching consolidates the teacher''s own knowledge.', 18, '15–20 min', 'None', 'Teach a younger sibling or cousin how to do something: a game, a craft, a skill. Teaching consolidates the teacher''s own knowledge.'),
  ('handle-peer-conflict-independently-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Handle Peer Conflict Independently', 'When a peer conflict arises, step back and let child attempt resolution before intervening. Debrief after.', null, 'Ongoing', 'None', 'When a peer conflict arises, step back and let child attempt resolution before intervening. Debrief after.'),
  ('understand-different-opinions-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Understand Different Opinions', 'She thinks it''s scary. You think it''s exciting. Both of you are right about what YOU feel.'' Opinion diversity.', null, 'Ongoing', 'None', 'She thinks it''s scary. You think it''s exciting. Both of you are right about what YOU feel.'' Opinion diversity.'),
  ('make-a-family-decision-together-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Make a Family Decision Together', 'Family meeting on a small household decision: where to eat, what film to watch. Child''s vote counts equally.', 13, '10–15 min', 'None', 'Family meeting on a small household decision: where to eat, what film to watch. Child''s vote counts equally.'),
  ('identify-own-strengths-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Identify Own Strengths', 'Name 3 things you''re really good at. Name 1 thing you''re still working on.'' Balanced self-assessment.', 7, '5–8 min', 'None', 'Name 3 things you''re really good at. Name 1 thing you''re still working on.'' Balanced self-assessment.'),
  ('volunteer-or-help-community-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Volunteer or Help Community', 'Help a neighbour carry groceries, participate in a local clean-up. Community beyond family -- prosocial behaviour.', 18, '15–20 min', 'None', 'Help a neighbour carry groceries, participate in a local clean-up. Community beyond family -- prosocial behaviour.'),
  ('marble-run-engineering-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Marble Run Engineering', 'Design, build, and test a marble run from tubes and tape. Engineering: hypothesis, build, test, iterate.', 25, '20–30 min', 'Tubes, tape, marbles or balls', 'Design, build, and test a marble run from tubes and tape. Engineering: hypothesis, build, test, iterate.'),
  ('dissect-a-flower-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Dissect a Flower', 'Pull a flower apart carefully and identify petal, stamen, pistil, sepal. Biology observation + language + fine motor.', 18, '15–20 min', 'Flower', 'Pull a flower apart carefully and identify petal, stamen, pistil, sepal. Biology observation + language + fine motor.'),
  ('make-and-test-boats-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Make and Test Boats', 'Fold and build boats from various materials; test which floats best. Buoyancy hypothesis and testing.', 18, '15–20 min', 'Paper, foil, clay + water container', 'Fold and build boats from various materials; test which floats best. Buoyancy hypothesis and testing.'),
  ('stargazing-and-moon-journal-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Stargazing and Moon Journal', 'On clear nights, observe the moon''s shape and draw it. Moon phase pattern recognition over 4 weeks.', 13, '10–15 min', 'Drawing journal', 'On clear nights, observe the moon''s shape and draw it. Moon phase pattern recognition over 4 weeks.'),
  ('make-natural-dyes-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Make Natural Dyes', 'Boil beetroot or turmeric in water; dye fabric. Colour science + sensory + natural material exploration.', 25, '20–30 min', 'Beetroot or turmeric, water, fabric', 'Boil beetroot or turmeric in water; dye fabric. Colour science + sensory + natural material exploration.'),
  ('cook-a-full-simple-meal-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Cook a Full Simple Meal', 'With supervision, cook a full simple meal: dal-rice or pasta. Planning, sequencing, measuring, timing.', 38, '30–45 min', 'Kitchen ingredients and tools', 'With supervision, cook a full simple meal: dal-rice or pasta. Planning, sequencing, measuring, timing.'),
  ('manage-own-health-basics-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Manage Own Health (Basics)', 'I feel sick -- I have a headache/tummy ache.'' Accurately naming and reporting own physical state to an adult.', null, 'Ongoing', 'None', 'I feel sick -- I have a headache/tummy ache.'' Accurately naming and reporting own physical state to an adult.'),
  ('sprint-with-baton-pass-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Sprint with Baton Pass', 'Sprint 10 m, pass an object to a partner who sprints on. Hand-off requires timing and spatial awareness in motion.', 13, '10–15 min', 'Small object as baton', 'Sprint 10 m, pass an object to a partner who sprints on. Hand-off requires timing and spatial awareness in motion.'),
  ('hop-scotch-full-game-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Hop Scotch (Full Game)', 'Hop, jump, pick up stone, hop back. Number sequence + motor planning + balance all in one traditional game.', 13, '10–15 min', 'Chalk or tape + stone', 'Hop, jump, pick up stone, hop back. Number sequence + motor planning + balance all in one traditional game.'),
  ('swim-10-metres-if-exposed-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Swim 10 Metres (If Exposed)', 'Independent 10-metre swim with any stroke. Breathing technique + stroke + direction = three systems coordinating.', 18, '15–20 min', 'Swimming pool', 'Independent 10-metre swim with any stroke. Breathing technique + stroke + direction = three systems coordinating.'),
  ('throw-and-catch-one-hand-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Throw and Catch (One Hand)', 'One-handed catch from 2 m. Requires faster hand positioning decision than two-handed catching.', 8, '5–10 min', 'Small ball', 'One-handed catch from 2 m. Requires faster hand positioning decision than two-handed catching.'),
  ('gymnastics-roll-bridge-cartwheel-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Gymnastics (Roll, Bridge, Cartwheel)', 'Forward roll + bridge + cartwheel attempt in sequence. Gymnastics sequence requires memory + motor execution.', 8, '5–10 min', 'Soft surface', 'Forward roll + bridge + cartwheel attempt in sequence. Gymnastics sequence requires memory + motor execution.'),
  ('balance-on-skateboard-board-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Balance on Skateboard/Board', 'Balance on a skateboard or wooden board. Dynamic balance on an unstable surface -- high-level proprioception.', 8, '5–10 min', 'Skateboard or plank on rolled towels', 'Balance on a skateboard or wooden board. Dynamic balance on an unstable surface -- high-level proprioception.'),
  ('dribble-basketball-both-hands-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Dribble Basketball (Both Hands)', 'Dribble 5 times with right, 5 with left. Non-dominant hand dribbling is significantly harder.', 8, '5–10 min', 'Basketball or large ball', 'Dribble 5 times with right, 5 with left. Non-dominant hand dribbling is significantly harder.'),
  ('long-jump-distance-record-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Long Jump (Distance Record)', 'Jump as far as possible from standing; mark and measure. Track personal record over weeks.', 7, '5–8 min', 'Tape measure or ruler', 'Jump as far as possible from standing; mark and measure. Track personal record over weeks.'),
  ('letter-formation-w-z-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Letter Formation (W-Z)', 'Complete the alphabet: W, X, Y, Z. Child can now write the full alphabet from memory.', 8, '5–10 min', 'Pencil and paper', 'Complete the alphabet: W, X, Y, Z. Child can now write the full alphabet from memory.'),
  ('perspective-drawing-simple-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Perspective Drawing (Simple)', 'Draw a room from above (bird''s-eye view). Point of view and spatial representation together.', 13, '10–15 min', 'Drawing materials', 'Draw a room from above (bird''s-eye view). Point of view and spatial representation together.'),
  ('cross-stitch-3-3-grid-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Cross Stitch (3×3 Grid)', 'A 9-cross cross-stitch in a simple pattern. Requires holding the pattern in mind while executing each cross.', 18, '15–20 min', 'Canvas, needle, embroidery thread', 'A 9-cross cross-stitch in a simple pattern. Requires holding the pattern in mind while executing each cross.'),
  ('build-circuit-light-or-motor-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Build Circuit (Light or Motor)', 'Add a switch to the battery-wire-bulb circuit. Switch = control of a circuit = power concepts.', 13, '10–15 min', 'Battery, wire, bulb, paper-clip switch', 'Add a switch to the battery-wire-bulb circuit. Switch = control of a circuit = power concepts.'),
  ('carve-vegetable-print-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Carve Vegetable Print', 'Press a carved potato or carrot into paint and print. Subtractive carving + repetitive printing.', 18, '15–20 min', 'Potato or carrot, blunt carving tool, paint', 'Press a carved potato or carrot into paint and print. Subtractive carving + repetitive printing.'),
  ('design-logo-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Design Logo', 'Design a simple logo for an imaginary brand. Design thinking + creativity + fine motor communication.', 13, '10–15 min', 'Drawing materials', 'Design a simple logo for an imaginary brand. Design thinking + creativity + fine motor communication.'),
  ('read-a-chapter-book-first-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Read a Chapter Book (First)', 'First chapter book: short chapters, many illustrations. Reading across multiple sessions = stamina and memory together.', 18, '15–20 min', 'Age-appropriate chapter book', 'First chapter book: short chapters, many illustrations. Reading across multiple sessions = stamina and memory together.'),
  ('write-a-poem-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Write a Poem', 'Rhyming couplets or free verse about a favourite thing. Poetry writing = word choice precision.', 13, '10–15 min', 'Pencil and paper', 'Rhyming couplets or free verse about a favourite thing. Poetry writing = word choice precision.'),
  ('read-aloud-to-younger-child-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Read Aloud to Younger Child', 'Read a picture book to a younger sibling or cousin. Teaching reading consolidates the reader''s own skill.', 13, '10–15 min', 'Picture book', 'Read a picture book to a younger sibling or cousin. Teaching reading consolidates the reader''s own skill.'),
  ('word-problem-in-maths-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Word Problem in Maths', 'Riya has 8 mangoes. She gives 3 to her friend. How many remain?'' Language + maths = real-world numeracy.', 8, '5–10 min', 'None', 'Riya has 8 mangoes. She gives 3 to her friend. How many remain?'' Language + maths = real-world numeracy.'),
  ('speech-favourite-topic-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Speech: Favourite Topic', 'Prepare and deliver a 2-minute talk on a favourite subject. Structure: introduction, 3 points, conclusion.', 13, '10–15 min', 'None', 'Prepare and deliver a 2-minute talk on a favourite subject. Structure: introduction, 3 points, conclusion.'),
  ('alliteration-and-assonance-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Alliteration and Assonance', 'Peter Piper picked...'' Tongue twisters. Alliteration awareness = phonological sensitivity at its most playful.', 7, '5–8 min', 'None', 'Peter Piper picked...'' Tongue twisters. Alliteration awareness = phonological sensitivity at its most playful.'),
  ('research-a-topic-guided-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Research a Topic (Guided)', 'Choose an animal or place. Find 5 facts using books or supervised internet. ''Where did you find each fact?''', 18, '15–20 min', 'Books or supervised device', 'Choose an animal or place. Find 5 facts using books or supervised internet. ''Where did you find each fact?'''),
  ('write-instructions-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Write Instructions', 'Write step-by-step instructions for making something they know. Procedural text with numbered steps.', 13, '10–15 min', 'Pencil and paper', 'Write step-by-step instructions for making something they know. Procedural text with numbered steps.'),
  ('times-tables-2-and-5-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Times Tables (2 and 5)', 'Learn 2x and 5x tables through songs and patterns. Multiplicative reasoning before the tables is memorised.', 8, '5–10 min', 'None', 'Learn 2x and 5x tables through songs and patterns. Multiplicative reasoning before the tables is memorised.'),
  ('understand-place-value-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Understand Place Value', 'Ones, tens, hundreds with physical objects (lentils in cups). Bundling 10 ones into 1 ten concretely.', 8, '5–10 min', 'Lentils or objects + cups', 'Ones, tens, hundreds with physical objects (lentils in cups). Bundling 10 ones into 1 ten concretely.'),
  ('graph-reading-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Graph Reading', 'Read a simple bar graph: ''Which colour got the most votes?'' Information extraction from data representation.', 7, '5–8 min', 'Simple bar graph', 'Read a simple bar graph: ''Which colour got the most votes?'' Information extraction from data representation.'),
  ('life-cycles-frog-or-butterfly-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Life Cycles (Frog or Butterfly)', 'Egg → tadpole/caterpillar → frog/butterfly. Draw the cycle. Compare to plant life cycle studied earlier.', 8, '5–10 min', 'Drawing materials', 'Egg → tadpole/caterpillar → frog/butterfly. Draw the cycle. Compare to plant life cycle studied earlier.'),
  ('simple-machines-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Simple Machines', 'Lever, wheel, ramp. Demonstrate each with household items: broom as lever, pencil under book as wheel.', 8, '5–10 min', 'Broom, pencil, book', 'Lever, wheel, ramp. Demonstrate each with household items: broom as lever, pencil under book as wheel.'),
  ('map-making-neighbourhood-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Map Making (Neighbourhood)', 'Draw a map of the local area from memory. What''s near our house? What direction is the park?', 13, '10–15 min', 'Paper and crayons', 'Draw a map of the local area from memory. What''s near our house? What direction is the park?'),
  ('self-manage-task-completion-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Self-Manage Task Completion', 'I said I would finish this today. I haven''t yet -- what do I need to do to finish it?'' Task commitment + follow-through.', null, 'Ongoing', 'None', 'I said I would finish this today. I haven''t yet -- what do I need to do to finish it?'' Task commitment + follow-through.'),
  ('peer-teaching-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Peer Teaching', 'Teach a peer (not sibling) how to play a game or do a craft. Social teaching requires reading the other person''s learning.', 18, '15–20 min', 'Game or craft materials', 'Teach a peer (not sibling) how to play a game or do a craft. Social teaching requires reading the other person''s learning.'),
  ('navigate-clique-dynamics-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Navigate Clique Dynamics', 'What happened when you felt left out? How did it feel? What did you do?'' Social complexity is real now.', 8, '5–10 min', 'None', 'What happened when you felt left out? How did it feel? What did you do?'' Social complexity is real now.'),
  ('goal-setting-weekly-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Goal Setting (Weekly)', 'Set 1 small goal for the week: practice reading 10 min daily, learn to tie shoes. Review at end of week.', 7, '5–8 min', 'Paper for recording the goal', 'Set 1 small goal for the week: practice reading 10 min daily, learn to tie shoes. Review at end of week.'),
  ('recognise-peer-emotions-in-real-time-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Recognise Peer Emotions in Real Time', 'Your friend looks upset right now. What do you think happened?'' Reading real social cues in real time.', null, 'Ongoing', 'None', 'Your friend looks upset right now. What do you think happened?'' Reading real social cues in real time.'),
  ('cultural-curiosity-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Cultural Curiosity', 'Learn about a different cultural celebration or tradition. Curiosity about difference before judgement.', 8, '5–10 min', 'Book or conversation with family', 'Learn about a different cultural celebration or tradition. Curiosity about difference before judgement.'),
  ('build-a-terrarium-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Build a Terrarium', 'Soil, stones, small plants in a glass container. Ecosystem awareness + ongoing observation responsibility.', 25, '20–30 min', 'Container, soil, stones, small plant', 'Soil, stones, small plants in a glass container. Ecosystem awareness + ongoing observation responsibility.'),
  ('colour-mixing-science-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Colour-Mixing Science', 'Mix food colours: R+B=purple, B+Y=green, R+Y=orange. Record predictions and results. Science method.', 13, '10–15 min', 'Food colouring, white paper, brushes', 'Mix food colours: R+B=purple, B+Y=green, R+Y=orange. Record predictions and results. Science method.'),
  ('knot-tying-3-types-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Knot Tying (3 Types)', 'Overhand, reef knot, simple hitch. Practical knot knowledge + fine motor + spatial manipulation.', 18, '15–20 min', 'Rope', 'Overhand, reef knot, simple hitch. Practical knot knowledge + fine motor + spatial manipulation.'),
  ('rhythm-composition-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Rhythm Composition', 'Create a 4-beat rhythm using body percussion; teach it to a family member. Composition + teaching = music literacy.', 13, '10–15 min', 'None', 'Create a 4-beat rhythm using body percussion; teach it to a family member. Composition + teaching = music literacy.'),
  ('taste-and-describe-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Taste and Describe', 'Blind taste test: describe 6 foods using texture, temperature, and taste words. Sensory vocabulary building.', 13, '10–15 min', '6 small food items', 'Blind taste test: describe 6 foods using texture, temperature, and taste words. Sensory vocabulary building.'),
  ('personal-safety-rules-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Personal Safety Rules', 'Know: full name + parent''s phone number + home address. First safety information a child should own.', 8, '5–10 min', 'None', 'Know: full name + parent''s phone number + home address. First safety information a child should own.'),
  ('budget-for-outing-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Budget for Outing', 'Given a small amount: plan what to spend it on for a family outing. Prioritisation + arithmetic + negotiation.', 13, '10–15 min', 'Small amount of real money', 'Given a small amount: plan what to spend it on for a family outing. Prioritisation + arithmetic + negotiation.'),
  ('sprint-circuit-5-stations-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Sprint Circuit (5 Stations)', 'Run a 5-station circuit: sprint, hop, jump, crawl, balance. Switching motor tasks = executive function + physical fitness.', 13, '10–15 min', 'Open space + station markers', 'Run a 5-station circuit: sprint, hop, jump, crawl, balance. Switching motor tasks = executive function + physical fitness.'),
  ('play-team-sport-simple-rules-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Play Team Sport (Simple Rules)', 'Relay race, simple football, or cricket with basic rules. Team sport introduces strategy, roles, and shared outcome.', 18, '15–20 min', 'None', 'Relay race, simple football, or cricket with basic rules. Team sport introduces strategy, roles, and shared outcome.'),
  ('bicycle-on-rough-terrain-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Bicycle on Rough Terrain', 'Ride on grass or gravel path. Variable surface challenges balance and steering significantly more than pavement.', 13, '10–15 min', 'Bicycle', 'Ride on grass or gravel path. Variable surface challenges balance and steering significantly more than pavement.'),
  ('swim-25-metres-if-exposed-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Swim 25 Metres (If Exposed)', '25-metre length swim independently. Breath control + stroke + endurance = full swimming foundation.', 18, '15–20 min', 'Swimming pool', '25-metre length swim independently. Breath control + stroke + endurance = full swimming foundation.'),
  ('gymnastics-floor-sequence-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Gymnastics Floor Sequence', '3-element sequence: roll, balance, jump. Remembering and performing a sequence of gymnastic elements.', 8, '5–10 min', 'Soft surface', '3-element sequence: roll, balance, jump. Remembering and performing a sequence of gymnastic elements.'),
  ('dance-sequence-8-moves-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Dance Sequence (8 Moves)', 'Learn an 8-move dance sequence. Memory of movement sequence + rhythmic execution.', 13, '10–15 min', 'Music', 'Learn an 8-move dance sequence. Memory of movement sequence + rhythmic execution.'),
  ('throw-and-catch-moving-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Throw and Catch Moving', 'Throw and catch while both thrower and catcher are walking. Moving target + moving thrower = high complexity.', 8, '5–10 min', 'Ball', 'Throw and catch while both thrower and catcher are walking. Moving target + moving thrower = high complexity.'),
  ('controlled-dribble-around-cones-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Controlled Dribble Around Cones', 'Dribble a ball around 5 cones without knocking them. Precision + continuous ball control.', 13, '10–15 min', 'Ball + 5 objects as cones', 'Dribble a ball around 5 cones without knocking them. Precision + continuous ball control.'),
  ('full-alphabet-in-capitals-lowercase-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Full Alphabet in Capitals + Lowercase', 'Write the complete alphabet in both forms from memory. Automatised handwriting foundation.', 8, '5–10 min', 'Pencil and paper', 'Write the complete alphabet in both forms from memory. Automatised handwriting foundation.'),
  ('comic-strip-creation-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Comic Strip Creation', 'Draw a 4-panel comic: character, problem, action, resolution. Narrative in sequential visual medium.', 18, '15–20 min', 'Drawing materials', 'Draw a 4-panel comic: character, problem, action, resolution. Narrative in sequential visual medium.'),
  ('puppet-making-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Puppet Making', 'Create a puppet from a sock or paper bag; design the face and outfit. Then perform with it.', 25, '20–30 min', 'Sock or paper bag, fabric, glue, markers', 'Create a puppet from a sock or paper bag; design the face and outfit. Then perform with it.'),
  ('calligraphy-basic-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Calligraphy (Basic)', 'Make each letter with a thicker downstroke and thinner upstroke. Pressure control in mark-making.', 13, '10–15 min', 'Thick and thin markers or pencil', 'Make each letter with a thicker downstroke and thinner upstroke. Pressure control in mark-making.'),
  ('build-mechanical-toy-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Build Mechanical Toy', 'Build a simple lever or pulley from household materials. Engineering: how does the mechanism work?', 25, '20–30 min', 'Spools, string, card, tape', 'Build a simple lever or pulley from household materials. Engineering: how does the mechanism work?'),
  ('jigsaw-puzzle-50-100-pieces-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Jigsaw Puzzle (50-100 Pieces)', '50-to-100-piece puzzle independently. Strategy: edges first, then sort by colour, then connect sections.', 25, '20–30 min', '50-100 piece puzzle', '50-to-100-piece puzzle independently. Strategy: edges first, then sort by colour, then connect sections.'),
  ('read-chapter-book-100-pages-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Read Chapter Book (100 Pages)', '100-page chapter book independently over 1-2 weeks. Stamina + character memory + plot tracking.', 18, '15–20 min', 'Age-appropriate chapter book', '100-page chapter book independently over 1-2 weeks. Stamina + character memory + plot tracking.'),
  ('write-a-non-fiction-report-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Write a Non-Fiction Report', 'Choose a topic; write 4 paragraphs: introduction, 2 fact paragraphs, conclusion. Non-fiction structure.', 18, '15–20 min', 'Pencil and paper + reference books', 'Choose a topic; write 4 paragraphs: introduction, 2 fact paragraphs, conclusion. Non-fiction structure.'),
  ('debate-argue-both-sides-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Debate: Argue Both Sides', 'Argue FOR a position, then argue AGAINST it. Separating personal opinion from arguable position.', 13, '10–15 min', 'None', 'Argue FOR a position, then argue AGAINST it. Separating personal opinion from arguable position.'),
  ('reading-comprehension-questions-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Reading Comprehension Questions', 'After reading, answer: ''Who? What? When? Where? Why? How?'' All 6 questions, full sentence answers.', 13, '10–15 min', 'Age-appropriate text', 'After reading, answer: ''Who? What? When? Where? Why? How?'' All 6 questions, full sentence answers.'),
  ('vocabulary-context-clues-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Vocabulary: Context Clues', 'Read a sentence with an unfamiliar word: ''What do you think it means from the context?'' Inference from context.', 8, '5–10 min', 'Text with unfamiliar word', 'Read a sentence with an unfamiliar word: ''What do you think it means from the context?'' Inference from context.'),
  ('research-and-present-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Research and Present', 'Research one topic in books or supervised internet; present 3 facts to family with a drawn diagram. Information literacy.', 18, '15–20 min', 'Reference books or supervised device + drawing materials', 'Research one topic in books or supervised internet; present 3 facts to family with a drawn diagram. Information literacy.'),
  ('write-a-dialogue-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Write a Dialogue', 'Write a conversation between two characters: correct speech marks, new speaker = new line. Dialogue conventions.', 13, '10–15 min', 'Pencil and paper', 'Write a conversation between two characters: correct speech marks, new speaker = new line. Dialogue conventions.'),
  ('read-a-simple-newspaper-article-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Read a Simple Newspaper Article', 'Read a short article from a children''s newspaper or magazine. Non-fiction reading with unfamiliar vocabulary.', 13, '10–15 min', 'Children''s newspaper or magazine', 'Read a short article from a children''s newspaper or magazine. Non-fiction reading with unfamiliar vocabulary.'),
  ('times-tables-3-and-4-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Times Tables (3 and 4)', '3x and 4x tables through grouping activities. Physical arrangement of 4 groups of 3 before abstract recitation.', 8, '5–10 min', 'Objects for grouping', '3x and 4x tables through grouping activities. Physical arrangement of 4 groups of 3 before abstract recitation.'),
  ('fractions-on-number-line-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Fractions on Number Line', 'Place ½, ¼, ¾ on a number line. Fraction as a position -- not just a part of a whole.', 8, '5–10 min', 'Drawn number line 0 to 1', 'Place ½, ¼, ¾ on a number line. Fraction as a position -- not just a part of a whole.'),
  ('perimeter-simple-shape-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Perimeter (Simple Shape)', 'Measure the distance around a rectangle by counting or measuring each side. Perimeter as ''fence around a garden.''', 8, '5–10 min', 'Ruler, simple rectangle', 'Measure the distance around a rectangle by counting or measuring each side. Perimeter as ''fence around a garden.'''),
  ('food-chains-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Food Chains', 'Sun → plant → caterpillar → bird → hawk. Draw and label a simple food chain. Energy transfer in ecosystems.', 8, '5–10 min', 'Drawing materials', 'Sun → plant → caterpillar → bird → hawk. Draw and label a simple food chain. Energy transfer in ecosystems.'),
  ('states-of-matter-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'States of Matter', 'Solid, liquid, gas. Ice (solid) → water (liquid) → steam (gas). Observe the transitions. Scientific vocabulary.', 13, '10–15 min', 'Ice, water, kettle (supervised)', 'Solid, liquid, gas. Ice (solid) → water (liquid) → steam (gas). Observe the transitions. Scientific vocabulary.'),
  ('compass-directions-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Compass Directions', 'N, S, E, W. Use a compass or remember: ''Never Eat Shredded Wheat.'' Navigate outdoors using direction.', 8, '5–10 min', 'Compass (or drawn compass rose)', 'N, S, E, W. Use a compass or remember: ''Never Eat Shredded Wheat.'' Navigate outdoors using direction.'),
  ('set-own-goals-monthly-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Set Own Goals (Monthly)', 'At the start of a month, set 1 academic, 1 physical, 1 social goal. Review at month end: achieved? Why or why not?', 13, '10–15 min', 'None', 'At the start of a month, set 1 academic, 1 physical, 1 social goal. Review at month end: achieved? Why or why not?'),
  ('ask-adult-for-help-appropriately-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Ask Adult for Help Appropriately', 'Excuse me, I need some help with this when you have a moment.'' Polite adult-addressing in a real context.', null, 'Ongoing', 'None', 'Excuse me, I need some help with this when you have a moment.'' Polite adult-addressing in a real context.'),
  ('digital-citizenship-basics-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Digital Citizenship (Basics)', 'What is personal information? What shouldn''t you share online? Age-appropriate internet safety.', 13, '10–15 min', 'None', 'What is personal information? What shouldn''t you share online? Age-appropriate internet safety.'),
  ('manage-own-health-appointment-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Manage Own Health Appointment', 'Tell the doctor directly what hurts, where, and for how long. Patient self-reporting builds medical advocacy.', null, 'Ongoing', 'None', 'Tell the doctor directly what hurts, where, and for how long. Patient self-reporting builds medical advocacy.'),
  ('celebrate-others-without-envy-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Celebrate Others Without Envy', 'When a friend or sibling achieves something: genuine celebration without resentment. This is a hard skill -- model it.', null, 'Ongoing', 'None', 'When a friend or sibling achieves something: genuine celebration without resentment. This is a hard skill -- model it.'),
  ('read-facial-expressions-photos-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Read Facial Expressions (Photos)', 'Look at photos of faces: name the emotion and what might have caused it. Facial decoding with context inference.', 7, '5–8 min', 'Photos or illustrated cards', 'Look at photos of faces: name the emotion and what might have caused it. Facial decoding with context inference.'),
  ('dissection-fruit-or-vegetable-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Dissection (Fruit or Vegetable)', 'Dissect a vegetable (broccoli, cabbage) or fruit. Identify parts. Biology observation + vocabulary + fine motor.', 18, '15–20 min', 'Vegetable/fruit + blunt knife', 'Dissect a vegetable (broccoli, cabbage) or fruit. Identify parts. Biology observation + vocabulary + fine motor.'),
  ('build-a-bridge-engineering-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Build a Bridge (Engineering)', 'Build a bridge from paper that holds a weight. Test, identify failure point, redesign. Engineering design cycle.', 25, '20–30 min', 'Paper, tape, small weight', 'Build a bridge from paper that holds a weight. Test, identify failure point, redesign. Engineering design cycle.'),
  ('night-sky-observation-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Night-Sky Observation', 'Identify the moon phase, Venus, Jupiter if visible. Astronomy: systematic observation of the sky.', 13, '10–15 min', 'None (outdoors at night)', 'Identify the moon phase, Venus, Jupiter if visible. Astronomy: systematic observation of the sky.'),
  ('paper-marbling-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Paper Marbling', 'Oil + water in a tray + drops of ink or paint. Swirl and press paper. Transfer the pattern. Surprising and beautiful.', 18, '15–20 min', 'Oil, water, ink/paint, paper, tray', 'Oil + water in a tray + drops of ink or paint. Swirl and press paper. Transfer the pattern. Surprising and beautiful.'),
  ('sound-wave-experiment-y4_9', 'cognitive'::domain, 'y4_9'::age_band, 'Sound Wave Experiment', 'Sprinkle salt on a drum surface (stretched cling film over bowl) and speak loudly near it. Watch salt vibrate. Sound = waves.', 13, '10–15 min', 'Cling film, bowl, salt', 'Sprinkle salt on a drum surface (stretched cling film over bowl) and speak loudly near it. Watch salt vibrate. Sound = waves.'),
  ('personal-hygiene-independence-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Personal Hygiene Independence', 'Shower or bath completely independently: wash hair, soap all areas, dry off. Full body hygiene self-management.', 18, '15–20 min', 'Bathroom + toiletries', 'Shower or bath completely independently: wash hair, soap all areas, dry off. Full body hygiene self-management.'),
  ('laundry-contribution-y4_9', 'social_emotional'::domain, 'y4_9'::age_band, 'Laundry Contribution', 'Sort clothes by colour, load them, set the wash. Understanding home management systems.', 13, '10–15 min', 'Laundry items', 'Sort clothes by colour, load them, set the wash. Understanding home management systems.'),
  ('team-sport-with-strategy-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Team Sport with Strategy', 'Play a team sport with positional roles. ''What''s the strategy? What position are you playing?''', 25, '20–30 min', 'Team sport equipment', 'Play a team sport with positional roles. ''What''s the strategy? What position are you playing?'''),
  ('swim-with-breathing-technique-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Swim with Breathing Technique', 'Bilateral breathing in freestyle or any stroke over 25 m. Rhythmic breathing is the most demanding swimming element.', 18, '15–20 min', 'Swimming pool', 'Bilateral breathing in freestyle or any stroke over 25 m. Rhythmic breathing is the most demanding swimming element.'),
  ('cycling-route-planning-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Cycling Route Planning', 'Plan and cycle a route from memory: ''We go left at the tree, then right at the gate.'' Navigation + cycling combined.', 18, '15–20 min', 'Bicycle', 'Plan and cycle a route from memory: ''We go left at the tree, then right at the gate.'' Navigation + cycling combined.'),
  ('gymnastics-sequence-5-elements-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Gymnastics Sequence (5 Elements)', '5-element gymnastics sequence: roll, cartwheel, balance, jump, bridge. Memory + execution + transition.', 13, '10–15 min', 'Soft surface', '5-element gymnastics sequence: roll, cartwheel, balance, jump, bridge. Memory + execution + transition.'),
  ('jump-rope-double-dutch-attempt-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Jump Rope (Double Dutch Attempt)', 'Attempt to jump between two turning ropes. Timing two inputs simultaneously = complex visual-motor integration.', 13, '10–15 min', 'Two jump ropes', 'Attempt to jump between two turning ropes. Timing two inputs simultaneously = complex visual-motor integration.'),
  ('rock-climbing-bouldering-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Rock Climbing (Bouldering)', 'Indoor bouldering: read the route, plan the moves, execute. Spatial problem-solving + full-body motor control.', 25, '20–30 min', 'Bouldering wall or climbing frame', 'Indoor bouldering: read the route, plan the moves, execute. Spatial problem-solving + full-body motor control.'),
  ('sprint-with-technique-arms-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Sprint with Technique (Arms)', 'Run with correct arm action: 90° elbow, drive back (not cross). Technique improvement = physical literacy.', 8, '5–10 min', 'Open space', 'Run with correct arm action: 90° elbow, drive back (not cross). Technique improvement = physical literacy.'),
  ('relay-race-strategy-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Relay Race Strategy', 'In a relay: ''Where should I stand? When do I reach for the baton?'' Positional thinking in team sport.', 18, '15–20 min', 'Open space + baton', 'In a relay: ''Where should I stand? When do I reach for the baton?'' Positional thinking in team sport.'),
  ('write-a-story-full-structure-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Write a Story (Full Structure)', '600-word story: opening, build-up, problem, resolution, ending. Full narrative structure with character development.', 25, '20–30 min', 'Pencil and paper', '600-word story: opening, build-up, problem, resolution, ending. Full narrative structure with character development.'),
  ('technical-drawing-ruler-pencil-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Technical Drawing (Ruler + Pencil)', 'Draw the front and side view of a box using a ruler. Technical drawing requires precision + spatial reasoning.', 18, '15–20 min', 'Pencil, ruler, paper', 'Draw the front and side view of a box using a ruler. Technical drawing requires precision + spatial reasoning.'),
  ('build-electronic-kit-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Build Electronic Kit', 'Simple electronics kit: traffic light, sound circuit. Read the instructions and build. Engineering literacy.', 25, '20–30 min', 'Simple electronic kit', 'Simple electronics kit: traffic light, sound circuit. Read the instructions and build. Engineering literacy.'),
  ('engraving-foil-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Engraving (Foil)', 'Press designs into kitchen foil with a blunt pencil. The material yields beautifully to pressure -- force calibration.', 13, '10–15 min', 'Kitchen foil, cardboard backing, blunt pencil', 'Press designs into kitchen foil with a blunt pencil. The material yields beautifully to pressure -- force calibration.'),
  ('detailed-nature-drawing-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Detailed Nature Drawing', 'Draw an insect or plant in close detail using observation. Scientific illustration requires sustained fine motor and attention.', 18, '15–20 min', 'Drawing materials + specimen', 'Draw an insect or plant in close detail using observation. Scientific illustration requires sustained fine motor and attention.'),
  ('architectural-model-y5_0', 'motor'::domain, 'y5_0'::age_band, 'Architectural Model', 'Build a model of a room or building from cardboard. Scale and proportion thinking.', 25, '20–30 min', 'Cardboard, ruler, scissors, tape', 'Build a model of a room or building from cardboard. Scale and proportion thinking.'),
  ('read-chapter-book-200-pages-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Read Chapter Book (200+ Pages)', '200-page novel over 2-3 weeks. Complex plot, multiple characters, sustained memory across sessions.', 18, '15–20 min', 'Age-appropriate novel', '200-page novel over 2-3 weeks. Complex plot, multiple characters, sustained memory across sessions.'),
  ('write-an-argument-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Write an Argument', 'Write 4 paragraphs: introduction + claim, argument 1 + evidence, argument 2 + evidence, conclusion. Persuasive structure.', 18, '15–20 min', 'Pencil and paper', 'Write 4 paragraphs: introduction + claim, argument 1 + evidence, argument 2 + evidence, conclusion. Persuasive structure.'),
  ('understand-subtext-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Understand Subtext', 'The character says they''re fine. But what does the author want us to understand they''re really feeling?'' Subtext reading.', 8, '5–10 min', 'Story extract', 'The character says they''re fine. But what does the author want us to understand they''re really feeling?'' Subtext reading.'),
  ('reported-speech-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Reported Speech', 'Direct vs reported speech format Direct and reported speech -- a significant grammar distinction.', 8, '5–10 min', 'Any conversation or story', 'Direct vs reported speech format Direct and reported speech -- a significant grammar distinction.'),
  ('prefix-and-suffix-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Prefix and Suffix', 'Un-, re-, pre-, -ful, -less, -ness. How does adding a prefix or suffix change a word''s meaning?', 7, '5–8 min', 'None', 'Un-, re-, pre-, -ful, -less, -ness. How does adding a prefix or suffix change a word''s meaning?'),
  ('research-project-multi-source-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Research Project (Multi-Source)', 'Use 3 different sources (books) to research a topic. Compare what each says -- sources may differ. Critical research.', 25, '20–30 min', 'Multiple reference books', 'Use 3 different sources (books) to research a topic. Compare what each says -- sources may differ. Critical research.'),
  ('write-a-newspaper-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Write a Newspaper', 'Create a 2-page newspaper: headline story, sport report, weather, comic strip. Multiple text types in one project.', 25, '20–30 min', 'Pencil, paper, ruler', 'Create a 2-page newspaper: headline story, sport report, weather, comic strip. Multiple text types in one project.'),
  ('grammar-clauses-and-phrases-y5_0', 'communication'::domain, 'y5_0'::age_band, 'Grammar: Clauses and Phrases', 'The dog ran'' is a clause. ''In the garden'' is a phrase. Identify in sentences. Formal grammar awareness.', 8, '5–10 min', 'Printed sentences', 'The dog ran'' is a clause. ''In the garden'' is a phrase. Identify in sentences. Formal grammar awareness.'),
  ('times-tables-6-7-8-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Times Tables (6, 7, 8)', '6x, 7x, 8x -- the most difficult tables. Songs, physical arrangements, and chanting all help. Repetition over time.', 8, '5–10 min', 'None', '6x, 7x, 8x -- the most difficult tables. Songs, physical arrangements, and chanting all help. Repetition over time.'),
  ('long-multiplication-2-digit-1-digit-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Long Multiplication (2-Digit × 1-Digit)', '23 × 4 using the grid method: 20×4 + 3×4. Breaking a large multiplication into parts -- distributive property.', 8, '5–10 min', 'Pencil and paper', '23 × 4 using the grid method: 20×4 + 3×4. Breaking a large multiplication into parts -- distributive property.'),
  ('bar-graph-creation-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Bar Graph Creation', 'Gather data (family preferences), create a bar graph, and write 3 conclusions. Data literacy with self-generated data.', 13, '10–15 min', 'Pencil, paper, ruler', 'Gather data (family preferences), create a bar graph, and write 3 conclusions. Data literacy with self-generated data.'),
  ('earth-and-solar-system-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Earth and Solar System', 'Name 8 planets in order from the sun. ''My Very Educated Mother Just Served Us Nachos.'' Scale comparison.', 8, '5–10 min', 'None', 'Name 8 planets in order from the sun. ''My Very Educated Mother Just Served Us Nachos.'' Scale comparison.'),
  ('angles-introduction-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Angles Introduction', 'Right angle (90°): spot them in the room. Acute and obtuse angles. Geometry vocabulary before protractors.', 7, '5–8 min', 'None', 'Right angle (90°): spot them in the room. Acute and obtuse angles. Geometry vocabulary before protractors.'),
  ('biography-reading-and-discussion-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Biography Reading and Discussion', 'Read a short biography of a historical figure. ''What challenges did they face? What can we learn from them?''', 13, '10–15 min', 'Short biography', 'Read a short biography of a historical figure. ''What challenges did they face? What can we learn from them?'''),
  ('manage-multiple-responsibilities-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Manage Multiple Responsibilities', 'Handle 3 concurrent responsibilities: homework, chore, and personal care. Executive function: prioritise and sequence.', null, 'Ongoing', 'None', 'Handle 3 concurrent responsibilities: homework, chore, and personal care. Executive function: prioritise and sequence.'),
  ('resolve-conflict-without-adult-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Resolve Conflict Without Adult', 'When a peer conflict arises at home, attempt resolution without adult mediation. Debrief after: what did you try?', null, 'Ongoing', 'None', 'When a peer conflict arises at home, attempt resolution without adult mediation. Debrief after: what did you try?'),
  ('understand-another-s-perspective-fully-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Understand Another''s Perspective Fully', 'Tell me the whole story from their point of view -- not yours.'' Full perspective-taking, not just awareness of difference.', 8, '5–10 min', 'None', 'Tell me the whole story from their point of view -- not yours.'' Full perspective-taking, not just awareness of difference.'),
  ('build-resilience-from-failure-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Build Resilience from Failure', 'After a genuine failure: ''What happened? What did you learn? What will you try next time?'' Growth mindset practice.', 8, '5–10 min', 'None', 'After a genuine failure: ''What happened? What did you learn? What will you try next time?'' Growth mindset practice.'),
  ('manage-screen-time-self-regulated-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Manage Screen Time (Self-Regulated)', 'Set own screen time limits for a week; track usage; review: ''Did I stick to it? How did it feel?'' Self-regulation of technology.', null, 'Ongoing', 'None', 'Set own screen time limits for a week; track usage; review: ''Did I stick to it? How did it feel?'' Self-regulation of technology.'),
  ('understand-misinformation-basics-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Understand Misinformation Basics', 'How do you know that''s true? Where did you hear it? Is it always the whole story?'' Media literacy beginning.', 8, '5–10 min', 'News item or claim to examine', 'How do you know that''s true? Where did you hear it? Is it always the whole story?'' Media literacy beginning.'),
  ('astronomy-observation-journal-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Astronomy Observation Journal', 'Observe and draw the moon every 3 nights for a month. Full lunar cycle observation builds pattern recognition.', 8, '5–10 min', 'Drawing journal + pen', 'Observe and draw the moon every 3 nights for a month. Full lunar cycle observation builds pattern recognition.'),
  ('build-a-compost-bin-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Build a Compost Bin', 'Start a small compost from kitchen waste. Biology: decomposition, food webs, natural cycles.', null, 'Ongoing', 'Container, kitchen waste', 'Start a small compost from kitchen waste. Biology: decomposition, food webs, natural cycles.'),
  ('photography-project-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Photography Project', 'Use a phone or camera: take 10 photos with a chosen theme. Composition awareness + visual literacy.', 13, '10–15 min', 'Camera or phone', 'Use a phone or camera: take 10 photos with a chosen theme. Composition awareness + visual literacy.'),
  ('fermentation-observation-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Fermentation Observation', 'Mix yeast + sugar + warm water and observe bubbles. Microorganism activity as a science phenomenon.', 13, '10–15 min', 'Yeast, sugar, warm water, balloon', 'Mix yeast + sugar + warm water and observe bubbles. Microorganism activity as a science phenomenon.'),
  ('architecture-observation-walk-y5_0', 'cognitive'::domain, 'y5_0'::age_band, 'Architecture Observation Walk', 'Walk around local buildings: note arches, columns, windows, patterns. Built environment as sensory + aesthetic exploration.', 25, '20–30 min', 'None (outdoors)', 'Walk around local buildings: note arches, columns, windows, patterns. Built environment as sensory + aesthetic exploration.'),
  ('plan-and-cook-a-meal-menu-to-table-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Plan and Cook a Meal (Menu to Table)', 'Choose a recipe, write a shopping list, shop with adult, prepare and serve. Full food chain participation.', 38, '30–45 min', 'Ingredients, kitchen tools', 'Choose a recipe, write a shopping list, shop with adult, prepare and serve. Full food chain participation.'),
  ('navigate-independently-short-trip-y5_0', 'social_emotional'::domain, 'y5_0'::age_band, 'Navigate Independently (Short Trip)', 'Walk or cycle a known short route (park and back) independently or with peers -- no adult accompaniment.', 18, '15–20 min', 'None', 'Walk or cycle a known short route (park and back) independently or with peers -- no adult accompaniment.'),
  ('orienteering-garden-or-park-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Orienteering (Garden or Park)', 'Follow a simple map to find 5 hidden points in a garden or park. Navigation + map reading + fitness combined.', 25, '20–30 min', 'Hand-drawn map, marked points', 'Follow a simple map to find 5 hidden points in a garden or park. Navigation + map reading + fitness combined.'),
  ('batting-cricket-or-rounders-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Batting (Cricket or Rounders)', 'Hit a bowled or tossed ball with a bat. Tracking, timing, and swing plane all coordinating.', 13, '10–15 min', 'Bat and ball', 'Hit a bowled or tossed ball with a bat. Tracking, timing, and swing plane all coordinating.'),
  ('swim-backstroke-10m-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Swim Backstroke 10m', 'Backstroke: arms alternating overhead while kicking on back. Different body position = new spatial challenge.', 18, '15–20 min', 'Swimming pool', 'Backstroke: arms alternating overhead while kicking on back. Different body position = new spatial challenge.'),
  ('handstand-wall-assisted-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Handstand (Wall-Assisted)', 'Kick up to handstand against a wall; hold 3 seconds. Full inversion + weight-bearing through arms.', 8, '5–10 min', 'Clear wall', 'Kick up to handstand against a wall; hold 3 seconds. Full inversion + weight-bearing through arms.'),
  ('sprint-start-3-point-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Sprint Start (3-Point)', 'Start from a 3-point stance on signal. Sports start = explosive reaction + acceleration + body position combined.', 7, '5–8 min', 'Open space', 'Start from a 3-point stance on signal. Sports start = explosive reaction + acceleration + body position combined.'),
  ('bicycle-hill-climb-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Bicycle — Hill Climb', 'Ride up a gentle slope. Hill cycling requires gear shifting (if applicable), sustained effort, and balance at low speed.', 13, '10–15 min', 'Bicycle + hill', 'Ride up a gentle slope. Hill cycling requires gear shifting (if applicable), sustained effort, and balance at low speed.'),
  ('ball-control-feet-and-knees-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Ball Control (Feet and Knees)', 'Keep a football in the air using feet, knees, chest. Juggling control is advanced ball mastery.', 13, '10–15 min', 'Football or large ball', 'Keep a football in the air using feet, knees, chest. Juggling control is advanced ball mastery.'),
  ('play-tag-variant-freeze-tag-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Play Tag (Variant: Freeze Tag)', 'Freeze tag: tag someone, they freeze until unfrozen by another. Spatial awareness + social coordination + motor speed.', 13, '10–15 min', 'Open space + players', 'Freeze tag: tag someone, they freeze until unfrozen by another. Spatial awareness + social coordination + motor speed.'),
  ('write-a-story-800-words-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Write a Story (800 Words)', '800-word story with dialogue, descriptive language, and a clear story arc. Word count should be a target, not a ceiling.', 25, '20–30 min', 'Pencil and paper', '800-word story with dialogue, descriptive language, and a clear story arc. Word count should be a target, not a ceiling.'),
  ('make-a-zine-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Make a Zine', 'Fold a single A4 sheet into an 8-page booklet. Create a mini-magazine: articles, illustrations, cover, contents page.', 18, '15–20 min', 'A4 paper, scissors, pens', 'Fold a single A4 sheet into an 8-page booklet. Create a mini-magazine: articles, illustrations, cover, contents page.'),
  ('scale-drawing-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Scale Drawing', 'Draw a room to scale (1 cm = 50 cm). Measurement + proportion + spatial representation.', 18, '15–20 min', 'Ruler, pencil, graph paper', 'Draw a room to scale (1 cm = 50 cm). Measurement + proportion + spatial representation.'),
  ('complex-origami-10-folds-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Complex Origami (10+ Folds)', 'Origami crane or frog: 10+ folds requiring spatial planning and precise crease alignment.', 25, '20–30 min', 'Square paper', 'Origami crane or frog: 10+ folds requiring spatial planning and precise crease alignment.'),
  ('build-a-simple-catapult-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Build a Simple Catapult', 'Craft sticks, rubber bands, plastic spoon. Load, aim, fire. Engineering: force, trajectory, adjustment.', 18, '15–20 min', 'Craft sticks, rubber bands, spoon, tape', 'Craft sticks, rubber bands, plastic spoon. Load, aim, fire. Engineering: force, trajectory, adjustment.'),
  ('batik-simple-wax-resist-y5_3', 'motor'::domain, 'y5_3'::age_band, 'Batik (Simple Wax Resist)', 'Apply wax to fabric, dye it, remove wax. The resist print is unpredictable and beautiful. Textile science.', 25, '20–30 min', 'Candle wax, fabric, dye (food colouring), hot water', 'Apply wax to fabric, dye it, remove wax. The resist print is unpredictable and beautiful. Textile science.'),
  ('read-novel-300-pages-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Read Novel (300+ Pages)', 'A 300-page novel at reading level. Complex character development + sustained reading stamina + literary discussion.', 25, '20–30 min', 'Age-appropriate novel', 'A 300-page novel at reading level. Complex character development + sustained reading stamina + literary discussion.'),
  ('write-a-book-report-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Write a Book Report', 'Summarise: title, author, main characters, plot, your opinion and why. Non-fiction analytical writing about fiction.', 18, '15–20 min', 'Novel read + pencil and paper', 'Summarise: title, author, main characters, plot, your opinion and why. Non-fiction analytical writing about fiction.'),
  ('vocabulary-word-roots-latin-greek-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Vocabulary: Word Roots (Latin/Greek)', 'Bio = life, graph = write, tele = far, phon = sound. Root knowledge unlocks unknown word meanings. 5 roots per week.', 8, '5–10 min', 'None', 'Bio = life, graph = write, tele = far, phon = sound. Root knowledge unlocks unknown word meanings. 5 roots per week.'),
  ('debate-formal-structure-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Debate (Formal Structure)', '2-minute opening argument, 1-minute rebuttal, 1-minute closing. Formal debate structure teaches evidence and logic.', 18, '15–20 min', 'None', '2-minute opening argument, 1-minute rebuttal, 1-minute closing. Formal debate structure teaches evidence and logic.'),
  ('write-a-script-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Write a Script', 'Write a short play: character list, scene directions, dialogue. Script format is a distinct text type.', 18, '15–20 min', 'Pencil and paper', 'Write a short play: character list, scene directions, dialogue. Script format is a distinct text type.'),
  ('analyse-a-poem-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Analyse a Poem', 'Read a poem: identify the theme, one poetic device, and what line you found most powerful and why.', 13, '10–15 min', 'Poem (any short poem)', 'Read a poem: identify the theme, one poetic device, and what line you found most powerful and why.'),
  ('edit-own-writing-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Edit Own Writing', 'Write a paragraph, leave it, return next day, and improve it. Editing = reading critically and rewriting, not just correcting.', 18, '15–20 min', 'Pencil and paper', 'Write a paragraph, leave it, return next day, and improve it. Editing = reading critically and rewriting, not just correcting.'),
  ('persuasive-speech-3-minutes-y5_3', 'communication'::domain, 'y5_3'::age_band, 'Persuasive Speech (3 Minutes)', 'Prepare and deliver a 3-minute persuasive speech on a chosen topic. Introduction, 3 arguments, conclusion, call to action.', 25, '20–30 min', 'None', 'Prepare and deliver a 3-minute persuasive speech on a chosen topic. Introduction, 3 arguments, conclusion, call to action.'),
  ('times-tables-9-10-11-12-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Times Tables (9, 10, 11, 12)', 'Complete the 12x12 multiplication grid. All tables known reliably — begin exploring patterns (9x = digit sum is 9).', 8, '5–10 min', 'Pencil and paper', 'Complete the 12x12 multiplication grid. All tables known reliably — begin exploring patterns (9x = digit sum is 9).'),
  ('long-division-2-digit-dividend-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Long Division (2-Digit Dividend)', '48 ÷ 4 = 12. The conceptual step: how many groups of 4 in 48? Grouping before the algorithm.', 8, '5–10 min', 'Pencil and paper', '48 ÷ 4 = 12. The conceptual step: how many groups of 4 in 48? Grouping before the algorithm.'),
  ('decimals-introduction-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Decimals Introduction', 'Tenths: 0.1, 0.5, 0.7. A decimal is a fraction with 10 in the denominator. Concrete representation with 10 blocks.', 8, '5–10 min', '10 uniform objects + whole', 'Tenths: 0.1, 0.5, 0.7. A decimal is a fraction with 10 in the denominator. Concrete representation with 10 blocks.'),
  ('classify-rocks-3-types-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Classify Rocks (3 Types)', 'Igneous, sedimentary, metamorphic. Find 3 rock types outdoors; identify key features of each.', 13, '10–15 min', 'Rock samples (collected outdoors)', 'Igneous, sedimentary, metamorphic. Find 3 rock types outdoors; identify key features of each.'),
  ('history-timeline-project-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'History: Timeline Project', 'Create a timeline of a chosen period with 8+ dated events. Chronological thinking + historical knowledge combined.', 18, '15–20 min', 'Paper, ruler, reference book', 'Create a timeline of a chosen period with 8+ dated events. Chronological thinking + historical knowledge combined.'),
  ('logic-puzzles-grid-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Logic Puzzles (Grid)', 'A 4x4 logic grid puzzle: deduce which person has which attribute. Systematic elimination = logical reasoning.', 18, '15–20 min', 'Logic puzzle (printable or drawn)', 'A 4x4 logic grid puzzle: deduce which person has which attribute. Systematic elimination = logical reasoning.'),
  ('manage-time-for-a-project-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Manage Time for a Project', 'Given a 5-day project deadline, plan the work across 5 days without being told when to do each step.', null, 'Ongoing', 'None', 'Given a 5-day project deadline, plan the work across 5 days without being told when to do each step.'),
  ('give-constructive-feedback-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Give Constructive Feedback', 'I liked… but one thing that could be even better is…'' Structured feedback that''s honest AND kind.', 8, '5–10 min', 'None', 'I liked… but one thing that could be even better is…'' Structured feedback that''s honest AND kind.'),
  ('handle-criticism-gracefully-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Handle Criticism Gracefully', 'When given negative feedback: listen fully, ask one question, thank them. Receiving criticism is a learnable skill.', null, 'Ongoing', 'None', 'When given negative feedback: listen fully, ask one question, thank them. Receiving criticism is a learnable skill.'),
  ('advocate-for-someone-else-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Advocate for Someone Else', 'My friend was upset about what happened. I wanted to say something on their behalf.'' Ally behaviour.', null, 'Ongoing', 'None', 'My friend was upset about what happened. I wanted to say something on their behalf.'' Ally behaviour.'),
  ('peer-mediation-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Peer Mediation', 'Help two friends resolve a conflict they''re having. Third-party mediation requires neutrality and listening.', 13, '10–15 min', 'None', 'Help two friends resolve a conflict they''re having. Third-party mediation requires neutrality and listening.'),
  ('discuss-a-moral-dilemma-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Discuss a Moral Dilemma', 'If you found a wallet full of money with no ID, what would you do?'' Moral reasoning without a single right answer.', 8, '5–10 min', 'None', 'If you found a wallet full of money with no ID, what would you do?'' Moral reasoning without a single right answer.'),
  ('tie-dye-fold-and-bind-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Tie-Dye (Fold and Bind)', 'Rubber band a white cloth in patterns, submerge in colour (food dye). Pattern control + colour science + patience.', 25, '20–30 min', 'White fabric, rubber bands, food dye, water', 'Rubber band a white cloth in patterns, submerge in colour (food dye). Pattern control + colour science + patience.'),
  ('candle-making-supervised-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Candle-Making (Supervised)', 'Melt wax, pour into a mould, insert wick. Supervised heat + transformation science + fine motor.', 25, '20–30 min', 'Wax (old candles), wick, container', 'Melt wax, pour into a mould, insert wick. Supervised heat + transformation science + fine motor.'),
  ('build-a-periscope-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Build a Periscope', 'Mirrors at 45-degree angles in a tube: see around corners. Optics: angles of reflection.', 18, '15–20 min', 'Cardboard tube, two small mirrors, tape', 'Mirrors at 45-degree angles in a tube: see around corners. Optics: angles of reflection.'),
  ('clay-kiln-pit-fire-outdoors-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Clay Kiln Pit Fire (Outdoors)', 'Shape clay pots; fire them in a pit fire (with adult supervision). Ancient technology + science of ceramic transformation.', 38, '30–45 min', 'Air-dry clay, outdoor fire (supervised)', 'Shape clay pots; fire them in a pit fire (with adult supervision). Ancient technology + science of ceramic transformation.'),
  ('acoustic-science-string-phone-y5_3', 'cognitive'::domain, 'y5_3'::age_band, 'Acoustic Science (String Phone)', 'Two cups connected by a taut string. Sound travels through the string — demonstrate vibration as a medium of sound.', 13, '10–15 min', 'Two cups, string', 'Two cups connected by a taut string. Sound travels through the string — demonstrate vibration as a medium of sound.'),
  ('manage-own-study-schedule-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'Manage Own Study Schedule', 'Plan a weekly study schedule independently. What to revise, when, for how long. Executive function for academic contexts.', 13, '10–15 min', 'Paper + calendar', 'Plan a weekly study schedule independently. What to revise, when, for how long. Executive function for academic contexts.'),
  ('first-solo-public-transaction-y5_3', 'social_emotional'::domain, 'y5_3'::age_band, 'First Solo Public Transaction', 'Enter a shop, choose an item, pay, check change, thank the cashier — alone. Real-world social-financial independence.', 13, '10–15 min', 'Money for a small purchase', 'Enter a shop, choose an item, pay, check change, thank the cashier — alone. Real-world social-financial independence.'),
  ('badminton-basic-rallying-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Badminton (Basic Rallying)', 'Rally a shuttlecock back and forth. Eye-hand coordination + fast visual tracking + footwork combined.', 13, '10–15 min', 'Badminton rackets + shuttlecock (or improvised)', 'Rally a shuttlecock back and forth. Eye-hand coordination + fast visual tracking + footwork combined.'),
  ('handstand-walk-1-2-steps-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Handstand Walk (1–2 Steps)', 'From wall-handstand, try 1–2 hand-steps away from wall. Weight shift in full inversion = exceptional balance demand.', 7, '5–8 min', 'Clear wall', 'From wall-handstand, try 1–2 hand-steps away from wall. Weight shift in full inversion = exceptional balance demand.'),
  ('swim-50-metres-various-strokes-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Swim 50 Metres (Various Strokes)', '50-metre swim using 2 different strokes. Stroke transition demonstrates fluid motor switching.', 18, '15–20 min', 'Swimming pool', '50-metre swim using 2 different strokes. Stroke transition demonstrates fluid motor switching.'),
  ('bicycle-long-distance-5-km-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Bicycle Long Distance (5 km)', 'Cycle 5 km on a chosen route. Stamina, navigation, and sustained attention across 20–30 minutes.', 25, '20–30 min', 'Bicycle', 'Cycle 5 km on a chosen route. Stamina, navigation, and sustained attention across 20–30 minutes.'),
  ('cricket-bowling-basic-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Cricket Bowling (Basic)', 'Overarm bowling at a target (stump or cone). Run-up + release + follow-through = full-body coordination in sequence.', 13, '10–15 min', 'Ball + target', 'Overarm bowling at a target (stump or cone). Run-up + release + follow-through = full-body coordination in sequence.'),
  ('gymnastics-beam-low-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Gymnastics Beam (Low)', 'Walk, turn, pose on a low beam. Balance in one plane while planning movement = gymnastic spatial reasoning.', 13, '10–15 min', 'Low beam or plank (10 cm high)', 'Walk, turn, pose on a low beam. Balance in one plane while planning movement = gymnastic spatial reasoning.'),
  ('archery-simple-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Archery (Simple)', 'Simple rubber-band bow and arrow or a commercial safety set. Aim, hold breath, release. Fine + gross combined.', 13, '10–15 min', 'Simple bow and arrows (safe set)', 'Simple rubber-band bow and arrow or a commercial safety set. Aim, hold breath, release. Fine + gross combined.'),
  ('frisbee-accurate-throw-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Frisbee Accurate Throw', 'Throw a frisbee so it lands in a target area 10 m away. Wrist flip + horizontal plane release = distinct motor skill.', 13, '10–15 min', 'Frisbee', 'Throw a frisbee so it lands in a target area 10 m away. Wrist flip + horizontal plane release = distinct motor skill.'),
  ('write-a-short-story-collection-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Write a Short Story Collection', '3 short stories (200 words each) with a connecting theme. Organisation + variety within a unified project.', 25, '20–30 min', 'Pencil and paper', '3 short stories (200 words each) with a connecting theme. Organisation + variety within a unified project.'),
  ('macrame-simple-knots-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Macrame (Simple Knots)', 'Square knot and half-hitch repeatedly to make a small wall piece or bracelet. Pattern knotting = fine motor + sequencing.', 25, '20–30 min', 'Macrame cord or thick string', 'Square knot and half-hitch repeatedly to make a small wall piece or bracelet. Pattern knotting = fine motor + sequencing.'),
  ('perspective-drawing-vanishing-point-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Perspective Drawing (Vanishing Point)', 'One-point perspective: a road or corridor disappearing to a single point on the horizon. Geometry through art.', 18, '15–20 min', 'Pencil, ruler, paper', 'One-point perspective: a road or corridor disappearing to a single point on the horizon. Geometry through art.'),
  ('build-a-hydraulic-arm-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Build a Hydraulic Arm', 'Syringes filled with water and connected by tubing. Hydraulic pressure lifts a load. Engineering + fluid physics.', 25, '20–30 min', 'Syringes, tubing, card, tape', 'Syringes filled with water and connected by tubing. Hydraulic pressure lifts a load. Engineering + fluid physics.'),
  ('scratch-coding-first-project-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Scratch Coding (First Project)', 'Program a character to move, make a sound, and respond to a key press. Three functions in one project = logic thinking.', 18, '15–20 min', 'Computer with Scratch (scratch.mit.edu)', 'Program a character to move, make a sound, and respond to a key press. Three functions in one project = logic thinking.'),
  ('print-making-lino-cut-simple-y5_6', 'motor'::domain, 'y5_6'::age_band, 'Print-Making (Lino Cut Simple)', 'Carve a simple design into a soft block and print. Carving subtracts; printing reveals — two-stage craft thinking.', 25, '20–30 min', 'Soft lino or polystyrene, blunt carving tool, paint', 'Carve a simple design into a soft block and print. Carving subtracts; printing reveals — two-stage craft thinking.'),
  ('read-a-novel-series-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Read a Novel Series', 'Two books in a series. Tracking character development across books = long-form narrative memory.', 25, '20–30 min', 'Novel series (2 books)', 'Two books in a series. Tracking character development across books = long-form narrative memory.'),
  ('write-a-scene-from-another-perspective-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Write a Scene from Another Perspective', 'Retell a chapter from a book from a different character''s point of view. Perspective-taking through creative writing.', 18, '15–20 min', 'Pencil and paper + familiar book', 'Retell a chapter from a book from a different character''s point of view. Perspective-taking through creative writing.'),
  ('homophone-and-homonym-work-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Homophone and Homonym Work', 'Their/there/they''re, to/too/two, affect/effect. Context determines the correct form. Language precision.', 8, '5–10 min', 'None', 'Their/there/they''re, to/too/two, affect/effect. Context determines the correct form. Language precision.'),
  ('interview-and-transcribe-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Interview and Transcribe', 'Interview a family member for 5 minutes; transcribe key quotes. Journalism skill: listening + note-taking + selection.', 18, '15–20 min', 'Paper for notes or recording device', 'Interview a family member for 5 minutes; transcribe key quotes. Journalism skill: listening + note-taking + selection.'),
  ('read-and-review-a-film-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Read and Review a Film', 'Watch a film; write a 200-word review: plot summary, best element, weakest element, rating. Critical media literacy.', 18, '15–20 min', 'Paper and pencil', 'Watch a film; write a 200-word review: plot summary, best element, weakest element, rating. Critical media literacy.'),
  ('word-etymology-project-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Word Etymology Project', 'Choose 5 unusual words and find their origins. Etymology shows language as a living, evolving system.', 13, '10–15 min', 'Dictionary or etymology book', 'Choose 5 unusual words and find their origins. Etymology shows language as a living, evolving system.'),
  ('write-an-acrostic-poem-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Write an Acrostic Poem', 'Write a poem where the first letter of each line spells a word. Constraint-based creativity = high linguistic challenge.', 13, '10–15 min', 'Pencil and paper', 'Write a poem where the first letter of each line spells a word. Constraint-based creativity = high linguistic challenge.'),
  ('comprehension-of-inference-y5_6', 'communication'::domain, 'y5_6'::age_band, 'Comprehension of Inference', 'Read a passage and answer: ''The text says X. What does that suggest about Y?'' Implicit meaning = deep comprehension.', 13, '10–15 min', 'Any passage with inferrable subtext', 'Read a passage and answer: ''The text says X. What does that suggest about Y?'' Implicit meaning = deep comprehension.'),
  ('percentages-introduction-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Percentages (Introduction)', '50% = half. 25% = quarter. 10% = one tenth. Percentage as a fraction of 100 — connect to known fraction knowledge.', 8, '5–10 min', 'Objects to split into 100 or 10', '50% = half. 25% = quarter. 10% = one tenth. Percentage as a fraction of 100 — connect to known fraction knowledge.'),
  ('negative-numbers-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Negative Numbers', 'Numbers below zero: temperature, floors below ground, money owed. Number line extended below zero.', 7, '5–8 min', 'Extended number line drawn on paper', 'Numbers below zero: temperature, floors below ground, money owed. Number line extended below zero.'),
  ('area-of-rectangle-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Area of Rectangle', 'Length × width. Find the area of 5 household objects. Area as ''how many squares fill this shape.''', 8, '5–10 min', 'Ruler, paper for recording', 'Length × width. Find the area of 5 household objects. Area as ''how many squares fill this shape.'''),
  ('electricity-and-magnetism-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Electricity and Magnetism', 'Electromagnet: coil wire around a nail + battery = magnet. What does it attract? Science + engineering combined.', 18, '15–20 min', 'Wire, nail, battery', 'Electromagnet: coil wire around a nail + battery = magnet. What does it attract? Science + engineering combined.'),
  ('human-body-systems-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Human Body Systems', 'Skeleton, muscles, heart, lungs. Draw and label each system. How do systems work together?', 13, '10–15 min', 'Paper and coloured pens', 'Skeleton, muscles, heart, lungs. Draw and label each system. How do systems work together?'),
  ('probability-simple-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Probability (Simple)', 'Flip a coin 20 times: predict, then compare results. Experimental probability vs theoretical probability.', 13, '10–15 min', 'Coin + tally chart', 'Flip a coin 20 times: predict, then compare results. Experimental probability vs theoretical probability.'),
  ('recognise-unhealthy-relationships-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Recognise Unhealthy Relationships', 'What would make a friendship unhealthy? What would you do if that happened?'' Protective relationship literacy.', 13, '10–15 min', 'None', 'What would make a friendship unhealthy? What would you do if that happened?'' Protective relationship literacy.'),
  ('practice-saying-no-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Practice Saying No', 'Role-play scenarios where saying no is the right answer. ''No thank you'', ''I don''t want to do that'', ''I''m leaving now.''', 8, '5–10 min', 'None', 'Role-play scenarios where saying no is the right answer. ''No thank you'', ''I don''t want to do that'', ''I''m leaving now.'''),
  ('manage-academic-pressure-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Manage Academic Pressure', 'What does it feel like when you''re worried about doing badly? What helps?'' Anxiety about performance is real and needs a name.', 8, '5–10 min', 'None', 'What does it feel like when you''re worried about doing badly? What helps?'' Anxiety about performance is real and needs a name.'),
  ('digital-empathy-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Digital Empathy', 'Would you say this in person? How might they feel reading it?'' Online communication carries the same emotional weight.', 8, '5–10 min', 'None', 'Would you say this in person? How might they feel reading it?'' Online communication carries the same emotional weight.'),
  ('gratitude-journal-daily-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Gratitude Journal (Daily)', 'Write or draw 3 things you''re grateful for, every day for 2 weeks. Sustained gratitude practice changes mood baseline.', 4, '3–5 min', 'Journal + pencil', 'Write or draw 3 things you''re grateful for, every day for 2 weeks. Sustained gratitude practice changes mood baseline.'),
  ('cultural-exchange-meal-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Cultural Exchange Meal', 'Cook and eat a meal from a culture your family isn''t from. Research the dish + cooking + context conversation.', 38, '30–45 min', 'Ingredients for chosen recipe', 'Cook and eat a meal from a culture your family isn''t from. Research the dish + cooking + context conversation.'),
  ('optical-illusion-art-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Optical Illusion Art', 'Draw Escher-inspired impossible shapes or trompe l''oeil. Visual perception + spatial reasoning + fine motor combined.', 25, '20–30 min', 'Pencil, ruler, paper', 'Draw Escher-inspired impossible shapes or trompe l''oeil. Visual perception + spatial reasoning + fine motor combined.'),
  ('fossil-making-clay-impression-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Fossil Making (Clay Impression)', 'Press shells, leaves, or bones into clay; let dry. The impression is exactly how real fossils form. Palaeontology concept.', 18, '15–20 min', 'Clay, shells or leaves', 'Press shells, leaves, or bones into clay; let dry. The impression is exactly how real fossils form. Palaeontology concept.'),
  ('make-a-weather-station-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Make a Weather Station', 'Thermometer, rain gauge (marked container), wind direction vane (card + pin). Record daily for 2 weeks.', 25, '20–30 min', 'Containers, ruler, card, pin', 'Thermometer, rain gauge (marked container), wind direction vane (card + pin). Record daily for 2 weeks.'),
  ('sound-science-frequency-and-pitch-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Sound Science (Frequency and Pitch)', 'Partially fill glasses with water at different levels; tap each. More water = lower pitch. Frequency + resonance explained.', 13, '10–15 min', 'Glasses, water, spoon', 'Partially fill glasses with water at different levels; tap each. More water = lower pitch. Frequency + resonance explained.'),
  ('dissect-a-squid-or-chicken-wing-y5_6', 'cognitive'::domain, 'y5_6'::age_band, 'Dissect a Squid or Chicken Wing', 'Supervised dissection of a squid (from market) or chicken wing. Identify tendons, cartilage, muscle. Real biology.', 18, '15–20 min', 'Squid or chicken wing, disposable gloves', 'Supervised dissection of a squid (from market) or chicken wing. Identify tendons, cartilage, muscle. Real biology.'),
  ('plan-a-fundraiser-concept-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Plan a Fundraiser (Concept)', 'Choose a cause; plan a simple fundraiser: what, for whom, how much to raise, how to tell people. Civic planning.', 18, '15–20 min', 'Paper for planning', 'Choose a cause; plan a simple fundraiser: what, for whom, how much to raise, how to tell people. Civic planning.'),
  ('travel-independently-short-route-y5_6', 'social_emotional'::domain, 'y5_6'::age_band, 'Travel Independently (Short Route)', 'Public transport or walk for a familiar route without adult. Route knowledge + safety + agency growing together.', 18, '15–20 min', 'Transport money if needed', 'Public transport or walk for a familiar route without adult. Route knowledge + safety + agency growing together.'),
  ('football-positional-play-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Football (Positional Play)', 'Understand and play a position in a simple football match. Reading the game spatially is as important as individual skill.', 25, '20–30 min', 'Football + players', 'Understand and play a position in a simple football match. Reading the game spatially is as important as individual skill.'),
  ('swimming-race-competitive-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Swimming Race (Competitive)', 'Race against another person or own previous time. Performance awareness + competitive experience in a safe context.', 18, '15–20 min', 'Swimming pool', 'Race against another person or own previous time. Performance awareness + competitive experience in a safe context.'),
  ('bicycle-navigation-2-km-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Bicycle Navigation (2 km)', 'Navigate a 2-km route from memory or a simple map, independently or with a peer.', 18, '15–20 min', 'Bicycle + route map', 'Navigate a 2-km route from memory or a simple map, independently or with a peer.'),
  ('rock-climbing-top-rope-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Rock Climbing (Top-Rope)', 'Supervised rock climbing on a wall or crag. Reading the route + executing the movement + trusting the equipment.', 25, '20–30 min', 'Climbing wall + instructor', 'Supervised rock climbing on a wall or crag. Reading the route + executing the movement + trusting the equipment.'),
  ('trampoline-seat-drop-back-drop-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Trampoline (Seat Drop, Back Drop)', 'Seat drop and back drop on a trampoline (supervised). Full inversion trust + controlled landing on novel body part.', 13, '10–15 min', 'Trampoline (supervised)', 'Seat drop and back drop on a trampoline (supervised). Full inversion trust + controlled landing on novel body part.'),
  ('tennis-forehand-and-backhand-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Tennis (Forehand and Backhand)', 'Rally with forehand and backhand groundstrokes. Switching grip and swing direction is a bilateral motor distinction.', 13, '10–15 min', 'Tennis racket and ball (or improvised)', 'Rally with forehand and backhand groundstrokes. Switching grip and swing direction is a bilateral motor distinction.'),
  ('sprint-technique-full-sprint-mechanics-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Sprint Technique (Full Sprint Mechanics)', 'Arms, legs, lean, breathing — all coordinated in a maximal effort sprint. Physical literacy = understanding your own body.', 8, '5–10 min', 'Open space', 'Arms, legs, lean, breathing — all coordinated in a maximal effort sprint. Physical literacy = understanding your own body.'),
  ('cricket-batting-against-moving-ball-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Cricket Batting (Against Moving Ball)', 'Bat against a bowled delivery with proper stance, backlift, and follow-through.', 13, '10–15 min', 'Cricket bat and ball', 'Bat against a bowled delivery with proper stance, backlift, and follow-through.'),
  ('write-a-personal-essay-i-believe-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Write a Personal Essay (I Believe...)', 'I believe that…'' — 500-word personal essay arguing a position from own experience. Opinion + narrative combined.', 25, '20–30 min', 'Pencil and paper', 'I believe that…'' — 500-word personal essay arguing a position from own experience. Opinion + narrative combined.'),
  ('woodworking-simple-joint-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Woodworking (Simple Joint)', 'Under supervision: saw, sand, and glue or nail a simple joint. Real tool use + material understanding.', 25, '20–30 min', 'Soft wood, hand saw, sandpaper, nails or glue', 'Under supervision: saw, sand, and glue or nail a simple joint. Real tool use + material understanding.'),
  ('make-an-animated-flip-book-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Make an Animated Flip Book', 'Draw 30 frames of a moving image. Animation principles: timing, squash, stretch, arcs.', 18, '15–20 min', 'Blank booklet or stapled paper + pencil', 'Draw 30 frames of a moving image. Animation principles: timing, squash, stretch, arcs.'),
  ('sew-a-simple-cushion-cover-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Sew a Simple Cushion Cover', 'Measure, cut, pin, sew three sides, stuff, sew fourth side. A complete sewing project from start to finish.', 25, '20–30 min', 'Fabric, needle, thread, stuffing', 'Measure, cut, pin, sew three sides, stuff, sew fourth side. A complete sewing project from start to finish.'),
  ('programme-a-simple-app-scratch-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Programme a Simple App (Scratch)', 'A fully functional quiz or animation with at least 3 scenes and user input. Logic, sequence, and debugging combined.', 25, '20–30 min', 'Computer with Scratch', 'A fully functional quiz or animation with at least 3 scenes and user input. Logic, sequence, and debugging combined.'),
  ('cast-plaster-into-mould-y5_9', 'motor'::domain, 'y5_9'::age_band, 'Cast Plaster into Mould', 'Pour plaster into a mould; wait; remove. Casting + material science: liquid becomes solid as crystals form.', 18, '15–20 min', 'Plaster of Paris, mould (clay or plastic)', 'Pour plaster into a mould; wait; remove. Casting + material science: liquid becomes solid as crystals form.'),
  ('read-a-classic-novel-adapted-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Read a Classic Novel (Adapted)', 'Adapted classic: Treasure Island, Alice in Wonderland, 20,000 Leagues. Literature with historical and cultural context.', 25, '20–30 min', 'Adapted classic novel', 'Adapted classic: Treasure Island, Alice in Wonderland, 20,000 Leagues. Literature with historical and cultural context.'),
  ('write-a-biography-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Write a Biography', 'Write a 400-word biography of a person they admire. Chronological structure + factual writing + sourcing.', 25, '20–30 min', 'Reference material + pencil and paper', 'Write a 400-word biography of a person they admire. Chronological structure + factual writing + sourcing.'),
  ('pr-cis-writing-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Précis Writing', 'Reduce a 200-word passage to 60 words, keeping all key points. Compression + selection = advanced literacy.', 18, '15–20 min', '200-word passage + pencil and paper', 'Reduce a 200-word passage to 60 words, keeping all key points. Compression + selection = advanced literacy.'),
  ('grammar-active-and-passive-voice-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Grammar: Active and Passive Voice', 'The dog bit the man'' vs ''The man was bitten by the dog.'' Transform 5 sentences between voices.', 8, '5–10 min', 'Printed sentences', 'The dog bit the man'' vs ''The man was bitten by the dog.'' Transform 5 sentences between voices.'),
  ('read-poetry-aloud-performance-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Read Poetry Aloud (Performance)', 'Memorise a short poem and perform it with expression to an audience. Oral language + memory + performance.', 13, '10–15 min', 'Short poem', 'Memorise a short poem and perform it with expression to an audience. Oral language + memory + performance.'),
  ('analyse-a-news-article-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Analyse a News Article', 'Author, publication, date, claim, evidence given, potential bias. Critical news literacy: 5-question analysis.', 13, '10–15 min', 'Current news article', 'Author, publication, date, claim, evidence given, potential bias. Critical news literacy: 5-question analysis.'),
  ('write-a-story-from-a-prompt-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Write a Story from a Prompt', 'Open prompt: ''The door appeared overnight where there had never been a door.'' Free creative writing from constraint.', 18, '15–20 min', 'Pencil and paper', 'Open prompt: ''The door appeared overnight where there had never been a door.'' Free creative writing from constraint.'),
  ('homage-writing-y5_9', 'communication'::domain, 'y5_9'::age_band, 'Homage Writing', 'Write a story in the style of a favourite author. Style analysis + imitation = advanced literary understanding.', 18, '15–20 min', 'Pencil and paper + chosen author''s book', 'Write a story in the style of a favourite author. Style analysis + imitation = advanced literary understanding.'),
  ('long-division-3-digit-dividend-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Long Division (3-Digit Dividend)', '256 ÷ 8 = 32. Place-value understanding applied to division. Estimate first, then calculate, then check.', 8, '5–10 min', 'Pencil and paper', '256 ÷ 8 = 32. Place-value understanding applied to division. Estimate first, then calculate, then check.'),
  ('algebra-introduction-missing-number-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Algebra Introduction (Missing Number)', '4 + x = 9. What is x? Unknown number in a known relationship. Algebra as a ''find the missing piece'' problem.', 8, '5–10 min', 'Pencil and paper', '4 + x = 9. What is x? Unknown number in a known relationship. Algebra as a ''find the missing piece'' problem.'),
  ('geometry-area-and-perimeter-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Geometry: Area and Perimeter', 'Both for the same shape. Why are they different? Distinguish the two concepts concretely before abstractly.', 8, '5–10 min', 'Ruler and simple shapes drawn on paper', 'Both for the same shape. Why are they different? Distinguish the two concepts concretely before abstractly.'),
  ('human-geography-population-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Human Geography (Population)', 'Why do most people live near rivers and coasts? Map evidence + reasoning about human patterns.', 13, '10–15 min', 'Simple world map', 'Why do most people live near rivers and coasts? Map evidence + reasoning about human patterns.'),
  ('chemical-change-vs-physical-change-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Chemical Change vs Physical Change', 'Burning = chemical. Cutting = physical. Test 5 household processes and classify. Observable evidence of change.', 13, '10–15 min', 'Candle, apple, water, paper', 'Burning = chemical. Cutting = physical. Test 5 household processes and classify. Observable evidence of change.'),
  ('hypothesis-and-test-scientific-method-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Hypothesis and Test (Scientific Method)', 'Write a formal hypothesis: ''I think X will happen because Y.'' Test it. Write results and conclusion. Science protocol.', 18, '15–20 min', 'Any testable household experiment', 'Write a formal hypothesis: ''I think X will happen because Y.'' Test it. Write results and conclusion. Science protocol.'),
  ('understand-social-norms-and-pressures-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Understand Social Norms and Pressures', 'What do you do when your friends want you to do something you''re uncomfortable with?'' Social pressure navigation.', 8, '5–10 min', 'None', 'What do you do when your friends want you to do something you''re uncomfortable with?'' Social pressure navigation.'),
  ('empathy-for-difference-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Empathy for Difference', 'Tell me about someone at school who is very different from you. What might their life be like?'' Imaginative empathy.', 8, '5–10 min', 'None', 'Tell me about someone at school who is very different from you. What might their life be like?'' Imaginative empathy.'),
  ('manage-own-mental-health-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Manage Own Mental Health', 'What are 3 things you do when you''re feeling low? What works best?'' Personal mental health toolkit building.', 8, '5–10 min', 'None', 'What are 3 things you do when you''re feeling low? What works best?'' Personal mental health toolkit building.'),
  ('understand-consent-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Understand Consent', 'What does it mean for something to be OK with everyone involved?'' Age-appropriate consent framing for all contexts.', 8, '5–10 min', 'None', 'What does it mean for something to be OK with everyone involved?'' Age-appropriate consent framing for all contexts.'),
  ('handle-exclusion-constructively-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Handle Exclusion Constructively', 'When you were left out, what did you do? What else could you have done?'' Exclusion is universal and manageable.', 8, '5–10 min', 'None', 'When you were left out, what did you do? What else could you have done?'' Exclusion is universal and manageable.'),
  ('be-the-honest-friend-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Be the Honest Friend', 'Would you tell your friend if they had spinach in their teeth? What about something bigger?'' Kindness + honesty.', 8, '5–10 min', 'None', 'Would you tell your friend if they had spinach in their teeth? What about something bigger?'' Kindness + honesty.'),
  ('astronomy-scale-model-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Astronomy: Scale Model', 'Build a scale model of the solar system outdoors. The distances are more powerful than any diagram. Science + awe.', 25, '20–30 min', 'Balls of varied sizes, outdoor space', 'Build a scale model of the solar system outdoors. The distances are more powerful than any diagram. Science + awe.'),
  ('brewing-kombucha-or-kefir-supervised-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Brewing Kombucha or Kefir (Supervised)', 'Fermented drink making. Living cultures + nutrition science + patience. Biology you can taste.', null, 'Ongoing', 'Starter culture, tea/milk, jar', 'Fermented drink making. Living cultures + nutrition science + patience. Biology you can taste.'),
  ('pressure-and-force-experiment-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Pressure and Force Experiment', 'Bed of nails principle: one nail vs many nails. Pressure = force/area. Demonstrate with a balloon on a nail board.', 13, '10–15 min', 'Balloons, nails in a board (adult-made)', 'Bed of nails principle: one nail vs many nails. Pressure = force/area. Demonstrate with a balloon on a nail board.'),
  ('dyeing-with-natural-plants-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Dyeing with Natural Plants', 'Onion skins, turmeric, woad. Plant-based dyes on fabric. Chemistry of natural colour in a sensory-rich process.', 25, '20–30 min', 'Onion skins/turmeric, fabric, water, pot', 'Onion skins, turmeric, woad. Plant-based dyes on fabric. Chemistry of natural colour in a sensory-rich process.'),
  ('micro-gardening-sprouts-y5_9', 'cognitive'::domain, 'y5_9'::age_band, 'Micro-Gardening (Sprouts)', 'Grow bean or lentil sprouts in a jar with mesh lid. Harvest in 3–5 days. Speed of growth makes observation immediate.', null, 'Ongoing', 'Jar, mesh lid, seeds (lentils or mung beans)', 'Grow bean or lentil sprouts in a jar with mesh lid. Harvest in 3–5 days. Speed of growth makes observation immediate.'),
  ('manage-own-calendar-for-a-week-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Manage Own Calendar for a Week', 'Write all commitments, deadlines, and personal time into a weekly planner independently.', 8, '5–10 min', 'Blank weekly planner', 'Write all commitments, deadlines, and personal time into a weekly planner independently.'),
  ('emergency-preparedness-y5_9', 'social_emotional'::domain, 'y5_9'::age_band, 'Emergency Preparedness', 'Know the emergency number (112 in India), when to call, what to say. Practise the call script with a parent.', 8, '5–10 min', 'None', 'Know the emergency number (112 in India), when to call, what to say. Practise the call script with a parent.'),
  ('organise-a-sports-game-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Organise a Sports Game', 'Plan a game for 4+ players: explain rules, assign roles, referee the first 5 minutes. Leadership + organisation.', 25, '20–30 min', 'Sports equipment of choice', 'Plan a game for 4+ players: explain rules, assign roles, referee the first 5 minutes. Leadership + organisation.'),
  ('swim-a-full-length-technique-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Swim a Full Length (Technique)', '25 m with correct technique: head position, arm pull, kick rhythm. Technical swimming, not just distance.', 18, '15–20 min', 'Swimming pool', '25 m with correct technique: head position, arm pull, kick rhythm. Technical swimming, not just distance.'),
  ('cycling-on-a-route-planning-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Cycling on a Route (Planning)', 'Plan a 5-km route, identify landmarks for navigation, execute it. Cartography + cycling + independence.', 25, '20–30 min', 'Bicycle + map (hand-drawn or printed)', 'Plan a 5-km route, identify landmarks for navigation, execute it. Cartography + cycling + independence.'),
  ('track-and-field-jumping-event-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Track and Field: Jumping Event', 'High jump (scissor technique) or long jump. Technique before distance — approach, take-off, landing.', 13, '10–15 min', 'Measuring tape + soft landing surface', 'High jump (scissor technique) or long jump. Technique before distance — approach, take-off, landing.'),
  ('skateboard-basic-tricks-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Skateboard Basic Tricks', 'Ollie attempt, kick turn, riding fakie. Skateboarding is a self-directed learning model: watch, try, fail, adjust.', 13, '10–15 min', 'Skateboard (supervised)', 'Ollie attempt, kick turn, riding fakie. Skateboarding is a self-directed learning model: watch, try, fail, adjust.'),
  ('martial-arts-basic-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Martial Arts (Basic)', 'Basic stance, block, strike — even in a single lesson or from a video. Discipline + body control + respect.', 18, '15–20 min', 'None (or video demonstration)', 'Basic stance, block, strike — even in a single lesson or from a video. Discipline + body control + respect.'),
  ('dance-choreograph-32-counts-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Dance: Choreograph 32 Counts', 'Choreograph a 32-count sequence to chosen music. Creative composition + timing + memory.', 18, '15–20 min', 'Music', 'Choreograph a 32-count sequence to chosen music. Creative composition + timing + memory.'),
  ('archery-aiming-and-consistency-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Archery (Aiming and Consistency)', '3 arrows at a target: how consistent is the grouping? Deliberate practice: aim for consistency before accuracy.', 13, '10–15 min', 'Simple bow and safe arrows + target', '3 arrows at a target: how consistent is the grouping? Deliberate practice: aim for consistency before accuracy.'),
  ('novel-first-draft-1000-words-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Novel (First Draft, 1000 Words)', 'Write the first 1000 words of a longer story. Sustaining a narrative over time without finishing it — beginning.', 25, '20–30 min', 'Pencil and paper', 'Write the first 1000 words of a longer story. Sustaining a narrative over time without finishing it — beginning.'),
  ('mosaic-tile-grouting-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Mosaic Tile Grouting', 'Place small tiles on cement board; apply and wipe grout. Real mosaic-making technique + sensory experience.', 25, '20–30 min', 'Tiles, adhesive, grout, board', 'Place small tiles on cement board; apply and wipe grout. Real mosaic-making technique + sensory experience.'),
  ('paper-airplanes-aerodynamics-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Paper Airplanes: Aerodynamics', 'Build 5 different designs and test each. Record flight time and distance. Which design flies furthest? Why?', 18, '15–20 min', 'Paper, pencil, tape measure', 'Build 5 different designs and test each. Record flight time and distance. Which design flies furthest? Why?'),
  ('sew-a-stuffed-animal-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Sew a Stuffed Animal', 'Design, cut, pin, sew, stuff, and close a small stuffed animal from scratch. Complete sewing project.', 25, '20–30 min', 'Fabric, needle, thread, stuffing, scissors', 'Design, cut, pin, sew, stuff, and close a small stuffed animal from scratch. Complete sewing project.'),
  ('digital-art-drawing-app-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Digital Art (Drawing App)', 'Create a scene or character in a drawing app. Digital tools have different affordances from analogue — explore them.', 18, '15–20 min', 'Tablet or phone + drawing app', 'Create a scene or character in a drawing app. Digital tools have different affordances from analogue — explore them.'),
  ('leather-tooling-bookmark-y6_0', 'motor'::domain, 'y6_0'::age_band, 'Leather Tooling (Bookmark)', 'Stamp a pattern into wet leather using a tool. Leatherwork is ancient, tactile, and produces lasting objects.', 25, '20–30 min', 'Leather offcut, tooling tools (or nail + hammer)', 'Stamp a pattern into wet leather using a tool. Leatherwork is ancient, tactile, and produces lasting objects.'),
  ('read-a-non-fiction-book-full-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Read a Non-Fiction Book (Full)', 'Full non-fiction book on a topic of choice. Note-taking while reading — extract key facts and questions.', 25, '20–30 min', 'Non-fiction book of choice', 'Full non-fiction book on a topic of choice. Note-taking while reading — extract key facts and questions.'),
  ('write-a-fairy-tale-with-subversion-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Write a Fairy Tale (With Subversion)', 'Traditional fairy tale with a twist: the villain wins, the hero fails, the ending is ambiguous. Genre subversion.', 25, '20–30 min', 'Pencil and paper', 'Traditional fairy tale with a twist: the villain wins, the hero fails, the ending is ambiguous. Genre subversion.'),
  ('punctuation-colon-and-semicolon-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Punctuation: Colon and Semicolon', 'Colon introduces a list or explanation; semicolon joins two related clauses. Identify in texts; use in own writing.', 8, '5–10 min', 'Printed text + pencil and paper', 'Colon introduces a list or explanation; semicolon joins two related clauses. Identify in texts; use in own writing.'),
  ('compound-complex-sentences-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Compound-Complex Sentences', 'Although she was tired, she finished her work, and then she slept.'' Subordinate + coordinate clauses combined.', 8, '5–10 min', 'Pencil and paper', 'Although she was tired, she finished her work, and then she slept.'' Subordinate + coordinate clauses combined.'),
  ('write-a-song-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Write a Song', 'Verse-chorus structure, 4 lines per section, end rhyme or near-rhyme. Setting own words to a simple self-composed melody.', 18, '15–20 min', 'Pencil and paper', 'Verse-chorus structure, 4 lines per section, end rhyme or near-rhyme. Setting own words to a simple self-composed melody.'),
  ('critical-reading-author-s-purpose-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Critical Reading (Author''s Purpose)', 'Why did the author write this? Who is the intended audience? What do they want you to believe?'' Critical literacy.', 13, '10–15 min', 'Any persuasive text', 'Why did the author write this? Who is the intended audience? What do they want you to believe?'' Critical literacy.'),
  ('start-a-reading-journal-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Start a Reading Journal', 'After each chapter: one event you remember, one thing you''re wondering, one connection to your life.', 8, '5–10 min', 'Journal + pencil', 'After each chapter: one event you remember, one thing you''re wondering, one connection to your life.'),
  ('descriptive-writing-senses-only-y6_0', 'communication'::domain, 'y6_0'::age_band, 'Descriptive Writing (Senses Only)', 'Describe a place using only sensory details — no adjectives like ''nice'' or ''good.'' Specific sensory language.', 13, '10–15 min', 'Pencil and paper + a chosen place', 'Describe a place using only sensory details — no adjectives like ''nice'' or ''good.'' Specific sensory language.'),
  ('percentages-of-amounts-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Percentages of Amounts', '20% of 50 = 10. Find 10%, then double. Percentages in real contexts: sale price, tip, score.', 8, '5–10 min', 'Pencil and paper', '20% of 50 = 10. Find 10%, then double. Percentages in real contexts: sale price, tip, score.'),
  ('roman-numerals-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Roman Numerals', 'I, V, X, L, C, D, M. Read and write years in Roman numerals. Historical + mathematical literacy.', 7, '5–8 min', 'None', 'I, V, X, L, C, D, M. Read and write years in Roman numerals. Historical + mathematical literacy.'),
  ('surface-area-cube-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Surface Area (Cube)', 'Unfold a cube: how many faces? Each face''s area × 6. Net of a 3D shape is spatial reasoning.', 8, '5–10 min', 'Paper, scissors, ruler', 'Unfold a cube: how many faces? Each face''s area × 6. Net of a 3D shape is spatial reasoning.'),
  ('economics-supply-and-demand-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Economics: Supply and Demand', 'If there''s lots of something, the price goes down. If there''s little, it goes up. Real-world example: market visit.', 13, '10–15 min', 'None (or market visit)', 'If there''s lots of something, the price goes down. If there''s little, it goes up. Real-world example: market visit.'),
  ('the-scientific-method-full-cycle-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'The Scientific Method (Full Cycle)', 'Question → Research → Hypothesis → Experiment → Analyse → Conclude → Report. Run a full cycle on one question.', 25, '20–30 min', 'Experiment materials (chosen by child)', 'Question → Research → Hypothesis → Experiment → Analyse → Conclude → Report. Run a full cycle on one question.'),
  ('human-rights-5-basic-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Human Rights (5 Basic)', 'Name 5 universal human rights and give a real example of each. Rights as a concept before civics education.', 8, '5–10 min', 'None', 'Name 5 universal human rights and give a real example of each. Rights as a concept before civics education.'),
  ('self-assess-academic-work-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Self-Assess Academic Work', 'Grade your own work before seeing an adult''s assessment. Where did your assessment and theirs differ? Why?', 13, '10–15 min', 'Own piece of work', 'Grade your own work before seeing an adult''s assessment. Where did your assessment and theirs differ? Why?'),
  ('manage-long-term-projects-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Manage Long-Term Projects', 'A project with a 2-week deadline: plan backwards from deadline to identify daily/weekly tasks.', null, 'Ongoing', 'None', 'A project with a 2-week deadline: plan backwards from deadline to identify daily/weekly tasks.'),
  ('cross-cultural-friendship-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Cross-Cultural Friendship', 'Actively build a friendship with someone from a different background, city, or school. Intentional social expansion.', null, 'Ongoing', 'None', 'Actively build a friendship with someone from a different background, city, or school. Intentional social expansion.'),
  ('compassion-vs-pity-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Compassion vs Pity', 'What''s the difference between feeling sorry for someone and actually helping them?'' Compassion as active.', 8, '5–10 min', 'None', 'What''s the difference between feeling sorry for someone and actually helping them?'' Compassion as active.'),
  ('handle-a-public-mistake-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Handle a Public Mistake', 'When you get something wrong in front of others: stay calm, acknowledge, correct, continue. Public error management.', null, 'Ongoing', 'None', 'When you get something wrong in front of others: stay calm, acknowledge, correct, continue. Public error management.'),
  ('understand-privilege-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Understand Privilege', 'What do we have that others don''t, through no effort of our own?'' Age-appropriate awareness of luck and circumstance.', 8, '5–10 min', 'None', 'What do we have that others don''t, through no effort of our own?'' Age-appropriate awareness of luck and circumstance.'),
  ('build-a-solar-oven-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Build a Solar Oven', 'Box, foil, clingfilm. Heat builds up and cooks food slowly. Solar energy + thermodynamics.', 25, '20–30 min', 'Cardboard box, foil, clingfilm, food to cook', 'Box, foil, clingfilm. Heat builds up and cooks food slowly. Solar energy + thermodynamics.'),
  ('grow-crystals-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Grow Crystals', 'Dissolve salt or sugar in hot water; let cool slowly on a string. Crystal formation as ordered molecular structure.', null, 'Ongoing', 'Salt or sugar, water, jar, string', 'Dissolve salt or sugar in hot water; let cool slowly on a string. Crystal formation as ordered molecular structure.'),
  ('make-a-pinhole-camera-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Make a Pinhole Camera', 'Pinhole in a dark box projects an inverted image. Optics: light travels in straight lines.', 18, '15–20 min', 'Dark box, foil, pin, tracing paper', 'Pinhole in a dark box projects an inverted image. Optics: light travels in straight lines.'),
  ('soap-making-cold-process-simplified-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Soap Making (Cold Process, Simplified)', 'Glycerine melt-and-pour soap with added scent and colour. Chemistry: saponification principle accessible version.', 25, '20–30 min', 'Glycerine soap base, essential oil, colour, mould', 'Glycerine melt-and-pour soap with added scent and colour. Chemistry: saponification principle accessible version.'),
  ('textile-printing-screen-y6_0', 'cognitive'::domain, 'y6_0'::age_band, 'Textile Printing (Screen)', 'Stretch fabric over a frame; apply paint through a stencil. Screen printing is industrial design made accessible.', 18, '15–20 min', 'Fabric, frame, stencil, fabric paint', 'Stretch fabric over a frame; apply paint through a stencil. Screen printing is industrial design made accessible.'),
  ('budget-for-a-week-s-meals-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Budget for a Week''s Meals', 'Plan a week of meals for the family within a set budget. Arithmetic + nutrition knowledge + planning combined.', 18, '15–20 min', 'Pencil, paper, budget amount', 'Plan a week of meals for the family within a set budget. Arithmetic + nutrition knowledge + planning combined.'),
  ('cook-from-a-recipe-independently-y6_0', 'social_emotional'::domain, 'y6_0'::age_band, 'Cook from a Recipe (Independently)', 'Choose a recipe, gather ingredients, cook from start to finish without help. Culinary literacy + independence.', 38, '30–45 min', 'Recipe book + kitchen access', 'Choose a recipe, gather ingredients, cook from start to finish without help. Culinary literacy + independence.'),
  ('field-sport-60-minutes-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Field Sport (60 Minutes)', 'Play a full 60-minute session of a team sport with proper rules, positions, and substitutions.', 60, '60–60 min', 'Sport-specific equipment + players', 'Play a full 60-minute session of a team sport with proper rules, positions, and substitutions.'),
  ('swim-flip-turn-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Swim: Flip Turn', 'Tumble turn at the pool wall: flip, push, glide, resume stroke. Technical swimming milestone.', 18, '15–20 min', 'Swimming pool', 'Tumble turn at the pool wall: flip, push, glide, resume stroke. Technical swimming milestone.'),
  ('cycling-descent-control-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Cycling: Descent Control', 'Control speed on a long downhill: brake timing, body position, steering. Downhill safety = motor + judgement.', 18, '15–20 min', 'Bicycle + hill', 'Control speed on a long downhill: brake timing, body position, steering. Downhill safety = motor + judgement.'),
  ('gymnastics-walkover-or-backbend-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Gymnastics: Walkover or Backbend', 'Back walkover or front walkover. Full spinal flexibility + weight-bearing in back-extended position.', 13, '10–15 min', 'Soft mat', 'Back walkover or front walkover. Full spinal flexibility + weight-bearing in back-extended position.'),
  ('athletics-800m-run-paced-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Athletics: 800m Run (Paced)', 'Run 800 m with pacing strategy: don''t sprint the first lap. Pacing is a cognitive and physical skill simultaneously.', 8, '5–10 min', 'Track or open space', 'Run 800 m with pacing strategy: don''t sprint the first lap. Pacing is a cognitive and physical skill simultaneously.'),
  ('basketball-dribble-and-shoot-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Basketball Dribble and Shoot', 'Dribble around a defender and shoot. Game-like combination rather than isolated skill practice.', 13, '10–15 min', 'Basketball + basket (or improvised)', 'Dribble around a defender and shoot. Game-like combination rather than isolated skill practice.'),
  ('surfing-if-coastal-or-bodyboard-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Surfing (If Coastal) or Bodyboard', 'Balance on a moving water surface. The most demanding vestibular and proprioceptive challenge available.', 38, '30–45 min', 'Board + sea access', 'Balance on a moving water surface. The most demanding vestibular and proprioceptive challenge available.'),
  ('martial-arts-sparring-light-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Martial Arts Sparring (Light)', 'Supervised light sparring. Reading an opponent + responding in real time = the highest-level motor planning.', 18, '15–20 min', 'Partner + instructor', 'Supervised light sparring. Reading an opponent + responding in real time = the highest-level motor planning.'),
  ('write-a-complete-short-story-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Write a Complete Short Story', 'A complete, edited short story: 1500 words. Character, conflict, resolution — revised twice before considered done.', 38, '30–45 min', 'Pencil and paper', 'A complete, edited short story: 1500 words. Character, conflict, resolution — revised twice before considered done.'),
  ('wearable-tech-design-paper-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Wearable Tech Design (Paper)', 'Design a device that could go on the body: what does it do, how is it powered, what problem does it solve?', 18, '15–20 min', 'Drawing materials', 'Design a device that could go on the body: what does it do, how is it powered, what problem does it solve?'),
  ('book-binding-pamphlet-stitch-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Book Binding (Pamphlet Stitch)', 'Fold and stitch a 16-page booklet with a pamphlet stitch. The book''s structure becomes comprehensible.', 25, '20–30 min', 'Paper, needle, wax thread, bone folder', 'Fold and stitch a 16-page booklet with a pamphlet stitch. The book''s structure becomes comprehensible.'),
  ('make-a-diorama-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Make a Diorama', 'A 3D scene in a box: painted background, layered paper elements, miniature figures. Theatrical design thinking.', 25, '20–30 min', 'Cardboard box, paint, paper, small objects', 'A 3D scene in a box: painted background, layered paper elements, miniature figures. Theatrical design thinking.'),
  ('weaving-rigid-heddle-loom-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Weaving: Rigid Heddle Loom', 'Simple table loom: warp, weave, beat, advance. The structure of cloth becomes visible and learnable.', 38, '30–45 min', 'Rigid heddle loom (or cardboard loom)', 'Simple table loom: warp, weave, beat, advance. The structure of cloth becomes visible and learnable.'),
  ('calligraphy-full-alphabet-y6_3', 'motor'::domain, 'y6_3'::age_band, 'Calligraphy: Full Alphabet', 'Write the full lowercase alphabet in an italic calligraphic hand. Letterform + pressure + consistency.', 25, '20–30 min', 'Calligraphy pen or marker, paper', 'Write the full lowercase alphabet in an italic calligraphic hand. Letterform + pressure + consistency.'),
  ('novel-3-chapters-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Novel: 3 Chapters', 'Write 3 chapters of an intended longer novel. Sustaining characters across chapters requires planning and consistency.', 38, '30–45 min', 'Pencil and paper', 'Write 3 chapters of an intended longer novel. Sustaining characters across chapters requires planning and consistency.'),
  ('socratic-seminar-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Socratic Seminar', 'Guided discussion of a big question with 3+ people: ''Is it ever right to break a rule?'' Listen and build on others.', 25, '20–30 min', 'None', 'Guided discussion of a big question with 3+ people: ''Is it ever right to break a rule?'' Listen and build on others.'),
  ('write-a-speech-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Write a Speech', 'A 400-word speech on a real topic. Opening hook + 3 arguments + call to action. Rhetoric as a skill.', 18, '15–20 min', 'Pencil and paper', 'A 400-word speech on a real topic. Opening hook + 3 arguments + call to action. Rhetoric as a skill.'),
  ('literary-devices-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Literary Devices', 'Metaphor, simile, personification, alliteration, onomatopoeia — identify and use all 5 in a single paragraph.', 13, '10–15 min', 'Pencil and paper', 'Metaphor, simile, personification, alliteration, onomatopoeia — identify and use all 5 in a single paragraph.'),
  ('letter-to-future-self-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Letter to Future Self', 'Write a letter to open in 5 years: who you are now, what you hope for, what you worry about.', 13, '10–15 min', 'Pencil, paper, envelope', 'Write a letter to open in 5 years: who you are now, what you hope for, what you worry about.'),
  ('analyse-a-speech-historical-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Analyse a Speech (Historical)', 'Read a famous speech. Identify: the audience, the purpose, 2 rhetorical devices, the call to action.', 13, '10–15 min', 'Printed speech text', 'Read a famous speech. Identify: the audience, the purpose, 2 rhetorical devices, the call to action.'),
  ('collaborative-story-writing-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Collaborative Story Writing', 'Write alternating chapters with a parent or friend: one person writes chapter 1, the other writes chapter 2.', 25, '20–30 min', 'Pencil and paper (shared)', 'Write alternating chapters with a parent or friend: one person writes chapter 1, the other writes chapter 2.'),
  ('write-a-research-essay-y6_3', 'communication'::domain, 'y6_3'::age_band, 'Write a Research Essay', '400 words with an argument, 3 pieces of evidence from different sources, and a conclusion. Academic writing beginning.', 25, '20–30 min', 'Reference materials + pencil and paper', '400 words with an argument, 3 pieces of evidence from different sources, and a conclusion. Academic writing beginning.'),
  ('ratio-and-proportion-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Ratio and Proportion', 'If 3 cups make 1 batch, how many cups for 2 batches? Proportional reasoning in cooking + mathematics.', 8, '5–10 min', 'Recipe + cooking context', 'If 3 cups make 1 batch, how many cups for 2 batches? Proportional reasoning in cooking + mathematics.'),
  ('angles-measuring-with-protractor-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Angles: Measuring with Protractor', 'Measure and draw angles to within 5 degrees. Protractor use = spatial measurement tool.', 8, '5–10 min', 'Protractor, ruler, pencil, paper', 'Measure and draw angles to within 5 degrees. Protractor use = spatial measurement tool.'),
  ('prime-numbers-1-50-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Prime Numbers (1–50)', 'Identify prime numbers to 50 using the Sieve of Eratosthenes. Pattern-based mathematical discovery.', 13, '10–15 min', 'Grid paper', 'Identify prime numbers to 50 using the Sieve of Eratosthenes. Pattern-based mathematical discovery.'),
  ('volcanoes-and-plate-tectonics-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Volcanoes and Plate Tectonics', 'Why do volcanoes happen? Plate tectonics model. Geography + geology + scale comprehension.', 8, '5–10 min', 'None', 'Why do volcanoes happen? Plate tectonics model. Geography + geology + scale comprehension.'),
  ('photosynthesis-equation-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Photosynthesis Equation', 'CO2 + water + light → glucose + oxygen. The equation of life: every plant, every breath.', 7, '5–8 min', 'None', 'CO2 + water + light → glucose + oxygen. The equation of life: every plant, every breath.'),
  ('historical-empathy-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Historical Empathy', 'Put yourself in [historical person''s] position. What would you have done? What did they know that we don''t?''', 13, '10–15 min', 'Historical reference or book', 'Put yourself in [historical person''s] position. What would you have done? What did they know that we don''t?'''),
  ('manage-peer-pressure-practice-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Manage Peer Pressure (Practice)', 'Role-play 3 peer pressure scenarios. Practise saying no in different ways: firm, funny, deflecting, leaving.', 13, '10–15 min', 'None', 'Role-play 3 peer pressure scenarios. Practise saying no in different ways: firm, funny, deflecting, leaving.'),
  ('understand-anxiety-own-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Understand Anxiety (Own)', 'What does worry feel like in your body? Where does it live? What are you most worried about right now?''', 8, '5–10 min', 'None', 'What does worry feel like in your body? Where does it live? What are you most worried about right now?'''),
  ('become-a-good-loser-and-a-good-winner-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Become a Good Loser and a Good Winner', 'Both in the same session: play a game, win one, lose one, respond to each with class. Practice, not performance.', 18, '15–20 min', 'Any competitive game', 'Both in the same session: play a game, win one, lose one, respond to each with class. Practice, not performance.'),
  ('notice-systemic-unfairness-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Notice Systemic Unfairness', 'Why might some people have more advantages than others from the start?'' Beginning structural thinking about society.', 8, '5–10 min', 'None', 'Why might some people have more advantages than others from the start?'' Beginning structural thinking about society.'),
  ('own-your-mistakes-publicly-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Own Your Mistakes Publicly', 'When you''ve done something wrong that others know about: acknowledge it without excessive excuse-making.', null, 'Ongoing', 'None', 'When you''ve done something wrong that others know about: acknowledge it without excessive excuse-making.'),
  ('reciprocity-in-relationships-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Reciprocity in Relationships', 'What have you given in your closest friendship this week? What have you received?'' Friendship as a two-way exchange.', 7, '5–8 min', 'None', 'What have you given in your closest friendship this week? What have you received?'' Friendship as a two-way exchange.'),
  ('hydroponics-simple-setup-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Hydroponics (Simple Setup)', 'Grow plants in water + nutrient solution without soil. Modern agriculture + biology + systematic care.', null, 'Ongoing', 'Container, water, plant food, seeds', 'Grow plants in water + nutrient solution without soil. Modern agriculture + biology + systematic care.'),
  ('electrolysis-salt-water-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Electrolysis (Salt Water)', 'Salt water + two pencils + battery = bubbles of hydrogen and oxygen. Electricity splits water. Simple electrolysis.', 13, '10–15 min', 'Salt, water, pencils, battery + wires', 'Salt water + two pencils + battery = bubbles of hydrogen and oxygen. Electricity splits water. Simple electrolysis.'),
  ('make-a-spectroscope-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Make a Spectroscope', 'CD + cardboard box + light source. Split white light into the spectrum. Optics: dispersion of light.', 18, '15–20 min', 'CD, cardboard box, light', 'CD + cardboard box + light source. Split white light into the spectrum. Optics: dispersion of light.'),
  ('felting-wet-felting-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Felting (Wet Felting)', 'Wet felting: wool + hot water + soap, agitate until fibres lock. The science of fibre entanglement.', 25, '20–30 min', 'Wool roving, soap, hot water, bubble wrap', 'Wet felting: wool + hot water + soap, agitate until fibres lock. The science of fibre entanglement.'),
  ('ethnobotany-walk-y6_3', 'cognitive'::domain, 'y6_3'::age_band, 'Ethnobotany Walk', 'Walk through a local area: identify plants with traditional or practical uses. Local plant knowledge as science.', 25, '20–30 min', 'Field guide or elder knowledge', 'Walk through a local area: identify plants with traditional or practical uses. Local plant knowledge as science.'),
  ('financial-literacy-saving-and-interest-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Financial Literacy: Saving and Interest', 'If you save 100 Rs and earn 5% interest per year, how much do you have after a year? Simple interest concept.', 8, '5–10 min', 'Pencil and paper', 'If you save 100 Rs and earn 5% interest per year, how much do you have after a year? Simple interest concept.'),
  ('cook-an-international-meal-y6_3', 'social_emotional'::domain, 'y6_3'::age_band, 'Cook an International Meal', 'Full meal from another country: recipe research, shopping, cooking, plating. Culinary geography.', 38, '30–45 min', 'Recipe + ingredients', 'Full meal from another country: recipe research, shopping, cooking, plating. Culinary geography.'),
  ('design-a-sport-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Design a Sport', 'Invent a new sport: rules, equipment, team size, scoring. Systems thinking + creativity + fairness all embedded.', 25, '20–30 min', 'Paper for rules, improvised equipment', 'Invent a new sport: rules, equipment, team size, scoring. Systems thinking + creativity + fairness all embedded.'),
  ('swimming-racing-dive-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Swimming: Racing Dive', 'Competitive racing dive from the blocks (or pool edge). Explosive entry + streamline = technical swimming milestone.', 13, '10–15 min', 'Swimming pool', 'Competitive racing dive from the blocks (or pool edge). Explosive entry + streamline = technical swimming milestone.'),
  ('cycle-touring-day-trip-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Cycle Touring (Day Trip)', 'Plan and execute a 10+ km cycling day trip with stops. Navigation, stamina, rest planning.', 105, '90–120 min', 'Bicycle, water, snack, route plan', 'Plan and execute a 10+ km cycling day trip with stops. Navigation, stamina, rest planning.'),
  ('advanced-gymnastics-sequence-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Advanced Gymnastics Sequence', '7-element floor sequence with transitions. Choreographed gymnastics: the motor elements are now the canvas, not the goal.', 18, '15–20 min', 'Soft floor surface', '7-element floor sequence with transitions. Choreographed gymnastics: the motor elements are now the canvas, not the goal.'),
  ('trail-running-3-km-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Trail Running (3 km)', 'Run on uneven terrain for 3 km. Trail running recruits far more stabilising muscles than road running.', 25, '20–30 min', 'Trail (park or natural path)', 'Run on uneven terrain for 3 km. Trail running recruits far more stabilising muscles than road running.'),
  ('yoga-flow-10-poses-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Yoga Flow (10 Poses)', '10-pose yoga sequence from memory, held 3 breaths each. Memory + breath + body alignment combined.', 13, '10–15 min', 'None', '10-pose yoga sequence from memory, held 3 breaths each. Memory + breath + body alignment combined.'),
  ('tennis-serve-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Tennis: Serve', 'Continental grip serve: toss, trophy position, contact, follow through. The serve is the most complex single stroke in tennis.', 13, '10–15 min', 'Racket, ball', 'Continental grip serve: toss, trophy position, contact, follow through. The serve is the most complex single stroke in tennis.'),
  ('ultimate-frisbee-full-game-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Ultimate Frisbee (Full Game)', 'Full game with disc rules, positions, and spirit of the game. Ultimate has a unique self-refereed model.', 25, '20–30 min', 'Frisbee + players', 'Full game with disc rules, positions, and spirit of the game. Ultimate has a unique self-refereed model.'),
  ('write-a-science-fiction-story-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Write a Science Fiction Story', 'Set in a plausible future world. Science underpins the fiction: what technology exists, why, and what problem it creates.', 25, '20–30 min', 'Pencil and paper', 'Set in a plausible future world. Science underpins the fiction: what technology exists, why, and what problem it creates.'),
  ('pottery-wheel-thrown-supervised-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Pottery: Wheel-Thrown (Supervised)', 'Supervised session on a potter''s wheel. Centring clay on a moving wheel is the most demanding fine motor task in craft.', 38, '30–45 min', 'Potter''s wheel + clay (art school or studio)', 'Supervised session on a potter''s wheel. Centring clay on a moving wheel is the most demanding fine motor task in craft.'),
  ('knitting-first-garment-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Knitting: First Garment', 'Knit a small rectangular scarf or wash cloth: 20 stitches, 40 rows. A complete, usable knitted object.', 38, '30–45 min', 'Yarn, needles (large)', 'Knit a small rectangular scarf or wash cloth: 20 stitches, 40 rows. A complete, usable knitted object.'),
  ('build-an-app-no-code-platform-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Build an App (No-Code Platform)', 'Build a functional app using a no-code platform. Real-world product: what problem does it solve?', 38, '30–45 min', 'Computer + no-code app platform (MIT App Inventor)', 'Build a functional app using a no-code platform. Real-world product: what problem does it solve?'),
  ('map-making-cartography-project-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Map-Making (Cartography Project)', 'Draw an imaginary world with 5 regions, a legend, a scale, compass rose, and geographic features.', 25, '20–30 min', 'Paper, pencil, ruler, coloured pens', 'Draw an imaginary world with 5 regions, a legend, a scale, compass rose, and geographic features.'),
  ('make-a-documentary-short-y6_6', 'motor'::domain, 'y6_6'::age_band, 'Make a Documentary (Short)', 'Plan, film, and edit a 2-minute documentary about a local topic. Visual storytelling + interviewing + editing.', 25, '20–30 min', 'Phone for filming', 'Plan, film, and edit a 2-minute documentary about a local topic. Visual storytelling + interviewing + editing.'),
  ('write-a-mystery-story-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Write a Mystery Story', 'A mystery requires: a mystery, red herrings, clues, a reveal, and a resolution. Plotting in reverse: start with the answer.', 25, '20–30 min', 'Pencil and paper', 'A mystery requires: a mystery, red herrings, clues, a reveal, and a resolution. Plotting in reverse: start with the answer.'),
  ('debate-cross-examination-style-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Debate (Cross-Examination Style)', 'Statement + cross-examination. One side asks targeted questions to undermine the other''s argument. Advanced debate.', 18, '15–20 min', 'None', 'Statement + cross-examination. One side asks targeted questions to undermine the other''s argument. Advanced debate.'),
  ('write-a-personal-manifesto-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Write a Personal Manifesto', 'These are the things I believe, the things I value, and the kind of person I am working to be.'' Identity in writing.', 13, '10–15 min', 'Pencil and paper', 'These are the things I believe, the things I value, and the kind of person I am working to be.'' Identity in writing.'),
  ('read-and-discuss-a-banned-book-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Read and Discuss a Banned Book', 'Read (or excerpt of) a book that has been banned or challenged. Why? What does this tell us about society?', 18, '15–20 min', 'Age-appropriate controversial/challenged book', 'Read (or excerpt of) a book that has been banned or challenged. Why? What does this tell us about society?'),
  ('epistolary-story-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Epistolary Story', 'A story told entirely through letters, emails, or diary entries. A distinct narrative structure with its own rules.', 18, '15–20 min', 'Pencil and paper', 'A story told entirely through letters, emails, or diary entries. A distinct narrative structure with its own rules.'),
  ('etymology-research-project-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Etymology Research Project', 'Choose 20 words from a single field (cooking, sport, medicine) and trace their origins. Language as historical record.', 25, '20–30 min', 'Etymological dictionary or resource', 'Choose 20 words from a single field (cooking, sport, medicine) and trace their origins. Language as historical record.'),
  ('write-a-found-poem-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Write a Found Poem', 'Take a news article and isolate words to create a poem. Found poetry reveals the poetry already in language.', 13, '10–15 min', 'Newspaper or magazine article + pencil', 'Take a news article and isolate words to create a poem. Found poetry reveals the poetry already in language.'),
  ('understand-narrative-unreliability-y6_6', 'communication'::domain, 'y6_6'::age_band, 'Understand Narrative Unreliability', 'Is the narrator telling us everything? Are they being honest?'' Unreliable narrator as a literary device.', 8, '5–10 min', 'Book or story extract', 'Is the narrator telling us everything? Are they being honest?'' Unreliable narrator as a literary device.'),
  ('square-roots-estimation-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Square Roots (Estimation)', 'What is the square root of 50? Between 7 (49) and 8 (64) — closer to 7. Estimation + number sense combined.', 8, '5–10 min', 'Pencil and paper', 'What is the square root of 50? Between 7 (49) and 8 (64) — closer to 7. Estimation + number sense combined.'),
  ('coordinate-geometry-4-quadrants-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Coordinate Geometry (4 Quadrants)', 'Plot points in all 4 quadrants of a coordinate plane. Negative coordinates = number line extended into space.', 8, '5–10 min', 'Graph paper', 'Plot points in all 4 quadrants of a coordinate plane. Negative coordinates = number line extended into space.'),
  ('speed-distance-time-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Speed, Distance, Time', 'If I travel 60 km at 30 km/h, how long does it take? The formula and its rearrangements.', 8, '5–10 min', 'Pencil and paper', 'If I travel 60 km at 30 km/h, how long does it take? The formula and its rearrangements.'),
  ('genetics-introduction-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Genetics Introduction', 'Why do children look like parents? Genes carry information. Dominant and recessive traits with Mendel''s peas.', 8, '5–10 min', 'None', 'Why do children look like parents? Genes carry information. Dominant and recessive traits with Mendel''s peas.'),
  ('climate-science-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Climate Science', 'Carbon dioxide + solar radiation + greenhouse effect. How does human activity change the climate? Evidence-based.', 8, '5–10 min', 'None', 'Carbon dioxide + solar radiation + greenhouse effect. How does human activity change the climate? Evidence-based.'),
  ('philosophy-of-mind-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Philosophy of Mind', 'How do you know other people are conscious? How do you know YOU are conscious?'' Philosophy as lived inquiry.', 13, '10–15 min', 'None', 'How do you know other people are conscious? How do you know YOU are conscious?'' Philosophy as lived inquiry.'),
  ('emotional-regulation-toolkit-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Emotional Regulation Toolkit', 'Map your own regulation tools: 5 things that calm you, 3 things that energise you, 2 things that ground you. Personal toolkit.', 13, '10–15 min', 'Paper for mapping', 'Map your own regulation tools: 5 things that calm you, 3 things that energise you, 2 things that ground you. Personal toolkit.'),
  ('understand-cognitive-biases-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Understand Cognitive Biases', 'Confirmation bias: we see what we already believe. Provide an example from own life. Self-awareness as critical thinking.', 8, '5–10 min', 'None', 'Confirmation bias: we see what we already believe. Provide an example from own life. Self-awareness as critical thinking.'),
  ('practice-radical-honesty-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Practice Radical Honesty', 'One conversation where you say exactly what you think (with kindness). Honesty as a practice, not just a value.', 8, '5–10 min', 'None', 'One conversation where you say exactly what you think (with kindness). Honesty as a practice, not just a value.'),
  ('build-a-community-project-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Build a Community Project', 'Identify a small problem in your community and design a solution. Civic agency: from observation to action.', 18, '15–20 min', 'Paper for planning', 'Identify a small problem in your community and design a solution. Civic agency: from observation to action.'),
  ('understand-the-news-cycle-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Understand the News Cycle', 'Read the same story from two different publications. What''s different? Journalism, framing, and editorial perspective.', 13, '10–15 min', 'Two news sources', 'Read the same story from two different publications. What''s different? Journalism, framing, and editorial perspective.'),
  ('comfort-someone-in-grief-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Comfort Someone in Grief', 'When someone you know is grieving: sit with them, listen, don''t fix. The skill of simply being present.', null, 'Ongoing', 'None', 'When someone you know is grieving: sit with them, listen, don''t fix. The skill of simply being present.'),
  ('build-a-radio-crystal-set-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Build a Radio (Crystal Set)', 'Crystal radio receiver: wire antenna, capacitor, crystal diode, earphone. Receives AM radio without power. Electromagnetic field science.', 25, '20–30 min', 'Crystal radio kit (basic components)', 'Crystal radio receiver: wire antenna, capacitor, crystal diode, earphone. Receives AM radio without power. Electromagnetic field science.'),
  ('make-indigo-dye-plant-based-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Make Indigo Dye (Plant-Based)', 'Process indigo leaves (or buy powder) to create a vat. Dye cloth. Reduction chemistry + ancient textile tradition.', 38, '30–45 min', 'Indigo leaves or powder, water, reducing agent', 'Process indigo leaves (or buy powder) to create a vat. Dye cloth. Reduction chemistry + ancient textile tradition.'),
  ('soil-science-investigation-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Soil Science Investigation', 'Test soil pH, texture, and drainage in 3 different spots. What do the results mean for growing food?', 18, '15–20 min', 'Soil samples, pH strip, water', 'Test soil pH, texture, and drainage in 3 different spots. What do the results mean for growing food?'),
  ('build-a-kite-from-scratch-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Build a Kite from Scratch', 'Bamboo + tissue paper + string + tail. Design it, test it, adjust it. Aerodynamics through iteration.', 25, '20–30 min', 'Bamboo, tissue paper, string, tape', 'Bamboo + tissue paper + string + tail. Design it, test it, adjust it. Aerodynamics through iteration.'),
  ('night-photography-y6_6', 'cognitive'::domain, 'y6_6'::age_band, 'Night Photography', 'Use a phone on night mode: photograph the moon, city lights, star trails (long exposure). Visual + astronomy.', 18, '15–20 min', 'Phone with night mode', 'Use a phone on night mode: photograph the moon, city lights, star trails (long exposure). Visual + astronomy.'),
  ('learn-basic-first-aid-certified-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Learn Basic First Aid (Certified)', 'Complete a basic first aid course (1-day). CPR, choking, burns, bleeding. Actual lifesaving capability.', null, 'Ongoing', 'First aid course', 'Complete a basic first aid course (1-day). CPR, choking, burns, bleeding. Actual lifesaving capability.'),
  ('manage-a-week-independently-y6_6', 'social_emotional'::domain, 'y6_6'::age_band, 'Manage a Week Independently', 'For one week, manage own morning routine, school bag, homework, and one household chore without reminders.', null, 'Ongoing', 'None', 'For one week, manage own morning routine, school bag, homework, and one household chore without reminders.'),
  ('coach-a-younger-team-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Coach a Younger Team', 'Organise and run a sports activity for 5–8 younger children. Leadership + pedagogy + patience combined.', 38, '30–45 min', 'Sport equipment + younger players', 'Organise and run a sports activity for 5–8 younger children. Leadership + pedagogy + patience combined.'),
  ('marathon-short-distance-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Marathon (Short Distance)', 'Run a 5-km ''marathon'' with pacing and recovery strategy. Goal-setting + physical training + completion.', 38, '30–45 min', 'Open space or road (supervised)', 'Run a 5-km ''marathon'' with pacing and recovery strategy. Goal-setting + physical training + completion.'),
  ('bicycle-maintenance-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Bicycle Maintenance', 'Fix a puncture, oil the chain, adjust the brakes. Understanding and maintaining one''s own tools.', 25, '20–30 min', 'Bicycle, tyre levers, pump, oil, cloth', 'Fix a puncture, oil the chain, adjust the brakes. Understanding and maintaining one''s own tools.'),
  ('sport-full-season-participation-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Sport: Full Season Participation', 'Commit to a sport for a full season. Regular training + team membership + end-of-season performance or competition.', null, 'Ongoing', 'Sport-specific equipment', 'Commit to a sport for a full season. Regular training + team membership + end-of-season performance or competition.'),
  ('swimming-medley-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Swimming: Medley', 'Individual medley: butterfly, backstroke, breaststroke, freestyle in sequence. The most technically demanding swimming achievement.', 18, '15–20 min', 'Swimming pool', 'Individual medley: butterfly, backstroke, breaststroke, freestyle in sequence. The most technically demanding swimming achievement.'),
  ('mountain-bike-trail-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Mountain Bike Trail', 'Trail mountain biking: technical terrain, root avoidance, off-camber sections. Mastery of cycling on a new surface.', 25, '20–30 min', 'Mountain bike + trail', 'Trail mountain biking: technical terrain, root avoidance, off-camber sections. Mastery of cycling on a new surface.'),
  ('dance-choreograph-for-an-audience-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Dance: Choreograph for an Audience', 'Choreograph a 2-minute dance piece and perform it for a real audience. Creative intention + public performance.', 25, '20–30 min', 'Music + performance space', 'Choreograph a 2-minute dance piece and perform it for a real audience. Creative intention + public performance.'),
  ('free-solo-climbing-bouldering-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Free Solo Climbing (Bouldering)', 'Unsupported bouldering at an indoor wall: read the route, solve it. Self-directed physical problem-solving.', 25, '20–30 min', 'Bouldering wall', 'Unsupported bouldering at an indoor wall: read the route, solve it. Self-directed physical problem-solving.'),
  ('write-a-novella-first-5000-words-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Write a Novella (First 5000 Words)', 'Begin a sustained long-form writing project. Plot outline, chapter plan, daily writing practice. Authorial identity.', 45, '30–60 min', 'Pencil and paper (or computer)', 'Begin a sustained long-form writing project. Plot outline, chapter plan, daily writing practice. Authorial identity.'),
  ('build-a-working-model-engine-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Build a Working Model Engine', 'Simple steam engine or electric motor model. How does energy convert into motion? Engineering science.', 38, '30–45 min', 'Kit or household materials (supervised)', 'Simple steam engine or electric motor model. How does energy convert into motion? Engineering science.'),
  ('ceramics-glazing-and-firing-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Ceramics: Glazing and Firing', 'Apply underglaze and overglaze to bisque-fired piece. Two-stage firing = colour chemistry through heat.', 38, '30–45 min', 'Bisque-fired piece, glazes, kiln (art school)', 'Apply underglaze and overglaze to bisque-fired piece. Two-stage firing = colour chemistry through heat.'),
  ('wiring-a-simple-plug-supervised-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Wiring a Simple Plug (Supervised)', 'Supervised: identify live, neutral, earth in a plug; connect correctly. Electrical safety + practical knowledge.', 18, '15–20 min', 'Old plug, wire, screwdriver (supervised)', 'Supervised: identify live, neutral, earth in a plug; connect correctly. Electrical safety + practical knowledge.'),
  ('photography-composition-rules-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Photography: Composition Rules', 'Rule of thirds, leading lines, framing. Apply all 3 in 5 intentional photos. Visual composition as deliberate craft.', 18, '15–20 min', 'Camera or phone', 'Rule of thirds, leading lines, framing. Apply all 3 in 5 intentional photos. Visual composition as deliberate craft.'),
  ('weave-a-rug-small-y6_9', 'motor'::domain, 'y6_9'::age_band, 'Weave a Rug (Small)', 'A small rug on a frame loom: warp and weft at density. Sustained repetitive fine motor over a physical project.', 45, '30–60 min', 'Frame loom, yarn', 'A small rug on a frame loom: warp and weft at density. Sustained repetitive fine motor over a physical project.'),
  ('read-literature-original-text-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Read Literature (Original Text)', 'Read an original, unabridged classic in full. Grapple with archaic language as a skill, not a barrier.', 25, '20–30 min', 'Classic novel in original text', 'Read an original, unabridged classic in full. Grapple with archaic language as a skill, not a barrier.'),
  ('write-a-formal-argument-essay-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Write a Formal Argument Essay', '800 words: thesis, 3 body paragraphs with evidence and counter-argument addressed, conclusion. University-essay structure.', 25, '20–30 min', 'Pencil and paper', '800 words: thesis, 3 body paragraphs with evidence and counter-argument addressed, conclusion. University-essay structure.'),
  ('public-speaking-external-audience-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Public Speaking (External Audience)', 'Present to an audience beyond family: school group, community, or recorded. Real audience = real feedback.', 15, '10–20 min', 'Prepared speech', 'Present to an audience beyond family: school group, community, or recorded. Real audience = real feedback.'),
  ('write-a-research-paper-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Write a Research Paper', 'Includes a bibliography, quotes with attribution, and a distinct argument. Academic writing conventions.', 25, '20–30 min', 'Reference materials + pencil and paper', 'Includes a bibliography, quotes with attribution, and a distinct argument. Academic writing conventions.'),
  ('translate-a-short-text-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Translate a Short Text', 'Translate a simple paragraph to/from a second language. Bilingual flexibility and linguistic comparison.', 13, '10–15 min', 'Short text + dictionary', 'Translate a simple paragraph to/from a second language. Bilingual flexibility and linguistic comparison.'),
  ('study-and-present-on-a-person-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Study and Present on a Person', 'In-depth research on one person: 10 facts, a timeline, one thing they changed. Oral presentation.', 18, '15–20 min', 'Reference materials', 'In-depth research on one person: 10 facts, a timeline, one thing they changed. Oral presentation.'),
  ('write-a-letter-to-an-authority-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Write a Letter to an Authority', 'Write a real letter (or email) to a local councillor, newspaper, or organisation about a real issue.', 18, '15–20 min', 'Pencil and paper or email access', 'Write a real letter (or email) to a local councillor, newspaper, or organisation about a real issue.'),
  ('read-and-discuss-a-dystopian-novel-y6_9', 'communication'::domain, 'y6_9'::age_band, 'Read and Discuss a Dystopian Novel', 'A gentle dystopian novel: what is the society afraid of? What does this tell us about our own world?', 18, '15–20 min', 'Age-appropriate dystopian novel', 'A gentle dystopian novel: what is the society afraid of? What does this tell us about our own world?'),
  ('algebra-linear-equations-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Algebra: Linear Equations', 'Solve 2x + 3 = 11. Two-step equations with one variable. Algebraic reasoning + inverse operations.', 8, '5–10 min', 'Pencil and paper', 'Solve 2x + 3 = 11. Two-step equations with one variable. Algebraic reasoning + inverse operations.'),
  ('statistics-mean-median-mode-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Statistics: Mean, Median, Mode', 'Calculate all three for a data set. When would each be misleading? Statistical literacy begins here.', 8, '5–10 min', 'Data set + pencil and paper', 'Calculate all three for a data set. When would each be misleading? Statistical literacy begins here.'),
  ('understand-compound-interest-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Understand Compound Interest', 'Interest on interest. Compare simple vs compound over 10 years. The most powerful concept in personal finance.', 8, '5–10 min', 'Pencil and paper', 'Interest on interest. Compare simple vs compound over 10 years. The most powerful concept in personal finance.'),
  ('philosophy-ethics-trolley-problem-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Philosophy: Ethics Trolley Problem', 'The trolley problem and its variants. There is no right answer — the process of reasoning is the point.', 13, '10–15 min', 'None', 'The trolley problem and its variants. There is no right answer — the process of reasoning is the point.'),
  ('evolution-natural-selection-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Evolution: Natural Selection', 'Survival of the fittest: variation, selection pressure, inherited advantage, generation change. Darwin''s mechanism.', 8, '5–10 min', 'None', 'Survival of the fittest: variation, selection pressure, inherited advantage, generation change. Darwin''s mechanism.'),
  ('study-a-civilisation-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Study a Civilisation', 'Choose one ancient civilisation: research government, economy, culture, fall. Historical systems thinking.', 18, '15–20 min', 'Reference book or supervised internet', 'Choose one ancient civilisation: research government, economy, culture, fall. Historical systems thinking.'),
  ('build-a-personal-vision-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Build a Personal Vision', 'What kind of person do I want to be at 18? At 30? What do I need to do to become that person?'' Long-range identity work.', 13, '10–15 min', 'None', 'What kind of person do I want to be at 18? At 30? What do I need to do to become that person?'' Long-range identity work.'),
  ('understand-your-own-learning-style-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Understand Your Own Learning Style', 'How do you learn best? What conditions make you most creative? What drains you? Self-awareness as meta-cognition.', 8, '5–10 min', 'None', 'How do you learn best? What conditions make you most creative? What drains you? Self-awareness as meta-cognition.'),
  ('lead-a-team-through-difficulty-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Lead a Team Through Difficulty', 'When a group project hits a problem: step up, identify the issue, suggest a path forward. Leadership in adversity.', null, 'Ongoing', 'None', 'When a group project hits a problem: step up, identify the issue, suggest a path forward. Leadership in adversity.'),
  ('understand-mental-health-continuum-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Understand Mental Health Continuum', 'Mental health is not binary — everyone is somewhere on a continuum. What affects yours? How do you maintain it?', 8, '5–10 min', 'None', 'Mental health is not binary — everyone is somewhere on a continuum. What affects yours? How do you maintain it?'),
  ('give-something-back-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Give Something Back', 'Identify a skill or resource you have and give it to someone who needs it. Generosity as identity, not event.', null, 'Ongoing', 'None', 'Identify a skill or resource you have and give it to someone who needs it. Generosity as identity, not event.'),
  ('identity-who-am-i-full-reflection-y6_9', 'social_emotional'::domain, 'y6_9'::age_band, 'Identity: Who Am I (Full Reflection)', 'Write or tell: your values, your strengths, your challenges, your culture, your aspirations. A portrait in words.', 18, '15–20 min', 'Paper and pencil (optional)', 'Write or tell: your values, your strengths, your challenges, your culture, your aspirations. A portrait in words.'),
  ('rocketry-baking-soda-vinegar-rocket-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Rocketry (Baking Soda + Vinegar Rocket)', 'Build a paper rocket body; launch with baking soda + vinegar. Newton''s 3rd law + trajectory + design iteration.', 18, '15–20 min', 'Paper, tape, baking soda, vinegar, cork', 'Build a paper rocket body; launch with baking soda + vinegar. Newton''s 3rd law + trajectory + design iteration.'),
  ('bread-fermentation-sourdough-starter-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Bread Fermentation (Sourdough Starter)', 'Cultivate a sourdough starter over 5 days. Microbiology: wild yeast + bacteria + time = leavening.', null, 'Ongoing', 'Flour, water, jar', 'Cultivate a sourdough starter over 5 days. Microbiology: wild yeast + bacteria + time = leavening.'),
  ('night-hike-moonlit-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Night Hike (Moonlit)', 'Hike 2 km at night using torchlight or moonlight. Sensory recalibration: vision changes, sound sharpens, fear and awe.', 38, '30–45 min', 'Torch, safe trail, adult accompaniment', 'Hike 2 km at night using torchlight or moonlight. Sensory recalibration: vision changes, sound sharpens, fear and awe.'),
  ('build-a-drone-simple-kit-y6_9', 'cognitive'::domain, 'y6_9'::age_band, 'Build a Drone (Simple Kit)', 'Assemble a simple drone kit. Lift, thrust, pitch, yaw, roll — four rotor forces that enable stable flight.', 38, '30–45 min', 'Simple drone kit', 'Assemble a simple drone kit. Lift, thrust, pitch, yaw, roll — four rotor forces that enable stable flight.'),
